            if (hasLeft && !hasRight) return { key: 'SOFA_CAMA_IZQ', label: 'SOFÁ CAMA BRAZO IZQUIERDO', rank: 10.5, stripTokens: ['SOFA', 'SOFAS', 'CAMA', 'CAMAS', 'CON', 'BRAZO', 'IZQUIERDO', 'IZQ'] };
