    const WOOD_SPECIES_CORE_RE = /\b(ROSA\s+MORADA|PAROTA|TZALAM|NOGAL|TECA|ENCINO|ROBLE|CEDRO|PINO|CAOBA|FRESNO|HAYA|OKUME|MAPLE|ABEDUL|PALO\s+DE\s+ROSA|MADERA|CHAPA|MELAMINA|MDF|TRIPLAY|ALAMO|BANAK|PRIMAVERA|CEREZO|EBANO|WENGUE|BAMBU)\b/i;
    const WOOD_FINISH_NAME_RE = /\b(TABACO|TACUBA|BELLOTA|ESPIGA|HABANO|CAMEL|GINGER|NOCHE|NUEZ)\b/i;
    const WOOD_PROVIDER_RE = /\b(BARSA|YOI|SKANOR|CHAVOYA|ARTEX|ATX|ARTC|KASAM|MOBEL\s+INN|BLOQUEART|CASA\s+AURA|REVICA|VANGARDI|LUX\s+FACTOR[IY]|LUIS\s+PEDRO|MR\s+FURNITURE)\b/i;
    const WOOD_DESCRIPTOR_ALLOWED_TOKENS = new Set([
        'ROSA', 'MORADA', 'PAROTA', 'TZALAM', 'NOGAL', 'TECA', 'ENCINO', 'ROBLE', 'CEDRO', 'PINO',
        'CAOBA', 'FRESNO', 'HAYA', 'OKUME', 'MAPLE', 'ABEDUL', 'PALO', 'TABACO', 'TACUBA', 'BELLOTA',
        'ESPIGA', 'HABANO', 'MADERA', 'CHAPA', 'MELAMINA', 'MDF', 'TRIPLAY', 'ALAMO', 'BANAK',
        'PRIMAVERA', 'CEREZO', 'EBANO', 'WENGUE', 'BAMBU', 'CAMEL', 'GINGER', 'NOCHE', 'NUEZ',
        'TONO', 'NATURAL', 'CLARO', 'CLARA', 'OSCURO', 'OSCURA', 'MATE', 'SEMI', 'BRILLANTE',
        'SATIN', 'SATINADO', 'SATINADA', 'ENTINTADO', 'ENTINTADA', 'ACEITE', 'WHITE', 'BLANCO',
        'BLANCA', 'NEGRO', 'NEGRA', 'CAFE', 'CHOCOLATE', 'MIEL', 'AHUMADO', 'AHUMADA', 'NOGALADO',
        'AVELLANA', 'CARAMELO', 'CENIZA', 'GRIS', 'BEIGE', 'DORADO', 'LACA', 'BARNIZ', 'ACABADO',
        'CEPILLADO', 'RUSTICO', 'RUSTICA', 'SOLIDA', 'SOLIDO', 'MACIZA', 'MACIZO', 'EN', 'CON',
        'SIN', 'DE', 'AL', 'DEL', 'LA', 'EL', 'Y', 'BASE', 'PATAS', 'CUBIERTA',
        'BARSA', 'YOI', 'SKANOR', 'CHAVOYA', 'ARTEX', 'ATX', 'ARTC', 'KASAM', 'MOBEL', 'INN',
        'BLOQUEART', 'CASA', 'AURA', 'REVICA', 'VANGARDI', 'LUX', 'FACTORI', 'FACTORY', 'LUIS',
        'PEDRO', 'MR', 'FURNITURE', 'HAKO', 'KAI', 'CREATA', 'MOBA', 'MONTE'
    ]);

    function isPureWoodDescriptor(rawText) {
        const norm = plainModelToken(rawText);
        if (!norm) return false;
        const hasCoreWood = WOOD_SPECIES_CORE_RE.test(norm) || (WOOD_FINISH_NAME_RE.test(norm) && WOOD_PROVIDER_RE.test(norm));
        if (!hasCoreWood) return false;
        const toks = norm.split(/\s+/).filter(Boolean);
        if (!toks.length) return false;
        for (let i = 0; i < toks.length; i++) {
            if (!WOOD_DESCRIPTOR_ALLOWED_TOKENS.has(toks[i])) return false;
        }
        return true;
    }

    function isWoodOnlyProductForFabricGuard(it) {
        if (!it) return false;
        const tlClean = cleanStr(it.tl);
        const ctClean = cleanStr(it.ct);
        const hasFabricCols = Boolean(
            (tlClean && !isPureWoodDescriptor(tlClean)) ||
            (ctClean && !isPureWoodDescriptor(ctClean))
        );
        if (hasFabricCols) return false;
        const catNorm = plainModelToken(it.c);
        const typeNameNorm = plainModelToken(cleanStr(it.tp) + ' ' + cleanStr(it.n));
        const hasUpholsteredHint = /\b(SILLA|SILLON|SOFA|SALA|LOVESEAT|LOVE\s+SEAT|MODULAR|CHAISE|COJIN|COJINES|CABECERA|CAMA|BANCO|TABURETE|PERIQUERA|POUF|PUF|OTTOMAN|OTOMAN|CAMASTRO|TAPIZ|TELA|PIEL|LINO|BOUCLE|VELVET|TERCIOPELO|CHENILLE|RECLINABLE|POLTRONA|BUTACA|BAUL)\b/i.test(typeNameNorm);
        if (hasUpholsteredHint) return false;
        if (catNorm === 'MESAS' || catNorm === 'MESAS DE CENTRO LATERALES' || catNorm === 'BUFETERAS CREDENZAS' || catNorm === 'ILUMINACION' || catNorm === 'ESPEJOS ARTE') return true;
        return /\b(MESA|COMEDOR|CREDENZA|BUFETERA|BURO|CONSOLA|ESCRITORIO|LIBRERO|MUEBLE\s+TV|PEDESTAL|BASE|CUBIERTA|ESPEJO|CUADRO|CAJONERA|COMODA|TOCADOR|VITRINA|CANTINA|BARRA|PERCHERO|REPISA|LAMPARA|CANDIL|ARBOTANTE|MACETA|FLORERO|JARRON|FOLLAJE|BOTELLA|ESCULTURA|RELOJ)\b/i.test(typeNameNorm);
    }

    function getVisualOverridePhotoUrl(overrideKey) {
        const k = String(overrideKey || '').trim().toUpperCase();
        if (!k) return '';
        if (invProductOverridesMap && typeof invProductOverridesMap === 'object' && Object.prototype.hasOwnProperty.call(invProductOverridesMap, k)) {
            const ovr = invProductOverridesMap[k];
            if (!ovr || ovr.status === 'ELIMINADO' || ovr.status === 'ARCHIVADO') return '';
            return sanitizeVisualOverrideUrl(cleanStr(ovr.note));
        }
        if (k.indexOf('VWOD:') === 0 && DEFAULT_WOOD_SWATCHES_CATALOG[k]) {
            return sanitizeVisualOverrideUrl(cleanStr(DEFAULT_WOOD_SWATCHES_CATALOG[k].note));
        }
        return '';
    }

    function getGroupVisualCoverPhotoUrl(groupKey) {
        return getVisualOverridePhotoUrl(buildVisualCoverOverrideKey(groupKey));
    }

    let _vfabIndexMapRef = null;
    let _vfabIndexEntries = [];
    const VFAB_GENERIC_SINGLE_TOKENS = new Set([
        'TELA', 'COLOR', 'ESTANDAR', 'MODULAR', 'SALA', 'SOFA', 'SILLON', 'SILLA',
        'DERECHO', 'IZQUIERDO', 'CENTRAL', 'CON', 'SIN', 'BRAZO', 'BRAZOS',
        'CLARO', 'OSCURO', 'NATURAL', 'MEDIO', 'NUEVO', 'NUEVA', 'LINO', 'PIEL'
    ]);
    // Colores/materiales genéricos que nunca deben quedar como 1 solo token en un VFAB (ej. "TELA BEIGE - LEONI" -> nunca colapsar a "BEIGE")
    const VFAB_GENERIC_SINGLE_COLOR_TOKENS = new Set([
        'BEIGE', 'BLANCO', 'BLANCA', 'WHITE', 'NEGRO', 'NEGRA', 'BLACK',
        'GRIS', 'GREY', 'GRAY', 'AZUL', 'BLUE', 'VERDE', 'GREEN',
        'ROJO', 'ROJA', 'RED', 'CAFE', 'BROWN', 'MARRON', 'ARENA', 'SAND',
        'CREMA', 'CREAM', 'HUESO', 'BONE', 'IVORY', 'MARFIL',
        'DORADO', 'ORO', 'GOLD', 'PLATA', 'SILVER', 'BRONCE', 'ROSA', 'PINK',
        'TERRACOTA', 'TAUPE', 'CAMEL', 'CHOCOLATE', 'OLIVO', 'OLIVE',
        'MOSTAZA', 'MUSTARD', 'OCRE', 'CRUDO', 'PERLA', 'PEARL',
        'SNOW', 'FLAX', 'ECRU', 'OAT', 'TOAST', 'ALABASTER',
        'PIEDRA', 'STONE', 'LINEN', 'COTTON', 'ALGODON', 'CUERDA',
        'CHARCOAL', 'PUTTY', 'DOVE', 'MINERAL'
    ]);

    function isGenericSingleFabricToken(tok) {
        return VFAB_GENERIC_SINGLE_TOKENS.has(tok) || VFAB_GENERIC_SINGLE_COLOR_TOKENS.has(tok);
    }

    function stripWoodNoiseFromFabricSwatchNorm(normText) {
        if (!normText) return '';
        const cleaned = String(normText)
            .replace(/\bROSA\s+MORADA(?:\s+(?:TONO\s+)?(?:NATURAL|BARSA|YOI|CHAVOYA|CLARA|OSCURA|NOGAL))?\b/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();
        return cleaned || normText;
    }

    function getUploadedFabricSwatchEntries() {
        if (!invProductOverridesMap || typeof invProductOverridesMap !== 'object') return [];
        if (_vfabIndexMapRef === invProductOverridesMap) return _vfabIndexEntries;
        const entries = [];
        const keys = Object.keys(invProductOverridesMap);
        for (let i = 0; i < keys.length; i++) {
            const k = String(keys[i] || '').trim().toUpperCase();
            if (k.indexOf('VFAB:') !== 0) continue;
            const ovr = invProductOverridesMap[k];
            if (!ovr || ovr.status === 'ELIMINADO' || ovr.status === 'ARCHIVADO') continue;
            const url = sanitizeVisualOverrideUrl(cleanStr(ovr.note));
            if (!url) continue;
            const rawLabel = cleanStr(ovr.name) || k.slice(5);
            const rawNorm = canonicalizeFabricAliases(plainModelToken(rawLabel));
            let normName = normalizeFabricLookupKey(rawLabel) || rawNorm;
            const rawTokens = rawNorm.split(/\s+/).filter(t => t.length >= 2);
            const normTokens = normName.split(/\s+/).filter(t => t.length >= 2);
            // Guardia de proveedor/modelo para telas o colores genéricos (ej. "VFAB:PIEL YOI" o "VFAB:TELA BEIGE - LEONI")
            if (normTokens.length === 1 && isGenericSingleFabricToken(normTokens[0]) && rawTokens.length >= 2) {
                normName = rawNorm;
            }
            // Limpiar ruido de madera incrustado en claves VFAB mixtas (ej. "OCASIONAL SAND 07 ROSA MORADA TONO NATURAL")
            normName = stripWoodNoiseFromFabricSwatchNorm(normName);
            const tokens = normName.split(/\s+/).filter(t => t.length >= 2);
            if (!normName || !tokens.length) continue;
            const sortedSig = tokens.slice().sort().join(' ');
            entries.push({
                overrideKey: k,
                label: rawLabel.toUpperCase(),
                normName: normName,
                tokens: tokens,
                sortedSig: sortedSig,
                url: url
            });
        }
        // Prefer more specific (more tokens / longer) fabric names first
        entries.sort((a, b) => (b.tokens.length - a.tokens.length) || (b.normName.length - a.normName.length));
        _vfabIndexMapRef = invProductOverridesMap;
        _vfabIndexEntries = entries;
        return entries;
    }

    function matchFabricTextAgainstUploadedSwatches(rawCandidateText) {
        if (isPureWoodDescriptor(rawCandidateText)) return null;
        const rawNorm = canonicalizeFabricAliases(plainModelToken(rawCandidateText));
        let cleanCand = normalizeFabricLookupKey(rawCandidateText) || rawNorm;
        if (isPureWoodDescriptor(cleanCand)) return null;
        const rawToks = rawNorm.split(/\s+/).filter(t => t.length >= 2);
        const cleanToks = cleanCand.split(/\s+/).filter(t => t.length >= 2);
        if (cleanToks.length === 1 && isGenericSingleFabricToken(cleanToks[0]) && rawToks.length >= 2) {
            cleanCand = rawNorm;
        }
        if (!cleanCand || cleanCand === 'ESTANDAR') return null;

        // 1) Exact override key match (both raw and canonical)
        const exactCandidates = [buildFabricSwatchOverrideKey(rawCandidateText), buildFabricSwatchOverrideKey(cleanCand)];
        for (let eIdx = 0; eIdx < exactCandidates.length; eIdx++) {
            const exactKey = exactCandidates[eIdx];
            if (!exactKey) continue;
            const exactUrl = getVisualOverridePhotoUrl(exactKey);
            if (exactUrl) {
                const ovr = invProductOverridesMap[exactKey];
                return {
                    overrideKey: exactKey,
                    label: cleanStr(ovr && ovr.name) ? cleanStr(ovr.name).toUpperCase() : cleanCand,
                    url: exactUrl
                };
            }
        }

        const entries = getUploadedFabricSwatchEntries();
        if (!entries.length) return null;

        const candTokens = cleanCand.split(/\s+/).filter(t => t.length >= 2);
        if (!candTokens.length) return null;
        const candSet = new Set(candTokens);
        const candSortedSig = candTokens.slice().sort().join(' ');

        // 2) Same token set regardless of word order (e.g. "IVORY LUXOR" == "LUXOR IVORY")
        for (let i = 0; i < entries.length; i++) {
            const e = entries[i];
            if (e.normName === cleanCand || e.sortedSig === candSortedSig) {
                return { overrideKey: e.overrideKey, label: e.label, url: e.url };
            }
        }

        // 3) Uploaded fabric tokens appear as a complete whole-word subset inside the candidate text
        for (let i = 0; i < entries.length; i++) {
            const e = entries[i];
            if (e.tokens.length === 1 && isGenericSingleFabricToken(e.tokens[0])) continue;
            if (e.tokens.every(tok => candSet.has(tok))) {
                return { overrideKey: e.overrideKey, label: e.label, url: e.url };
            }
        }

        // 4) Candidate is a specific multi-word fabric name contained within an uploaded fabric name
        // Guardia anti-falso positivo: nunca emparejar si todos los tokens del candidato son de madera/acabado/colores genéricos
        if (candTokens.length >= 2 && !candTokens.every(tok => WOOD_DESCRIPTOR_ALLOWED_TOKENS.has(tok) || isGenericSingleFabricToken(tok))) {
            for (let i = 0; i < entries.length; i++) {
                const e = entries[i];
                const eSet = new Set(e.tokens);
                if (candTokens.every(tok => eSet.has(tok))) {
                    return { overrideKey: e.overrideKey, label: e.label, url: e.url };
                }
            }
        }

        return null;
    }

    function getFabricSwatchPhotoUrl(fabricKey, itemOpt) {
        if (isPureWoodDescriptor(fabricKey)) return '';
        const directUrl = getVisualOverridePhotoUrl(buildFabricSwatchOverrideKey(fabricKey));
        if (directUrl) return directUrl;
        const canonKey = normalizeFabricLookupKey(fabricKey);
        if (canonKey && !isPureWoodDescriptor(canonKey)) {
            const canonUrl = getVisualOverridePhotoUrl(buildFabricSwatchOverrideKey(canonKey));
            if (canonUrl) return canonUrl;
        }
        const matched = matchFabricTextAgainstUploadedSwatches(fabricKey);
        if (matched && matched.url) return matched.url;
        if (itemOpt) {
            const fromItem = findMatchingFabricSwatchForItem(itemOpt, null);
            if (fromItem && fromItem.url) return fromItem.url;
        }
        return '';
    }

    function findMatchingFabricSwatchForItem(it, groupObj) {
        if (!it) return null;
        if (isWoodOnlyProductForFabricGuard(it)) return null;
        const entries = getUploadedFabricSwatchEntries();
        if (!entries.length) return null;

        const tl = cleanStr(it.tl);
        const ct = cleanStr(it.ct);
        const prov = plainModelToken(cleanStr(it.p));
        const combinedTlCt = (tl && ct && plainModelToken(tl).indexOf(plainModelToken(ct)) === -1)
            ? (tl + ' ' + ct)
            : (tl || ct);

        const candidates = [];
        if (tl && prov && plainModelToken(tl) === 'PIEL') {
            candidates.push('PIEL ' + prov);
        }
        if (combinedTlCt && !isPureWoodDescriptor(combinedTlCt)) candidates.push(combinedTlCt);
        if (tl && tl !== combinedTlCt && !isPureWoodDescriptor(tl)) candidates.push(tl);
        if (cleanStr(it.vr)) {
            const vrParts = String(it.vr).split(/\s*[·|\/]\s*/).map(cleanStr).filter(Boolean);
            for (let i = 0; i < vrParts.length; i++) {
                if (!isPureWoodDescriptor(vrParts[i])) candidates.push(vrParts[i]);
            }
            if (!isPureWoodDescriptor(it.vr)) candidates.push(cleanStr(it.vr));
        }
        if (ct && ct !== combinedTlCt && !isPureWoodDescriptor(ct)) candidates.push(ct);
        const resolvedFab = resolveItemFabricVariation(it, groupObj || null);
        if (resolvedFab && resolvedFab.key && resolvedFab.key !== 'ESTANDAR' && !isPureWoodDescriptor(resolvedFab.key)) {
            candidates.push(resolvedFab.key);
        }

        const tried = new Set();
        for (let i = 0; i < candidates.length; i++) {
            const c = cleanStr(candidates[i]);
            if (!c || tried.has(c)) continue;
            tried.add(c);
            const hit = matchFabricTextAgainstUploadedSwatches(c);
            if (hit && hit.url) return hit;
        }

        // Último respaldo: buscar tela ya subida (de >=2 palabras o nombre específico) dentro del nombre completo del producto
        const nameNorm = canonicalizeFabricAliases(plainModelToken(stripDimensionsFromProductText(it.n)));
        if (nameNorm) {
            const nameSet = new Set(nameNorm.split(/\s+/).filter(Boolean));
            for (let i = 0; i < entries.length; i++) {
                const e = entries[i];
                if (isPureWoodDescriptor(e.normName)) continue;
                if (e.tokens.length < 2 && (e.tokens[0].length < 5 || isGenericSingleFabricToken(e.tokens[0]))) continue;
                if (e.tokens.every(tok => nameSet.has(tok))) {
                    return { overrideKey: e.overrideKey, label: e.label, url: e.url };
                }
            }
        }
        return null;
    }

    // ------------------------------------------------------------------------
    // MUESTRAS DE MADERA (VWOD:) — Pre-cargadas de Drive MADERAS + Overrides en vivo
    // ------------------------------------------------------------------------
    let _vwodIndexMapRef = null;
    let _vwodIndexEntries = [];
    const NON_WOOD_MATERIAL_ONLY_RE = /^(MARMOL|MARBOL|TRAVERTINO|ONIX|PIEDRA|GRANITO|CUARZO|CRISTAL|VIDRIO|ESPEJO|METAL|ACERO|ALUMINIO|HIERRO|HERRERIA|LATON|BRONCE|COBRE|CERAMICA|PORCELANA|PORCELANATO|RESINA|PLASTICO|POLIPROPILENO|RATAN|RATTAN|MIMBRE|CUERDA|SOGA|FIBRA|CONCRETO|CEMENTO|PINO|PINO\s+ESTUFADO|MADERA\s+DE\s+PINO|MDF|TRIPLAY|CONTRACHAPADO|AGLOMERADO|POLIESTER|ESPUMA|DELCRON|N\/A|NA|NO APLICA|NINGUNA|NINGUNO|SIN MADERA|-)$/i;
    const WOOD_FILLER_TOKENS = new Set(['MADERA', 'DE', 'EN', 'CON', 'TONO', 'NATURAL', 'ACABADO', 'LACA', 'BARNIZ', 'BASE', 'PATAS', 'CUBIERTA', 'SOLIDA', 'SOLIDO', 'MACIZA', 'MACIZO', 'CHAPA', 'LAMINADO', 'LAMINADA', 'ENCHAPADO', 'ENCHAPADA']);
    const WOOD_SPECIAL_FINISH_TOKENS = new Set(['ENTINTADO', 'ENTINTADA', 'ACEITE', 'WHITE', 'CLARA', 'CLARO', 'OSCURO', 'OSCURA']);
    // Modificadores/adjetivos solos nunca deben emparejar una muestra de madera (ej. "CLARO" != "TABACO CLARO BARSA")
    const WOOD_MODIFIER_ONLY_TOKENS = new Set([
        'CLARO', 'CLARA', 'OSCURO', 'OSCURA', 'OBSCURO', 'OBSCURA',
        'ENTINTADO', 'ENTINTADA', 'ACEITE', 'WHITE', 'BLANCO', 'BLANCA',
        'NEGRO', 'NEGRA', 'GRIS', 'BEIGE', 'CAFE', 'NATURAL', 'TONO',
        'LACA', 'MATTE', 'MATE', 'BARNIZ', 'BRILLANTE', 'SEMI', 'CARDEADO', 'BLANQUEADO'
    ]);
    const SALA_SOFA_WOOD_GUARD_RE = /\b(SALA|SALAS|SOFA|SOFAS|SOFACAMA|SOFA\s+CAMA|MODULAR|SECCIONAL|ESCUADRA|LOVESEAT|LOVE\s+SEAT|CHAISE|ESQUINERO|FUTON|FUTTON)\b/i;
    const NON_WOOD_TEXTILE_CAT_RE = /^(COJINES\s+TEXTILES|TEXTILES|ROPA\s+DE\s+CAMA|TAPETES|ALFOMBRAS|COLCHONES|BLANCOS)$/i;
    const VISIBLE_WOOD_IN_NAME_RE = /\b(ROSA\s+MORADA|PALO\s+DE\s+ROSA|PAROTA|TZALAM|NOGAL|TECA|TEKA|TEAK|ENCINO|ROBLE|FRESNO|CEDRO|CAOBA|OLMO|HAYA|TABACO|TACUBA|BELLOTA|HABANO|ESPIGA|GINGER|CAMEL|NOCHE|NUEZ|MADERA|PATA(?:S)?\s+DE\s+MADERA|BASE\s+(?:EN\s+)?MADERA)\b/i;

    function expandWoodProviderAliases(provRaw) {
        const p = plainModelToken(provRaw);
        if (!p) return [];
        const out = new Set(p.split(/\s+/).filter(t => t.length >= 2));
        if (p.indexOf('ARTEX') !== -1 || p === 'ATX' || p === 'ARTC') {
            out.add('ARTEX');
            out.add('ATX');
            out.add('ARTC');
        }
        if (p.indexOf('LUX') !== -1) {
            out.add('LUX');
            out.add('FACTORI');
            out.add('FACTORY');
        }
        if (p.indexOf('MOBEL') !== -1) {
            out.add('MOBEL');
            out.add('INN');
        }
        return Array.from(out);
    }

    function normalizeWoodCanonicalText(raw) {
        return plainModelToken(raw)
            .replace(/\bFACTORY\b/g, 'FACTORI')
            .replace(/\b(?:TEKA|TEAK)\b/g, 'TECA')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function getUploadedWoodSwatchEntries() {
        if (_vwodIndexMapRef === invProductOverridesMap && _vwodIndexEntries.length > 0) {
            return _vwodIndexEntries;
        }
        const mergedByKey = new Map();
        const defKeys = Object.keys(DEFAULT_WOOD_SWATCHES_CATALOG);
        for (let i = 0; i < defKeys.length; i++) {
            const k = defKeys[i];
            const ovr = (invProductOverridesMap && Object.prototype.hasOwnProperty.call(invProductOverridesMap, k))
                ? invProductOverridesMap[k]
                : null;
            if (ovr && (ovr.status === 'ELIMINADO' || ovr.status === 'ARCHIVADO')) continue;
            const effective = (ovr && sanitizeVisualOverrideUrl(cleanStr(ovr.note))) ? ovr : DEFAULT_WOOD_SWATCHES_CATALOG[k];
            mergedByKey.set(k, { ovr: effective, isDefault: !ovr });
        }
        if (invProductOverridesMap && typeof invProductOverridesMap === 'object') {
            const ovKeys = Object.keys(invProductOverridesMap);
            for (let i = 0; i < ovKeys.length; i++) {
                const k = String(ovKeys[i] || '').trim().toUpperCase();
                if (k.indexOf('VWOD:') !== 0 || mergedByKey.has(k)) continue;
                const ovr = invProductOverridesMap[k];
                if (!ovr || ovr.status === 'ELIMINADO' || ovr.status === 'ARCHIVADO') continue;
                const url = sanitizeVisualOverrideUrl(cleanStr(ovr.note));
                if (!url) continue;
                mergedByKey.set(k, { ovr: ovr, isDefault: false });
            }
        }
        const entries = [];
        mergedByKey.forEach((meta, k) => {
            const ovr = meta.ovr;
            const url = sanitizeVisualOverrideUrl(cleanStr(ovr.note));
            if (!url) return;
            const rawLabel = cleanStr(ovr.name) || k.slice(5);
            const normName = normalizeWoodCanonicalText(rawLabel);
            const tokens = normName.split(/\s+/).filter(t => t.length >= 2);
            if (!normName || !tokens.length) return;
            const coreTokens = tokens.filter(t => !WOOD_FILLER_TOKENS.has(t));
            entries.push({
                overrideKey: k,
                label: rawLabel.toUpperCase(),
                normName: normName,
                tokens: tokens,
                tokenSet: new Set(tokens),
                coreTokens: coreTokens.length ? coreTokens : tokens,
                sortedSig: tokens.slice().sort().join(' '),
                url: url,
                isDefault: meta.isDefault
            });
        });
        entries.sort((a, b) => (a.isDefault === b.isDefault ? 0 : (a.isDefault ? 1 : -1)) || (b.tokens.length - a.tokens.length) || a.label.localeCompare(b.label));
        _vwodIndexMapRef = invProductOverridesMap;
        _vwodIndexEntries = entries;
        return entries;
    }

    function matchWoodTextAgainstUploadedSwatches(rawCandidateText, provHint) {
        const cleanRaw = cleanStr(rawCandidateText);
        if (!cleanRaw || NON_WOOD_MATERIAL_ONLY_RE.test(plainModelToken(cleanRaw))) return null;
        const normCand = normalizeWoodCanonicalText(cleanRaw);
        if (!normCand || normCand === 'ESTANDAR' || normCand === 'MADERA' || normCand === 'NATURAL' || normCand === 'TONO NATURAL') return null;

        const provAliases = expandWoodProviderAliases(provHint);
        const provNorm = plainModelToken(provHint);

        // 1) Coincidencia directa por clave VWOD: (primero con proveedor si existe, luego directa)
        const directTries = [];
        if (provNorm && normCand.indexOf(provNorm) === -1) {
            directTries.push(normCand + ' ' + provNorm);
        }
        directTries.push(cleanRaw, normCand);
        for (let d = 0; d < directTries.length; d++) {
            const dKey = buildWoodSwatchOverrideKey(directTries[d]);
            if (!dKey) continue;
            const dUrl = getVisualOverridePhotoUrl(dKey);
            if (dUrl) {
                const ovr = (invProductOverridesMap && invProductOverridesMap[dKey]) || DEFAULT_WOOD_SWATCHES_CATALOG[dKey];
                return {
                    overrideKey: dKey,
                    label: cleanStr(ovr && ovr.name) ? cleanStr(ovr.name).toUpperCase() : normCand,
                    url: dUrl
                };
            }
        }

        const entries = getUploadedWoodSwatchEntries();
        if (!entries.length) return null;

        const candTokens = normCand.split(/\s+/).filter(t => t.length >= 2);
        const coreCandTokens = candTokens.filter(t => !WOOD_FILLER_TOKENS.has(t));
        if (!coreCandTokens.length) return null;
        const nonProvCoreTokens = coreCandTokens.filter(t => !provAliases.includes(t) && !WOOD_PROVIDER_RE.test(t));
        if (!nonProvCoreTokens.length) return null;
        // Nunca permitir que solo modificadores genéricos (ej. "CLARO", "CLARA", "ENTINTADO", "OSCURO", "WHITE") emparejen una madera
        if (nonProvCoreTokens.every(t => WOOD_MODIFIER_ONLY_TOKENS.has(t))) return null;
        const candSet = new Set(candTokens);
        const candSortedSig = candTokens.slice().sort().join(' ');
        const candWantsSpecial = candTokens.some(t => WOOD_SPECIAL_FINISH_TOKENS.has(t));

        // 2) Igualdad exacta por nombre normalizado o conjunto de tokens (ej. "ROSA MORADA BARSA")
        for (let i = 0; i < entries.length; i++) {
            const e = entries[i];
            if (e.normName === normCand || e.sortedSig === candSortedSig) {
                return { overrideKey: e.overrideKey, label: e.label, url: e.url };
            }
        }

        // 3) Todos los tokens de la muestra están contenidos en el candidato (ej. candidato "ROSA MORADA BARSA NATURAL" -> "ROSA MORADA BARSA")
        const subsetOfCand = [];
        for (let i = 0; i < entries.length; i++) {
            const e = entries[i];
            if (e.tokens.every(tok => candSet.has(tok))) {
                subsetOfCand.push(e);
            }
        }
        if (subsetOfCand.length) {
            subsetOfCand.sort((a, b) => {
                const aProv = provAliases.some(p => a.tokenSet.has(p)) ? 0 : 1;
                const bProv = provAliases.some(p => b.tokenSet.has(p)) ? 0 : 1;
                if (aProv !== bProv) return aProv - bProv;
                return b.tokens.length - a.tokens.length;
            });
            const best = subsetOfCand[0];
            return { overrideKey: best.overrideKey, label: best.label, url: best.url };
        }

        // 4) Todos los tokens núcleo del candidato están contenidos en la muestra (con prioridad de proveedor y acabado estándar)
        const matchingEntries = [];
        for (let i = 0; i < entries.length; i++) {
            const e = entries[i];
            if (coreCandTokens.every(tok => e.tokenSet.has(tok))) {
                matchingEntries.push(e);
            }
        }
        if (matchingEntries.length) {
            matchingEntries.sort((a, b) => {
                const aProv = provAliases.length && provAliases.some(p => a.tokenSet.has(p)) ? 0 : 1;
                const bProv = provAliases.length && provAliases.some(p => b.tokenSet.has(p)) ? 0 : 1;
                if (aProv !== bProv) return aProv - bProv;
                const aHasSpecial = a.tokens.some(t => WOOD_SPECIAL_FINISH_TOKENS.has(t));
                const bHasSpecial = b.tokens.some(t => WOOD_SPECIAL_FINISH_TOKENS.has(t));
                const aSpecPenalty = (!candWantsSpecial && aHasSpecial) ? 1 : 0;
                const bSpecPenalty = (!candWantsSpecial && bHasSpecial) ? 1 : 0;
                if (aSpecPenalty !== bSpecPenalty) return aSpecPenalty - bSpecPenalty;
                return (a.isDefault === b.isDefault ? 0 : (a.isDefault ? 1 : -1)) || (a.tokens.length - b.tokens.length);
            });
            const best = matchingEntries[0];
            return { overrideKey: best.overrideKey, label: best.label, url: best.url };
        }

        // 5) Si el candidato tenía proveedor no presente en la muestra (ej. "PAROTA HAKO"), reintentar solo especie
        if (coreCandTokens.length >= 2) {
            const speciesOnly = coreCandTokens.filter(t => !provAliases.includes(t) && !WOOD_PROVIDER_RE.test(t));
            if (speciesOnly.length > 0 && speciesOnly.length < coreCandTokens.length) {
                return matchWoodTextAgainstUploadedSwatches(speciesOnly.join(' '), provHint);
            }
        }

        return null;
    }

    function getWoodSwatchPhotoUrl(woodKey, itemOpt) {
        const prov = itemOpt ? cleanStr(itemOpt.p) : '';
        const directUrl = getVisualOverridePhotoUrl(buildWoodSwatchOverrideKey(woodKey));
        if (directUrl) return directUrl;
        const matched = matchWoodTextAgainstUploadedSwatches(woodKey, prov);
        if (matched && matched.url) return matched.url;
        if (itemOpt) {
            const fromItem = findMatchingWoodSwatchForItem(itemOpt, null);
            if (fromItem && fromItem.url) return fromItem.url;
        }
        return '';
    }

    function findMatchingWoodSwatchForItem(it, groupObj) {
        if (!it) return null;
        const catNorm = plainModelToken(cleanStr(it._cat || it.c));
        const nameNorm = plainModelToken(stripDimensionsFromProductText(it.n));
        const typeNameNorm = plainModelToken(cleanStr(it.tp) + ' ' + cleanStr(it.n));

        // 1) Nunca mostrar madera en textiles/accesorios no maderables (cojines, fundas, hilos, tapetes, colchones)
        if (NON_WOOD_TEXTILE_CAT_RE.test(catNorm) || /\b(COJIN|COJINES|FUNDA|FUNDAS|ALMOHADON|SABANA|DUVET|MANTEL|HILO|CONO\s+DE\s+HILO|TOALLA|TAPETE|ALFOMBRA|COLCHON|CORTINA)\b/i.test(typeNameNorm)) {
            return null;
        }

        // 2) REGLA SALAS / SOFÁS: las salas tapizadas NO muestran madera de casco interno (ej. "PINO ESTUFADO" / "CLARO")
        //    SOLO muestran muestra de madera si el NOMBRE del producto menciona explícitamente madera/acabado visible.
        const isSalaOrSofa = SALA_SOFA_WOOD_GUARD_RE.test(catNorm + ' ' + typeNameNorm);
        if (isSalaOrSofa && !VISIBLE_WOOD_IN_NAME_RE.test(nameNorm)) {
            return null;
        }

        const md = cleanStr(it.md);
        const cm = cleanStr(it.cm);
        const prov = cleanStr(it.p);
        const mdNorm = plainModelToken(md);
        const cmNorm = plainModelToken(cm);
        if (mdNorm && NON_WOOD_MATERIAL_ONLY_RE.test(mdNorm) && (!cmNorm || NON_WOOD_MATERIAL_ONLY_RE.test(cmNorm))) {
            return null;
        }
        // Si el producto especifica explícitamente pata negra / laca negra / laca blanca en el nombre sin especie visible, no mostrar madera natural
        if (/^(?:LACA\s+)?(?:NEGR[OA]|BLANC[OA])$/i.test(cmNorm) && /\b(?:PATA(?:S)?\s+NEGR[OA]S?|LACA\s+(?:NEGR[OA]|BLANC[OA]))\b/i.test(nameNorm) && !VISIBLE_WOOD_IN_NAME_RE.test(nameNorm)) {
            return null;
        }

        const candidates = [];
        const mdOk = Boolean(md && !NON_WOOD_MATERIAL_ONLY_RE.test(mdNorm));
        const cmOk = Boolean(cm && !NON_WOOD_MATERIAL_ONLY_RE.test(cmNorm));
        // Priorizar combinación especie + acabado (ej. "TECA ENTINTADO", "ROSA MORADA CLARA") antes de sueltos
        if (mdOk && cmOk && cmNorm.indexOf(mdNorm) === -1) {
            if (prov && (mdNorm + ' ' + cmNorm).indexOf(plainModelToken(prov)) === -1) candidates.push(md + ' ' + cm + ' ' + prov);
            candidates.push(md + ' ' + cm);
        }
        if (cmOk) {
            if (prov && cmNorm.indexOf(plainModelToken(prov)) === -1) candidates.push(cm + ' ' + prov);
            candidates.push(cm);
        }
        if (mdOk) {
            if (prov && mdNorm.indexOf(plainModelToken(prov)) === -1) candidates.push(md + ' ' + prov);
            candidates.push(md);
        }
        if (cleanStr(it.vr)) {
            const vrParts = String(it.vr).split(/\s*[·|\/]\s*/).map(cleanStr).filter(Boolean);
            for (let i = 0; i < vrParts.length; i++) {
                if (isPureWoodDescriptor(vrParts[i])) candidates.push(vrParts[i]);
            }
            if (isPureWoodDescriptor(it.vr)) candidates.push(cleanStr(it.vr));
        }

        const tried = new Set();
        for (let i = 0; i < candidates.length; i++) {
            const c = cleanStr(candidates[i]);
            if (!c || tried.has(c)) continue;
            tried.add(c);
            const hit = matchWoodTextAgainstUploadedSwatches(c, prov);
            if (hit && hit.url) return hit;
        }

        // Respaldo conservador: si no venían columnas MADERA/COLOR MADERA, buscar únicamente especies inequívocas en el nombre
        if (!md && !cm && nameNorm) {
            const spMatch = nameNorm.match(/\b(ROSA\s+MORADA|PALO\s+DE\s+ROSA|PAROTA|TZALAM|NOGAL|TECA|TEKA|TEAK|ENCINO|ROBLE)\b/i);
            if (spMatch && spMatch[1]) {
                const hit = matchWoodTextAgainstUploadedSwatches(spMatch[1], prov);
                if (hit && hit.url) return hit;
            }
        }
        return null;
    }

    function resolveVisualImgSrc(rawUrl, sizePx) {
        const clean = cleanStr(rawUrl);
        if (!clean || /^blob:/i.test(clean)) return '';
        const allowed = sanitizeVisualOverrideUrl(clean, { allowDataImage: true });
        if (!allowed) return '';
        if (/^data:image\//i.test(allowed)) return allowed;
        const fid = extractDriveFileId(allowed);
        if (fid) {
            return 'https://lh3.googleusercontent.com/d/' + fid + '=w' + (Number(sizePx) || 400);
        }
        return allowed;
    }

    function isVisualPhotoEditorAllowed() {
        try {
            return typeof isEffectiveAdminSession === 'function' && isEffectiveAdminSession() &&
                typeof hasAdminPerm === 'function' && hasAdminPerm('fotosApp');
        } catch (e) {
            return false;
        }
    }

    function getMainCategoryRank(mainCat) {
        return Object.prototype.hasOwnProperty.call(MAIN_CAT_RANK, mainCat) ? MAIN_CAT_RANK[mainCat] : 99;
    }

    function getSubCategoryRank(subCat) {
        return Object.prototype.hasOwnProperty.call(SUB_CAT_RANK, subCat) ? SUB_CAT_RANK[subCat] : 999;
    }

    function compareCommercialGroupOrder(a, b) {
        const pa = (a && a._hasPhoto) ? 1 : 0;
        const pb = (b && b._hasPhoto) ? 1 : 0;
        if (pb !== pa) return pb - pa;
        const ma = (a && typeof a._mainRank === 'number') ? a._mainRank : 99;
        const mb = (b && typeof b._mainRank === 'number') ? b._mainRank : 99;
        if (ma !== mb) return ma - mb;
        const ta = (a && typeof a._typeRank === 'number') ? a._typeRank : 999;
        const tb = (b && typeof b._typeRank === 'number') ? b._typeRank : 999;
        if (ta !== tb) return ta - tb;
        if (ta === 999 && tb === 999) {
            const sa = (a && typeof a._subRank === 'number') ? a._subRank : 999;
            const sb = (b && typeof b._subRank === 'number') ? b._subRank : 999;
            if (sa !== sb) return sa - sb;
        }
        return compareAlphaEs(a && (a.displayTitle || a.title), b && (b.displayTitle || b.title)) ||
            String((a && a.key) || '').localeCompare(String((b && b.key) || ''));
    }

    const AVAILABILITY_FILTERS = [
        { key: 'STOCK', label: 'STOCK' },
        { key: 'LPPT', label: 'LPPT' },
        { key: 'LPPT_STOCK', label: 'LPPT+STOCK' }
    ];

    // Submenú de días restantes para LPPT (rangos separados excluyendo 0)
    const LPPT_DAY_RANGES = [
        { key: '-15', label: '-15', min: 1, max: 15 },
        { key: '-30', label: '-30', min: 16, max: 30 },
        { key: '-45', label: '-45', min: 31, max: 45 },
        { key: '-75', label: '-75', min: 46, max: 75 },
        { key: '-90', label: '-90', min: 76, max: 90 }
    ];

    const MODULAR_SALA_MODELS = new Set([
        'CARRARA', 'DYLAN', 'LUGANO', 'MONACO', 'SHELBY', 'ARIA', 'LUNNO', 'NILO',
        'ASPEN', 'AVALANCHE', 'AVENZANO', 'GALARDI', 'KASSIA', 'PONZETTA', 'TRENTO', 'SANTHOMAS',
        'ALTEA', 'BAIKAL', 'CALGARY', 'HARRIS', 'MILAN', 'TESSA', 'TORINO', 'VERSELLI', 'WEMBLEY', 'WILLIAMS'
    ]);

    const SALA_EN_L_MODELS = new Set([
        'DONATI', 'MATERA', 'AMARETO', 'DOVELLI', 'GALES', 'IBIZA',
        'LEXY', 'MAWI', 'PIERO', 'TEREANI', 'VALENTI', 'VARENA',
        'LUNA', 'MELODY', 'MEMPHIS', 'PERRY',
        'CAPRI', 'CHELSEA', 'OXFORD', 'VANCOUVER'
    ]);

    const SOFA_CAMA_MODELS = new Set(['CITY', 'ASHA']);

    const MANUAL_SUBCATEGORY_ALIAS_MAP = (function buildManualSubcategoryAliasMap() {
        const normKey = (s) => String(s || '')
            .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
            .toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim();
        const m = Object.create(null);
        Object.keys(MAIN_OF_SUB).forEach((sub) => {
            if (sub && sub !== 'OTROS') m[normKey(sub)] = sub;
        });
        const aliases = {
            'SOFA CAMA': 'FUTONES & SOFÁ CAMAS',
            'SOFA CAMAS': 'FUTONES & SOFÁ CAMAS',
            'SOFACAMA': 'FUTONES & SOFÁ CAMAS',
            'SOFACAMAS': 'FUTONES & SOFÁ CAMAS',
            'FUTON': 'FUTONES & SOFÁ CAMAS',
            'FUTONES': 'FUTONES & SOFÁ CAMAS',
            'FUTTON': 'FUTONES & SOFÁ CAMAS',
            'FUTTONES': 'FUTONES & SOFÁ CAMAS',
            'FUTONES Y SOFA CAMAS': 'FUTONES & SOFÁ CAMAS',
            'FUTONES SOFA CAMAS': 'FUTONES & SOFÁ CAMAS',
            'SOFA CAMA Y FUTTONES': 'FUTONES & SOFÁ CAMAS',
            'SALA MODULAR': 'SALAS MODULARES',
            'SALA EN L': 'SALAS EN L',
            'ESCUADRA': 'SALAS EN L',
            'SOFA': 'SOFAS & LOVESEATS',
            'SOFAS': 'SOFAS & LOVESEATS',
            'LOVESEAT': 'SOFAS & LOVESEATS',
            'LOVE SEAT': 'SOFAS & LOVESEATS',
            'SOFAS Y LOVESEATS': 'SOFAS & LOVESEATS',
            'SILLON': 'SILLONES',
            'MESA DE CENTRO': 'MESAS DE CENTRO',
            'MESA CENTRO': 'MESAS DE CENTRO',
            'MESA LATERAL': 'MESAS LATERALES',
            'MESA AUXILIAR': 'MESAS LATERALES',
            'MESAS AUXILIARES': 'MESAS LATERALES',
            'MESA': 'MESAS',
            'MESAS DE COMEDOR': 'MESAS',
            'MESA DE COMEDOR': 'MESAS',
            'SILLA': 'SILLAS',
            'SILLAS COMEDOR': 'SILLAS',
            'SILLAS COMEDORES': 'SILLAS',
            'BANCO': 'BANCOS & BANCAS',
            'BANCOS': 'BANCOS & BANCAS',
            'BANCA': 'BANCOS & BANCAS',
            'BANCAS': 'BANCOS & BANCAS',
            'BANCOS Y BANCAS': 'BANCOS & BANCAS',
            'BUFETERA': 'BUFETERAS',
            'CAMA': 'CAMAS',
            'CABECERA': 'CABECERAS',
            'COLCHON': 'COLCHONES',
            'BASE': 'BASES',
            'BASE DE CAMA': 'BASES',
            'BURO': 'BURÓS',
            'COMODA': 'COMODAS Y TOCADORES',
            'COMODAS': 'COMODAS Y TOCADORES',
            'TOCADOR': 'COMODAS Y TOCADORES',
            'TOCADORES': 'COMODAS Y TOCADORES',
            'MUEBLE PARA TV': 'MUEBLES PARA TV',
            'MUEBLE DE TV': 'MUEBLES PARA TV',
            'MESA DE TV': 'MUEBLES PARA TV',
            'CREDENZA': 'CREDENZAS',
            'MUEBLE DE BAR': 'MUEBLES DE BAR',
            'BAR': 'MUEBLES DE BAR',
            'CAVA': 'MUEBLES DE BAR',
            'LIBRERO': 'LIBREROS',
            'ESCRITORIO': 'ESCRITORIOS',
            'OFICINA': 'ESCRITORIOS',
            'EXTERIOR Y TERRAZA': 'EXTERIOR',
            'EXTERIOR TERRAZA': 'EXTERIOR',
            'TERRAZA': 'EXTERIOR',
            'ESPEJO': 'ESPEJOS',
            'CUADRO': 'CUADROS',
            'LAMPARA': 'LÁMPARAS',
            'ILUMINACION': 'LÁMPARAS',
            'COJIN': 'COJINES & TEXTILES',
            'COJINES': 'COJINES & TEXTILES',
            'TEXTILES': 'COJINES & TEXTILES',
            'COJINES Y TEXTILES': 'COJINES & TEXTILES',
            'ACCESORIO': 'ACCESORIOS DECORATIVOS',
            'ACCESORIOS': 'ACCESORIOS DECORATIVOS'
        };
        Object.keys(aliases).forEach((k) => { m[normKey(k)] = aliases[k]; });
        return m;
    })();

    function resolveManualSubcategoryOverride(rawCat) {
        const s = cleanStr(rawCat);
        if (!s || /^(?:VISUAL_COVER|FABRIC_SWATCH|WOOD_SWATCH)$/i.test(s)) return '';
        const normKey = s
            .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
            .toUpperCase().replace(/[^A-Z0-9]+/g, ' ').trim();
        return MANUAL_SUBCATEGORY_ALIAS_MAP[normKey] || '';
    }

    function isExteriorFurnitureItem(it, allTxt, prodTxt, mo, tp, nom, cat) {
        if (/\bINTERIOR\b/.test(nom) || /\bCUADRO\b/.test(prodTxt)) return false;
        const prov = String(cleanStr(it && it.p)).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim();
        if (/\b(EXTERIOR|CAMASTRO|COLUMPIO|SOMBRILLA|POLYRATAN|POLYRATTAN|TERRAZA|INTEMPERIE|SUNBRELLA|ALBERCA)\b/.test(allTxt)) {
            return true;
        }
        // Proveedores y materiales exclusivos de mobiliario de exterior (HANGKAI Teka/Cuerda y G&C Aluminio/Polvo Alumbre)
        if (prov === 'HANGKAI' || /^HAK/i.test(cleanStr(it && it.s))) {
            return true;
        }
        if (prov === 'G&C' && !/^(COJIN|MACETA|ACCESORIO)$/.test(tp)) {
            return true;
        }
        if (/\b(POLVO\s+ALUMBRE|TUBO\s+DE\s+ALUMINIO|CUERDA\s+SINTETICA|TELA\s+REPELENTE)\b/.test(prodTxt)) {
            return true;
        }
        // Colecciones de exterior conocidas sin la palabra "EXTERIOR" en el nombre ERP
        if (mo === 'ALTEA' && /\b(TEKA|TECA|GLACIER\s+ICE|ESQUINERO|OTTOMAN|SILLON|MESA)\b/.test(prodTxt)) {
            return true;
        }
        if (mo === 'SANTHOMAS' && !/\b(BUFETERA|COMODA|SILLA)\b/.test(prodTxt) && /\b(TECA|TEKA|LOVE\s*SEAT|MODULAR|EXTERIOR)\b/.test(prodTxt)) {
            return true;
        }
        if (mo === 'SANTA MONICA' && /^MIN/i.test(cleanStr(it && it.s))) {
            return true;
        }
        if (cat === 'EXTERIOR & TERRAZA') {
            return true;
        }
        return false;
    }

    function isModularOrSectionalSalaPiece(prodTxt, nomHeadSub, mo, moFirst, tp) {
        // Sillas de comedor o sillones explícitamente ocasionales/individuales sin brazo direccional ni modularidad NO son módulos
        if (/\bSILLAS?\b/.test(nomHeadSub) && !/\bSILLON(?:ES)?\b/.test(nomHeadSub)) return false;
        const isExplicitModularText = /\b(MODULAR(?:ES)?|MODULOS?|ESQUINEROS?|REMATES?|SIN\s+BRAZOS?|CON\s+BRAZO\s+(?:DER(?:ECHO|EHO)?|IZQ(?:UIERDO)?)|BRAZO\s+(?:DER(?:ECHO|EHO)?|IZQ(?:UIERDO)?)|B\/DER|B\/IZQ|(?:SILLON|SOFA|LOVE\s*SEAT|LOVESEAT|LOVE)\s+(?:CURVO\s+)?(?:DER(?:ECHO|EHO)?|IZQ(?:UIERDO)?|CENTRAL|MODULAR))\b/.test(prodTxt);
        if (isExplicitModularText) return true;
        // Piezas de modelos modulares conocidos (excepto SILLON OCASIONAL como ARIA SILLON OCASIONAL)
        const isOccasionalChair = /\b(OCASIONAL|MECEDORA|RECLINABLE|BERGERE|BUTACA)\b/.test(prodTxt);
        if (!isOccasionalChair && (MODULAR_SALA_MODELS.has(mo) || MODULAR_SALA_MODELS.has(moFirst))) {
            if (/\b(SILLON(?:ES)?|SOFAS?|LOVE\s*SEATS?|LOVESEATS?|ESQUINEROS?|CHAISE|OTTOMAN|OTOMAN|TABURETES?|REMATE)\b/.test(tp + ' ' + nomHeadSub)) {
                return true;
            }
        }
        return false;
    }

    function classifyItemSubcategory(it) {
        const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();
        // Prioridad 0: categoría editada manualmente por Kevin en _INV_PRODUCT_OVERRIDES (ej. "Sofa camas" -> "FUTONES & SOFÁ CAMAS")
        const manualOvr = getProductOverrideForSku(it && it.s);
        if (manualOvr && manualOvr.category) {
            const manualSub = resolveManualSubcategoryOverride(manualOvr.category);
            if (manualSub) return manualSub;
        }
        const cat = norm(cleanStr(it && it.c));
        const tp = norm(cleanStr(it && it.tp));
        const mo = norm(cleanStr(it && it.mo));
        const moFirst = mo.split(/\s+/)[0] || '';
        const nom = norm(cleanStr(it && it.n));
        const prodTxt = (tp + ' ' + nom).trim();
        const allTxt = (tp + ' ' + nom + ' ' + mo + ' ' + cat).trim();

        // 0) Muebles de TV explícitos antes de cualquier exclusión de recubrimientos (ej. "WALL UNIT MESA DE TV")
        if (
            /^PTV\b/.test(tp) ||
            /\b(MUEBLES?\s+(?:PARA\s+|DE\s+)?TV|MESAS?\s+(?:PARA\s+|DE\s+)?TV|MODULOS?\s+(?:PARA\s+|DE\s+)?TV|CENTROS?\s+DE\s+TV|CENTROS?\s+DE\s+ENTRETENIMIENTO|CENTROS?\s+DE\s+ENCETRENIMIENTO|\bPTV\b)\b/.test(prodTxt)
        ) {
            return 'MUEBLES PARA TV';
        }

        // 1) Exclusión temprana de exterior, iluminación, textiles, colchones y decoración (evita falsos positivos como "LAMPARA DE MESA", "CAMINO MESA", "CHAROLA BAR", etc.)
        if (isExteriorFurnitureItem(it, allTxt, prodTxt, mo, tp, nom, cat)) {
            return 'EXTERIOR';
        }
        if (/\b(LAMPARA|CANDIL|ARBOTANTE|LUMINARIA|PLAFON)\b/.test(prodTxt) || cat === 'ILUMINACION') {
            return 'LÁMPARAS';
        }
        // Textiles de cama (cubrecamas, juegos de sábanas, sets de blancos 11 pzas) NO son muebles de cama
        if (
            /\b(CUBRE\s*CAMAS?|JUEGO\s+(?:DE\s+)?SABANAS?|JGO\.?\s+SABANAS?|SABANAS?|COLCHAS?|EDREDON(?:ES)?|DUVET)\b/.test(prodTxt) ||
            (
                /\bSET\b/.test(nom) &&
                /\(\s*(?:[4-9]|[1-9]\d)\s*PZAS?\s*\)/.test(nom) &&
                /\b(KING(?:\s+SIZE)?|QUEEN(?:\s+SIZE)?|MATRIMONIAL|MAT\/QUEEN|INDIVIDUAL|KS|QS)\b/.test(nom) &&
                !/\b(CABECERA|BASE\s+DE\s+CAMA|PATAS?|EXTENSIONES?|BURO|COMODA|CAJONERA)\b/.test(nom)
            )
        ) {
            return 'COJINES & TEXTILES';
        }
        const isFurniturePiece = /\b(SALAS?|SOFAS?|LOVE\s*SEATS?|LOVESEATS?|LOVE\s+CON\s+BRAZO|SILLON(?:ES)?|BUTACAS?|CHAISE|ESQUINEROS?|FUTTON(?:ES)?|FUTON(?:ES)?|OTTOMAN|OTOMAN|POUF|PUFF?|MESAS?\s+(?:DE\s+)?(?:COMEDOR|CENTRO|CENTRAL|LATERAL|AUXILIAR|BAR|TV)|ANTECOMEDOR(?:ES)?|COMEDOR(?:ES)?|SILLAS?|BANCOS?|BANCAS?|TABURETES?|BUFETERAS?|CREDENZAS?|CONSOLAS?|CAVAS?|LIBREROS?|ESCRITORIOS?|CAMAS?|CABECERAS?|BASES?\s+(?:DE\s+)?CAMA|BUROS?|COMODAS?|TOCADOR(?:ES)?|CAJONERAS?|LITERAS?|CUNAS?|COLCHON(?:ES)?|PIE\s+DE\s+CAMA|CAMASTROS?|COLUMPIOS?)\b/.test(tp + ' ' + nom) ||
            /^(?:SALA|SOFA|LOVE\s*SEAT|LOVESEAT|SILLON|MESA\s+(?:DE\s+)?(?:COMEDOR|CENTRO|CENTRAL|LATERAL|AUXILIAR)|COMEDOR|SILLA|BANCO|BANCA|BUFETERA|CREDENZA|CAMA|BASE\s+(?:DE\s+)?CAMA|CABECERA|BURO|COMODA|COLCHON)\b/.test(nom);

        if (
            !isFurniturePiece && (
                /\b(COJIN(?:ES)?|FUNDA(?:\s+DECORATIVA|\s+RINONERA)?|DUVET|FRAZADA|BLANCOS|ALMOHADA|TAPETE|RELLENO|DRACON|COLCHA|EDREDON|SABANA|CUBRECAMA|TOALLA|CAMINO\s+(?:DE\s+)?MESA|MANTEL|PORTAVASO|SERVILLETERO)\b/.test(prodTxt) ||
                /^INDIVIDUAL(?:ES)?$/.test(tp) ||
                /^(?:SET\s+(?:DE\s+)?(?:\d+\s+)?)?INDIVIDUAL(?:ES)?\b/.test(nom) ||
                /^(?:T\.\s+|TELA\s+|TEL-ARTELL\b|TEL-?FOR\b|TELART\b)/.test(nom) ||
                /^(?:TELA(?:\s+ARTELL)?|TEL-?FOR|TELART|TAPICERIA|COMPONENTES\s+TAPICERIA|SINTETICO)$/.test(tp)
            )
        ) {
            return 'COJINES & TEXTILES';
        }
        if (/\b(COLCHON|CUBRE\s*COLCHON|PROTECTOR\s+DE\s+COLCHON)\b/.test(nom) || /^COLCHON$/.test(tp)) {
            return 'COLCHONES';
        }
        if (/\bPROTECTOR(?:ES)?\s+SAFETY\b/.test(prodTxt) || (/^PROTECTOR(?:ES)?\b/.test(nom) && !/\bCOLCHON\b/.test(nom))) {
            return 'ACCESORIOS DECORATIVOS';
        }
        if (/\bESPEJOS?\b/.test(tp) || (/^ESPEJO\b/.test(nom) && !/\b(TOCADOR|COMODA)\b/.test(prodTxt))) {
            return 'ESPEJOS';
        }
        if (/\b(CUADRO|ARTE\s+OBJETO|DECORATIVO\s+(?:DE\s+)?PARED|PINTURA|LIENZO|GICLEE)\b/.test(prodTxt)) {
            return 'CUADROS';
        }
        // Pieza de sala mal etiquetada como ACCESORIO DECORATIVO en ERP (ej. HARRIS LOVE CON BRAZO DERECHO)
        const isMislabelledSalaModule = /\b(LOVE\s+CON\s+BRAZO|BRAZO\s+(?:DER|IZQ))\b/.test(nom) && (MODULAR_SALA_MODELS.has(mo) || SALA_EN_L_MODELS.has(mo));
        if (
            !isMislabelledSalaModule && (
                /^(?:ACCESORIOS?(?:\s+DECORATIVOS?)?|ACCECORIO|FLORERO|JARRON|ESCULTURA|CHAROLA|BANDEJA|FRUTERO|ENSALADERA|CANDELABRO|PORTAVELAS?|PORTARRETRATO|MACETA|PLANTA(?:\s+DECORATIVA)?|FOLLAJE|VELAS?|LIBRO(?:\s+DECORATIVO)?|BOTELLA|BOTELLON|PLATO(?:\s+HONDO)?(?:\s+DECORATIVO)?|PLATON|SET\s+PLATO|TAZON|BATEA|BOLSA|CANAST[OA]|CESTA|LINTERNA|FAROL|CORAL|CONCHA|BOWL|CORDON\s+DECORATIVO|DECORATIVO\s+NAVIDAD|PERCHERO|MAMPARA|BIOMBO|PAPEL\s+TAPIZ|LAMBRIN(?:\s+DECORATIVO)?|LAMINA\s+DE\s+PVC|PISOS?\s+MODULARES?|ARCHIVERO|PEDESTAL|GARANTIA|MAQFOR|PRODUCTO\s+ESPECIAL|BAUL)$/.test(tp) ||
                /\b(CENTRO\s+DE\s+MESA|RELOJ\s+DE\s+MESA|ADORNO\s+DE\s+MESA|LIBRO\s+DECORATIVO|PLANTA\s+DECORATIVA)\b/.test(prodTxt) ||
                (tp === 'ESCUADRA' && /\b(PATA|CARPINTERIA)\b/.test(allTxt))
            )
        ) {
            return 'ACCESORIOS DECORATIVOS';
        }

        // 2) Subcategorías de RECÁMARAS, COMEDORES, SALAS y COMPLEMENTOS
        if (/\bPIE\s+DE\s+CAMA\b/.test(prodTxt) || (/\bBANCAS?\b/.test(prodTxt) && /\bPIE\s+DE\s+CAMA\b/.test(allTxt))) {
            return 'PIE DE CAMA';
        }
        const isSalaModularTaburete = /\bTABURETES?\b/.test(prodTxt) && (
            MODULAR_SALA_MODELS.has(mo) || MODULAR_SALA_MODELS.has(moFirst) ||
            SALA_EN_L_MODELS.has(mo) || SALA_EN_L_MODELS.has(moFirst)
        );
        if (!isSalaModularTaburete && /\b(BANCOS?|BANCAS?|TABURETES?)\b/.test(prodTxt) && !/\bSALA\b/.test(tp)) {
            return 'BANCOS & BANCAS';
        }
        if (
            /\b(MUEBLES?\s+(?:DE\s+|PARA\s+)?BAR|CARRITOS?\s+(?:DE\s+)?BAR|CAVAS?|CONTRABARRAS?|CANTINAS?|BAR\s+GABINETE|GABINETES?\s+(?:DE\s+)?BAR)\b/.test(prodTxt) ||
            /^BAR\b/.test(tp)
        ) {
            return 'MUEBLES DE BAR';
        }
        if (/\b(ESCRITORIOS?|SECRETAIRES?)\b/.test(prodTxt)) {
            return 'ESCRITORIOS';
        }
        if (
            /\b(SOFAS?\s*CAMAS?|SOFA-CAMA|FUTON(?:ES)?|FUTTON(?:ES)?|DAYBED)\b/.test(prodTxt) ||
            ((SOFA_CAMA_MODELS.has(mo) || dynamicSofaCamaModels.has(extractPlainModelKeyForPairing(it))) && /\b(CHAISE|SOFA|LOVE\s*SEAT|SALA|OTTOMAN)\b/.test(prodTxt))
        ) {
            return 'FUTONES & SOFÁ CAMAS';
        }
        if (/\bCABECERAS?\b/.test(prodTxt) && tp !== 'CAMA') {
            return 'CABECERAS';
        }
        if (
            tp !== 'CAMA' && (
                /\b(BASES?\s+(?:DE\s+)?CAMA|BASES?\s+(?:PARA\s+)?COLCHON|BASES?\s+(?:KS|QS|MAT|MTR|IND|KING(?:\s+SIZE)?|QUEEN(?:\s+SIZE)?|MATRIMONIAL|INDIVIDUAL)|BOX\s*SPRING)\b/.test(prodTxt) ||
                tp === 'BOX' ||
                (/^BASES?\b/.test(tp) && !/\b(COMEDOR|MESA|CUBIERTA|CRISTAL|MARMOL|LAMPARA)\b/.test(allTxt))
            )
        ) {
            return 'BASES';
        }
        if (/\b(CAMAS?|LITERAS?|CUNAS?)\b/.test(prodTxt)) {
            return 'CAMAS';
        }
        if (/\bBUROS?\b/.test(prodTxt)) {
            return 'BURÓS';
        }
        if (/\b(COMODAS?|TOCADOR(?:ES)?|CHIFONIERS?|CAJONERAS?)\b/.test(prodTxt)) {
            return 'COMODAS Y TOCADORES';
        }
        if (
            /\b(LIBREROS?|ESTANTERIAS?|ESTANTES?|REPISAS?|VITRINAS?|PUERTAS\s+PARA\s+LIBRERO)\b/.test(prodTxt) ||
            (tp === 'SET DE PUERTAS' && /\b(LIBRERO|TRITON)\b/.test(allTxt))
        ) {
            return 'LIBREROS';
        }
        if (/\b(CREDENZAS?|CONSOLAS?|RECIBIDOR(?:ES)?)\b/.test(prodTxt)) {
            return 'CREDENZAS';
        }
        if (/\b(BUFETERAS?|BUFERETERAS?|BUFETEROS?|TRINCHADOR(?:ES)?|APARADOR(?:ES)?)\b/.test(prodTxt)) {
            return 'BUFETERAS';
        }
        const nomHeadSub = nom.split(/\b(?:INCLUYE|INCL|CON\s+\d|CON\s+MESAS?\b|CON\s+SILLAS?\b|C\/\s*FUNDAS)\b/)[0].trim();
        const isModularPiece = isModularOrSectionalSalaPiece(prodTxt, nomHeadSub, mo, moFirst, tp);
        if (
            !isModularPiece &&
            /\b(SILLON(?:ES)?|BUTACAS?|MECEDORAS?|RECLINABLES?|BERGERE)\b/.test(nomHeadSub) &&
            !/\bSILLAS?\b/.test(nomHeadSub) &&
            !/^(?:SALA|SOFA\s+CAMA|FUTTON|FUTON)\b/.test(nomHeadSub)
        ) {
            return 'SILLONES';
        }
        if (
            /\bSILLAS?\b/.test(nomHeadSub) &&
            !/\b(SILLON(?:ES)?|MESAS?|COLGANTES?|COLUMPIOS?)\b/.test(nomHeadSub) &&
            !/^SALA\b/.test(nomHeadSub)
        ) {
            return 'SILLAS';
        }
        if (/^SILLAS?\b/.test(tp) && !/\bSILLON(?:ES)?\b/.test(nomHeadSub)) {
            return 'SILLAS';
        }
        const isExplicitSala = tp === 'SALA' || (/^SALA\b/.test(nom) && !/^SALA\s+COMEDOR\b/.test(nom));
        if (!isExplicitSala) {
            if (/\b(MESAS?\s+(?:DE\s+)?CENTRO|MESAS?\s+CENTRAL(?:ES)?|SETS?\s+(?:DE\s+)?MESAS?\s+(?:DE\s+)?CENTRO)\b/.test(prodTxt)) {
                return 'MESAS DE CENTRO';
            }
            if (/\b(MESAS?\s+LATERAL(?:ES)?|MESAS?\s+AUXILIAR(?:ES)?|MESAS?\s+DE\s+RINCON|MESAS?\s+NIDO|MESAS?\s+OCASIONAL(?:ES)?)\b/.test(prodTxt)) {
                return 'MESAS LATERALES';
            }
            if (/\b(MESAS?\s+(?:DE\s+|PARA\s+)?COMEDOR|COMEDOR(?:ES)?|ANTECOMEDOR(?:ES)?|DESAYUNADOR(?:ES)?|CUBIERTAS?\s+(?:DE\s+|PARA\s+)?(?:COMEDOR|MESA|CRISTAL)|BASES?\s+(?:DE\s+|PARA\s+)?(?:COMEDOR|MESA)|EXTENSIONES?\s+DE\s+MESA|SET\s+DE\s+EXTENSIONES)\b/.test(prodTxt)) {
                return 'MESAS';
            }
            if (/\bCRISTAL\b/.test(tp)) {
                if (/\bCOMEDOR\b/.test(allTxt)) return 'MESAS';
                if (/\bLATERAL|AUXILIAR\b/.test(allTxt)) return 'MESAS LATERALES';
                if (/\bCENTRO|SALA|MESA\b/.test(allTxt)) return 'MESAS DE CENTRO';
                return 'ACCESORIOS DECORATIVOS';
            }
            if (/\bMESAS?\b/.test(prodTxt)) {
                if (/\b(LATERAL|AUXILIAR|RINCON|NIDO)\b/.test(allTxt)) return 'MESAS LATERALES';
                if (/\b(CENTRO|CENTRAL|SALA)\b/.test(allTxt)) return 'MESAS DE CENTRO';
                return 'MESAS';
            }
            if (!isModularPiece && /\b(SILLON(?:ES)?|BUTACAS?|MECEDORAS?|RECLINABLES?|BERGERE)\b/.test(prodTxt)) {
                return 'SILLONES';
            }
            if (/\bSILLAS?\b/.test(prodTxt)) {
                return 'SILLAS';
            }
        }
        if (
            isModularPiece ||
            isMislabelledSalaModule ||
            /\b(SALAS?|SOFAS?|LOVE\s*SEATS?|LOVESEATS?|MODULOS?|MODULAR(?:ES)?|ESQUINEROS?|ESQUINERAS?|RINCONERAS?|CHAISE(?:\s+LONGUE)?|OTTOMAN|OTOMAN|POUF|PUFF?|SECCIONAL(?:ES)?|REMATES?)\b/.test(prodTxt)
        ) {
            if (/\b(SALAS?\s+EN\s+L|SECCIONAL(?:ES)?\s+EN\s+L|EN\s+ESCUADRA)\b/.test(prodTxt)) {
                return 'SALAS EN L';
            }
            if (SALA_EN_L_MODELS.has(mo) || SALA_EN_L_MODELS.has(moFirst)) {
                return 'SALAS EN L';
            }
            if (
                isModularPiece ||
                isMislabelledSalaModule ||
                /\b(MODULAR(?:ES)?|MODULOS?|ESQUINEROS?|REMATES?)\b/.test(prodTxt) ||
                MODULAR_SALA_MODELS.has(mo) ||
                MODULAR_SALA_MODELS.has(moFirst)
            ) {
                return 'SALAS MODULARES';
            }
            if (
                /\b(CHAISE(?:\s+LONGUE)?|EN\s+L|ESQUINERAS?|SECCIONAL(?:ES)?)\b/.test(prodTxt) ||
                (/\b(SOFAS?|LOVE\s*SEATS?|LOVESEATS?|SALAS?)\b/.test(prodTxt) && /\b(BRAZO\s+DER(?:ECHO|EHO)?|BRAZO\s+IZQ(?:UIERDO)?|B\/DER|B\/IZQ|DERECHO|DEREHO|IZQUIERDO|DER|IZQ)\b/.test(prodTxt))
            ) {
                return 'SALAS EN L';
            }
            return 'SOFAS & LOVESEATS';
        }

        return 'OTROS';
    }

    function resolveItemCategory(it) {
        return classifyItemSubcategory(it);
    }

    function resolveItemSubcategory(it, baseCat) {
        return baseCat || classifyItemSubcategory(it);
    }

    function photoUrlForItem(it) {
        return it ? resolveDriveOrImgUrl(it.f) : '';
    }

    function firstPhotoItem(items) {
        for (let i = 0; i < items.length; i++) {
            if (photoUrlForItem(items[i])) return items[i];
        }
        return null;
    }

    const THUMB_PLACEHOLDER_SVG =
        '<svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"></path></svg>';

    const failedDrivePhotoIds = new Set();
    const OPTFIT_STORAGE_KEY = 'creata_optfit_bbox_v2';
    const OPTFIT_MAX_ENTRIES = 800;
    const OPTFIT_TARGET_FILL = 0.78;
    let optFitMap = null;
    let optFitSaveTimer = null;
    let optFitCanvas = null;
    let optFitCtx = null;
    const optFitQueue = [];
    let optFitScheduled = false;

    function loadOptFitMap() {
        if (optFitMap) return optFitMap;
        optFitMap = {};
        try {
            const raw = sessionStorage.getItem(OPTFIT_STORAGE_KEY);
            if (raw) {
                const parsed = JSON.parse(raw);
                if (parsed && typeof parsed === 'object') optFitMap = parsed;
            }
        } catch (e) {
            optFitMap = {};
        }
        return optFitMap;
    }

    function scheduleSaveOptFitMap() {
        if (optFitSaveTimer) return;
        optFitSaveTimer = setTimeout(function () {
            optFitSaveTimer = null;
            try {
                const map = loadOptFitMap();
                const keys = Object.keys(map);
                if (keys.length > OPTFIT_MAX_ENTRIES) {
                    const excess = keys.length - OPTFIT_MAX_ENTRIES;
                    for (let i = 0; i < excess; i++) delete map[keys[i]];
                }
                sessionStorage.setItem(OPTFIT_STORAGE_KEY, JSON.stringify(map));
            } catch (e) {}
        }, 500);
    }

    /**
     * Detecta la caja de contenido del producto sobre fondo uniforme de estudio
     * (blanco/transparente/gris claro) muestreando ÚNICAMENTE los píxeles reales
     * de la imagen (sin franjas letterbox) y filtrando motas aisladas de 1px.
     */
    function detectStudioContentBounds(rgba, w, h, naturalWidth, naturalHeight) {
        if (!rgba || !w || !h || w < 12 || h < 12) return null;
        const ring = (w < 24 || h < 24) ? 1 : 2;
        let borderCount = 0;
        let transCount = 0;
        let sumR = 0, sumG = 0, sumB = 0;
        const bSamples = [];
        for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
                if (x >= ring && x < w - ring && y >= ring && y < h - ring) continue;
                const idx = (y * w + x) * 4;
                const a = rgba[idx + 3];
                borderCount++;
                if (a < 24) {
                    transCount++;
                } else {
                    sumR += rgba[idx];
                    sumG += rgba[idx + 1];
                    sumB += rgba[idx + 2];
                    bSamples.push(rgba[idx], rgba[idx + 1], rgba[idx + 2]);
                }
            }
        }
        const transRatio = borderCount > 0 ? (transCount / borderCount) : 0;
        const useAlpha = transRatio >= 0.08;
        const opaqueBorder = bSamples.length / 3;
        const mR = opaqueBorder > 0 ? sumR / opaqueBorder : 255;
        const mG = opaqueBorder > 0 ? sumG / opaqueBorder : 255;
        const mB = opaqueBorder > 0 ? sumB / opaqueBorder : 255;
        let varSum = 0;
        for (let i = 0; i < bSamples.length; i += 3) {
            const dr = bSamples[i] - mR;
            const dg = bSamples[i + 1] - mG;
            const db = bSamples[i + 2] - mB;
            varSum += (dr * dr + dg * dg + db * db) / 3;
        }
        const borderStdDev = opaqueBorder > 0 ? Math.sqrt(varSum / opaqueBorder) : 0;

        const maxCh = Math.max(mR, mG, mB);
        const minCh = Math.min(mR, mG, mB);
        const isPureWhiteBg = useAlpha || (minCh >= 244 && (maxCh - minCh) <= 12);
        if (!useAlpha) {
            if (isPureWhiteBg) {
                if (borderStdDev > 24) return null;
            } else {
                // Fondo gris claro uniforme de estudio permitido; fotos ambiente/oscuras se respetan intactas
                if (borderStdDev > 20 || minCh < 212 || (maxCh - minCh) > 20) return null;
            }
        }

        const thresh = Math.max(30, Math.min(64, Math.round(28 + borderStdDev * 2.2)));
        const mask = new Uint8Array(w * h);
        for (let y = 0; y < h; y++) {
            const rowOff = y * w;
            for (let x = 0; x < w; x++) {
                const idx = (rowOff + x) * 4;
                const a = rgba[idx + 3];
                if (a <= 24) continue;
                if (useAlpha) {
                    mask[rowOff + x] = 1;
                } else {
                    const dist = Math.abs(rgba[idx] - mR) + Math.abs(rgba[idx + 1] - mG) + Math.abs(rgba[idx + 2] - mB);
                    if (dist > thresh) mask[rowOff + x] = 1;
                }
            }
        }

        // Filtro 8-vecinos: elimina píxeles aislados de polvo/compresión conservando patas delgadas
        let minX = w, minY = h, maxX = -1, maxY = -1, fgCount = 0;
        for (let y = 0; y < h; y++) {
            const rowOff = y * w;
            const y0 = y > 0 ? y - 1 : 0;
            const y1 = y < h - 1 ? y + 1 : h - 1;
            for (let x = 0; x < w; x++) {
                if (!mask[rowOff + x]) continue;
                const x0 = x > 0 ? x - 1 : 0;
                const x1 = x < w - 1 ? x + 1 : w - 1;
                let hasNeighbor = false;
                for (let ny = y0; ny <= y1 && !hasNeighbor; ny++) {
                    const nRow = ny * w;
                    for (let nx = x0; nx <= x1; nx++) {
                        if (nx === x && ny === y) continue;
                        if (mask[nRow + nx]) {
                            hasNeighbor = true;
                            break;
                        }
                    }
                }
                if (!hasNeighbor) continue;
                fgCount++;
                if (x < minX) minX = x;
                if (x > maxX) maxX = x;
                if (y < minY) minY = y;
                if (y > maxY) maxY = y;
            }
        }

        const minFg = Math.max(24, Math.floor(w * h * 0.008));
        if (fgCount < minFg || maxX <= minX || maxY <= minY) return null;
        const boxW = maxX - minX + 1;
        const boxH = maxY - minY + 1;
        if (boxW / w < 0.08 || boxH / h < 0.08) return null;

        return {
            nw: Number(naturalWidth) || w,
            nh: Number(naturalHeight) || h,
            uMin: +(minX / w).toFixed(4),
            uMax: +((maxX + 1) / w).toFixed(4),
            vMin: +(minY / h).toFixed(4),
            vMax: +((maxY + 1) / h).toFixed(4),
            isWhiteBg: !!isPureWhiteBg
        };
    }

    /**
     * Calcula escala y traslación exactas para CSS `translate(tx%, ty%) scale(s)`
     * centrando el producto al ~78% parejo del contenedor sin recortar bordes ni mostrar costuras grises.
     */
    function computeOpticalFitForBox(bbox, boxRatio, opts) {
        if (!bbox || bbox === 'skip' || !bbox.nw || !bbox.nh) return { s: 1, tx: 0, ty: 0 };
        const o = opts || {};
        const targetFill = Number(o.targetFill) || OPTFIT_TARGET_FILL;
        const maxScale = Number(o.maxScale) || 1.65;
        const bRatio = (Number(boxRatio) > 0.1) ? Number(boxRatio) : 1;
        const imgRatio = bbox.nw / bbox.nh;

        let rw = 1;
        let rh = 1;
        if (imgRatio >= bRatio) {
            rw = 1;
            rh = bRatio / imgRatio;
        } else {
            rw = imgRatio / bRatio;
            rh = 1;
        }

        const bw = Math.max(0.01, (bbox.uMax - bbox.uMin) * rw);
        const bh = Math.max(0.01, (bbox.vMax - bbox.vMin) * rh);
        const occ = Math.max(bw, bh);
        if (occ <= 0.05) return { s: 1, tx: 0, ty: 0 };

        const minScale = bbox.isWhiteBg ? 0.76 : 1.0;
        const rawScale = targetFill / occ;
        const s = Math.max(minScale, Math.min(maxScale, rawScale));

        const uc = (bbox.uMin + bbox.uMax) / 2;
        const vc = (bbox.vMin + bbox.vMax) / 2;
        const ex = (uc - 0.5) * rw;
        const ey = (vc - 0.5) * rh;

        // Con transform: translate(tx, ty) scale(s) desde el centro,
        // un punto (ex, ey) termina en (s*ex + tx, s*ey + ty) => tx = -s*ex, ty = -s*ey.
        // En fondos gris claro no blancos, limitar el desplazamiento al sobrante real para evitar costuras.
        const maxShiftX = bbox.isWhiteBg ? 0.38 : Math.max(0, Math.min(0.12, (s * rw - 1) / 2));
        const maxShiftY = bbox.isWhiteBg ? 0.38 : Math.max(0, Math.min(0.12, (s * rh - 1) / 2));
        const txFrac = Math.max(-maxShiftX, Math.min(maxShiftX, -s * ex));
        const tyFrac = Math.max(-maxShiftY, Math.min(maxShiftY, -s * ey));

        const finalS = +s.toFixed(3);
        const finalTx = +(txFrac * 100).toFixed(2);
        const finalTy = +(tyFrac * 100).toFixed(2);

        if (Math.abs(finalS - 1) < 0.03 && Math.abs(finalTx) < 1.2 && Math.abs(finalTy) < 1.2) {
            return { s: 1, tx: 0, ty: 0 };
        }
        return { s: finalS, tx: finalTx, ty: finalTy };
    }

    function detectProductStudioBoundsFromSource(sourceEl, maxSampleSide) {
        if (!sourceEl) return null;
        const nw = sourceEl.naturalWidth || sourceEl.width || 0;
        const nh = sourceEl.naturalHeight || sourceEl.height || 0;
        if (nw < 16 || nh < 16) return null;
        try {
            const cap = Number(maxSampleSide) || 96;
            const ratio = Math.min(1, cap / Math.max(nw, nh));
            const dw = Math.max(16, Math.round(nw * ratio));
            const dh = Math.max(16, Math.round(nh * ratio));
            if (!optFitCanvas) {
                optFitCanvas = document.createElement('canvas');
                optFitCtx = optFitCanvas.getContext('2d', { willReadFrequently: true });
            }
            if (!optFitCtx) return null;
            if (optFitCanvas.width !== dw) optFitCanvas.width = dw;
            if (optFitCanvas.height !== dh) optFitCanvas.height = dh;
            optFitCtx.clearRect(0, 0, dw, dh);
            optFitCtx.drawImage(sourceEl, 0, 0, dw, dh);
            const data = optFitCtx.getImageData(0, 0, dw, dh).data;
            return detectStudioContentBounds(data, dw, dh, nw, nh);
        } catch (e) {
            return null;
        }
    }

    function resolveImgBoxRatio(imgEl, overrideRatio) {
        if (Number(overrideRatio) > 0.1) return Number(overrideRatio);
        if (imgEl) {
            const attrRatio = Number(imgEl.getAttribute && imgEl.getAttribute('data-box-ratio'));
            if (attrRatio > 0.1) return attrRatio;
            const cw = imgEl.clientWidth || 0;
            const ch = imgEl.clientHeight || 0;
            if (cw >= 24 && ch >= 24) return cw / ch;
        }
        return 1;
    }

    function applyOptFitVars(imgEl, bboxOrFit, overrideRatio) {
        if (!imgEl) return;
        if (!bboxOrFit || bboxOrFit === 'skip') {
            imgEl.style.removeProperty('--opt-scale');
            imgEl.style.removeProperty('--opt-tx');
            imgEl.style.removeProperty('--opt-ty');
            return;
        }
        const fit = (typeof bboxOrFit.uMin === 'number')
            ? computeOpticalFitForBox(bboxOrFit, resolveImgBoxRatio(imgEl, overrideRatio))
            : bboxOrFit;
        if (!fit || fit === 'skip') {
            imgEl.style.removeProperty('--opt-scale');
            imgEl.style.removeProperty('--opt-tx');
            imgEl.style.removeProperty('--opt-ty');
            return;
        }
        if (fit.s && Math.abs(fit.s - 1) > 0.01) {
            imgEl.style.setProperty('--opt-scale', String(fit.s));
        } else {
            imgEl.style.removeProperty('--opt-scale');
        }
        if (fit.tx && Math.abs(fit.tx) >= 0.5) {
            imgEl.style.setProperty('--opt-tx', String(fit.tx) + '%');
        } else {
            imgEl.style.removeProperty('--opt-tx');
        }
        if (fit.ty && Math.abs(fit.ty) >= 0.5) {
            imgEl.style.setProperty('--opt-ty', String(fit.ty) + '%');
        } else {
            imgEl.style.removeProperty('--opt-ty');
        }
    }

    function analyzeImageOpticalFit(imgEl) {
        const bbox = detectProductStudioBoundsFromSource(imgEl, 96);
        return bbox || 'skip';
    }

    window.__CREATA_OPTFIT_TEST__ = {
        detectStudioContentBounds: detectStudioContentBounds,
        computeOpticalFitForBox: computeOpticalFitForBox,
        OPTFIT_STORAGE_KEY: OPTFIT_STORAGE_KEY,
        OPTFIT_TARGET_FILL: OPTFIT_TARGET_FILL
    };

    function drainOptFitQueue() {
        optFitScheduled = false;
        const map = loadOptFitMap();
        let processed = 0;
        let dirty = false;
        while (optFitQueue.length > 0 && processed < 8) {
            const imgEl = optFitQueue.shift();
            if (!imgEl || !imgEl.isConnected) continue;
            const fid = imgEl.getAttribute('data-fid') || '';
            if (fid && Object.prototype.hasOwnProperty.call(map, fid)) {
                applyOptFitVars(imgEl, map[fid]);
                continue;
            }
            const bbox = analyzeImageOpticalFit(imgEl);
            if (fid) {
                map[fid] = bbox;
                dirty = true;
            }
            applyOptFitVars(imgEl, bbox);
            processed++;
        }
        if (dirty) scheduleSaveOptFitMap();
        if (optFitQueue.length > 0) scheduleOptFitDrain();
    }

    function scheduleOptFitDrain() {
        if (optFitScheduled) return;
        optFitScheduled = true;
        if (typeof window.requestIdleCallback === 'function') {
            window.requestIdleCallback(drainOptFitQueue, { timeout: 300 });
        } else {
            setTimeout(drainOptFitQueue, 16);
        }
    }

    window.__invOnCardImgLoad = function (imgEl) {
        if (!imgEl || !imgEl.getAttribute('data-card-img')) return;
        const fid = imgEl.getAttribute('data-fid') || '';
        const map = loadOptFitMap();
        if (fid && Object.prototype.hasOwnProperty.call(map, fid)) {
            applyOptFitVars(imgEl, map[fid]);
            return;
        }
        optFitQueue.push(imgEl);
        scheduleOptFitDrain();
    };

    window.__invHandleCardImgError = function (imgEl) {
        if (!imgEl) return;
        const fid = imgEl.getAttribute('data-fid') || '';
        const step = parseInt(imgEl.getAttribute('data-fb-step') || '0', 10);
        if (fid && /^[a-zA-Z0-9_-]{15,}$/.test(fid)) {
            if (step === 0) {
                imgEl.setAttribute('data-fb-step', '1');
                try { imgEl.removeAttribute('crossorigin'); } catch (e) {}
                imgEl.crossOrigin = null;
                imgEl.src = 'https://lh3.googleusercontent.com/d/' + encodeURIComponent(fid) + '=w600';
                return;
            }
            if (step === 1) {
                imgEl.setAttribute('data-fb-step', '2');
                try { imgEl.removeAttribute('crossorigin'); } catch (e) {}
                imgEl.src = 'https://drive.google.com/thumbnail?id=' + encodeURIComponent(fid) + '&sz=w800';
                return;
            }
            if (step === 2) {
                imgEl.setAttribute('data-fb-step', '3');
                try { imgEl.removeAttribute('crossorigin'); } catch (e) {}
                imgEl.src = 'https://drive.google.com/uc?export=view&id=' + encodeURIComponent(fid);
                return;
            }
        }
        imgEl.onerror = null;
        if (fid) failedDrivePhotoIds.add(fid);
        const stage = imgEl.parentElement;
        if (stage) {
            stage.classList.add('is-empty');
            stage.innerHTML = '<div class="inv-thumb-placeholder">' + THUMB_PLACEHOLDER_SVG + '</div>';
        }
    };

    window.__invHandleSwatchImgError = function (imgEl) {
        if (!imgEl) return;
        const fid = imgEl.getAttribute('data-fid') || '';
        const step = parseInt(imgEl.getAttribute('data-fb-step') || '0', 10);
        if (fid && /^[a-zA-Z0-9_-]{15,}$/.test(fid)) {
            if (step === 0) {
                imgEl.setAttribute('data-fb-step', '1');
                try { imgEl.removeAttribute('crossorigin'); } catch (e) {}
                imgEl.src = 'https://drive.google.com/thumbnail?id=' + encodeURIComponent(fid) + '&sz=w600';
                return;
            }
            if (step === 1) {
                imgEl.setAttribute('data-fb-step', '2');
                imgEl.src = 'https://drive.google.com/uc?export=view&id=' + encodeURIComponent(fid);
                return;
            }
        }
        imgEl.onerror = null;
        imgEl.style.display = 'none';
        const parentEl = imgEl.parentElement;
        if (parentEl && parentEl.classList && parentEl.classList.contains('inv-fabric-choice-stage') && !parentEl.querySelector('.inv-fabric-choice-empty')) {
            const zoomBtn = parentEl.querySelector('.inv-fabric-choice-zoom');
            if (zoomBtn) zoomBtn.style.display = 'none';
            const fbDiv = document.createElement('div');
            fbDiv.className = 'inv-fabric-choice-empty';
            fbDiv.innerHTML = '<span class="inv-fabric-choice-empty-ico" aria-hidden="true">🧵</span><span>Tela / Color</span>';
            parentEl.appendChild(fbDiv);
        }
    };

    function buildThumbHtml(it, opts) {
        const o = opts || {};
        const url = photoUrlForItem(it);
        const fid = it ? extractDriveFileId(it.f) : '';
        if (!url || (fid && failedDrivePhotoIds.has(fid))) {
            return '<div class="inv-thumb"><div class="inv-thumb-stage is-empty"><div class="inv-thumb-placeholder">' + THUMB_PLACEHOLDER_SVG + '</div></div></div>';
        }
        let targetUrl = url;
        if (fid) {
            const sz = o.compact
                ? '=w160'
                : (o.card && typeof window !== 'undefined' && window.innerWidth >= 768 ? '=w600' : '=w400');
            targetUrl = 'https://lh3.googleusercontent.com/d/' + fid + sz;
        }
        const loadingAttr = o.eager ? 'loading="eager" fetchpriority="high"' : 'loading="lazy"';
        const enableOptFit = !!(o.card || o.compact);
        const boxRatio = Number(o.boxRatio) > 0.1 ? Number(o.boxRatio) : 1;
        const cardAttr = enableOptFit ? (' data-card-img="1" data-box-ratio="' + boxRatio.toFixed(4) + '"') : '';
        let inlineFitStyle = '';
        if (enableOptFit && fid) {
            const cachedBbox = loadOptFitMap()[fid];
            if (cachedBbox && cachedBbox !== 'skip') {
                const cachedFit = (typeof cachedBbox.uMin === 'number')
                    ? computeOpticalFitForBox(cachedBbox, boxRatio)
                    : cachedBbox;
                if (cachedFit && cachedFit !== 'skip') {
                    const parts = [];
                    if (cachedFit.s && Math.abs(cachedFit.s - 1) > 0.01) parts.push('--opt-scale:' + cachedFit.s);
                    if (cachedFit.tx && Math.abs(cachedFit.tx) >= 0.5) parts.push('--opt-tx:' + cachedFit.tx + '%');
                    if (cachedFit.ty && Math.abs(cachedFit.ty) >= 0.5) parts.push('--opt-ty:' + cachedFit.ty + '%');
                    if (parts.length) inlineFitStyle = ' style="' + parts.join(';') + '"';
                }
            }
        }
        return '<div class="inv-thumb"><div class="inv-thumb-stage">' +
            '<img ' + loadingAttr + ' decoding="async" referrerpolicy="no-referrer" crossorigin="anonymous" draggable="false" alt=""' +
            cardAttr + (fid ? (' data-fid="' + escapeHtml(fid) + '"') : '') + inlineFitStyle +
            ' src="' + escapeHtml(targetUrl) + '"' +
            (enableOptFit ? ' onload="window.__invOnCardImgLoad&&window.__invOnCardImgLoad(this)"' : '') +
            ' onerror="window.__invHandleCardImgError&&window.__invHandleCardImgError(this)">' +
            '</div></div>';
    }
    window.__INV_THUMB_PH = THUMB_PLACEHOLDER_SVG;

    function formatTitleWithPriceHtml(titleText, priceStr) {
        const cleanTitle = escapeHtml(titleText || '');
        const cleanPr = formatPrice(priceStr);
        if (!cleanPr) return cleanTitle;
        return cleanTitle + ' <span class="font-extrabold" style="color:#A38251;">— ' + escapeHtml(cleanPr) + '</span>';
    }

    function formatTitleWithPricePlain(titleText, priceStr) {
        const cleanTitle = String(titleText || '').trim();
        const cleanPr = formatPrice(priceStr);
        if (!cleanPr) return cleanTitle;
        return cleanTitle + ' — ' + cleanPr;
    }

    function parseSheetDate(rawStr) {
        const s = cleanStr(rawStr);
        if (!s) return null;
        const m1 = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
        if (m1) {
            const d = parseInt(m1[1], 10);
            const m = parseInt(m1[2], 10) - 1;
            let y = parseInt(m1[3], 10);
            if (y < 100) y += 2000;
            const dt = new Date(y, m, d);
            dt.setHours(0, 0, 0, 0);
            return isNaN(dt.getTime()) ? null : dt;
        }
        const m2 = s.match(/^(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})$/);
        if (m2) {
            const dt = new Date(parseInt(m2[1], 10), parseInt(m2[2], 10) - 1, parseInt(m2[3], 10));
            dt.setHours(0, 0, 0, 0);
            return isNaN(dt.getTime()) ? null : dt;
        }
        return null;
    }

    // Holgura operativa solicitada: +2 semanas (+14 días) sobre la Fecha compromiso del proveedor (LPPT Col F)
    const SUPPLIER_COMMITMENT_BUFFER_DAYS = 14;

    function formatDateDMY(dt) {
        if (!dt || isNaN(dt.getTime())) return '';
        const dd = String(dt.getDate()).padStart(2, '0');
        const mm = String(dt.getMonth() + 1).padStart(2, '0');
        const yyyy = dt.getFullYear();
        return dd + '/' + mm + '/' + yyyy;
    }

    function addDaysLocal(dt, days) {
        if (!dt || isNaN(dt.getTime())) return null;
        const copy = new Date(dt.getTime());
        copy.setDate(copy.getDate() + (Number(days) || 0));
        copy.setHours(0, 0, 0, 0);
        return copy;
    }

    function shiftDateStringDays(rawStr, days) {
        const clean = cleanStr(rawStr);
        if (!clean) return '';
        const parsed = parseSheetDate(clean);
        if (!parsed) return clean;
        const shifted = addDaysLocal(parsed, days);
        return shifted ? formatDateDMY(shifted) : clean;
    }

    function formatSpanishDayMonth(dt) {
        if (!dt || isNaN(dt.getTime())) return '';
        const dayNum = dt.getDate();
        const monthName = MONTHS_ES[dt.getMonth()] || '';
        return dayNum + ' de ' + monthName;
    }

    // Días restantes para la llegada de la pieza en LPPT (null si no hay dato o no tiene piezas en LPPT)
    function getItemLpptRemainingDays(it) {
        if (!it || getLpptStock(it) <= 0) return null;
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        const feRaw = cleanStr(it.fe);
        if (feRaw && feRaw !== 'Sin piezas solicitadas') {
            const dFe = parseSheetDate(feRaw);
            if (dFe) {
                return Math.max(0, Math.round((dFe.getTime() - today.getTime()) / 86400000));
            }
        }

        const fcompRaw = cleanStr(it.fcomp);
        if (fcompRaw) {
            const dComp = parseSheetDate(fcompRaw);
            if (dComp) {
                return Math.max(0, Math.round((dComp.getTime() - today.getTime()) / 86400000));
            }
        }

        if (it.lt !== '' && it.lt !== null && it.lt !== undefined) {
            const ltNum = Number(it.lt);
            if (!isNaN(ltNum) && isFinite(ltNum) && ltNum >= 0) {
                return Math.round(ltNum);
            }
        }
        return null;
    }

    function getItemLpptDaysBucket(it) {
        const days = getItemLpptRemainingDays(it);
        if (days === null || days === undefined || !isFinite(days)) return '';
        const d = Math.round(days);
        for (let i = 0; i < LPPT_DAY_RANGES.length; i++) {
            const r = LPPT_DAY_RANGES[i];
            if (d >= r.min && d <= r.max) return r.key;
        }
        return '';
    }

    // Construye el mensaje de LPPT mostrando los días faltantes y, si existe, la fecha compromiso del proveedor
    function formatLpptArrivalText(it, lpptQty) {
        const qty = Math.max(0, Number(lpptQty) || 0);
        if (qty <= 0) return '';

        const today = new Date();
        today.setHours(0, 0, 0, 0);

        let arrivalDate = null;
        const feRaw = cleanStr(it && it.fe);
        if (feRaw && feRaw !== 'Sin piezas solicitadas') {
            arrivalDate = parseSheetDate(feRaw);
        }

        const fcompRaw = cleanStr(it && it.fcomp);
        const compDate = fcompRaw ? parseSheetDate(fcompRaw) : null;

        const remDays = getItemLpptRemainingDays(it);
        if (!arrivalDate && remDays !== null) {
            const d = new Date(today.getTime());
            d.setDate(d.getDate() + remDays);
            arrivalDate = d;
        }

        const dispWord = qty === 1 ? 'disponible' : 'disponibles';
        const parts = ['LPPT: ' + qty + ' ' + dispWord];

        if (remDays !== null) {
            if (remDays === 0) {
                parts.push('Por llegar (0 días restantes)');
            } else if (remDays === 1) {
                parts.push('Falta 1 día por llegar');
            } else {
                parts.push('Faltan ' + remDays + ' días por llegar');
            }
        }

        if (compDate) {
            parts.push('Fecha compromiso proveedor: ' + formatDateDMY(compDate) + ' (' + formatSpanishDayMonth(compDate) + ')');
        } else if (arrivalDate) {
            const dayMonth = formatSpanishDayMonth(arrivalDate);
            if (dayMonth) parts.push('Entrega estimada: ' + dayMonth);
        }

        return parts.join(' · ');
    }

    function buildSinglePieceCoverGroup(it, skuKey, fallbackGroupTitle) {
        const pieceTitle = (
            it._singleTitle ||
            stripDimensionsFromProductText(it.n) ||
            fallbackGroupTitle ||
            skuKey
        ).toUpperCase();
        const wordList = Array.from(new Set((it._search || '').split(/\s+/).filter(w => w.length >= 2)));
        return {
            key: 'all_sku_' + skuKey,
            title: pieceTitle,
            displayTitle: pieceTitle,
            tp: cleanStr(it.tp).toUpperCase(),
            mo: cleanStr(it.mo).toUpperCase(),
            items: [it],
            totalStock: getBodegaPisoStock(it),
            lpptStock: getLpptStock(it),
            _hasPhoto: it._hasPhoto ? 1 : 0,
            _mainRank: it._mainRank,
            _subRank: it._subRank,
            _typeRank: it._typeRank,
            _plain: it._plain || '',
            _search: it._search || '',
            _titleSearch: normSearch(pieceTitle),
            _compact: (it._search || '').replace(/\s+/g, ''),
            _words: wordList,
            _stems: new Set(wordList.map(stemEs)),
            _roots: new Set(wordList.map(rootEs)),
            _titleTokens: normSearch(pieceTitle).split(/\s+/).filter(Boolean),
            _modelTokens: it.mo ? normSearch(it.mo).split(/\s+/).filter(Boolean) : []
        };
    }

    const FOTOS_SAVED_OVERRIDES_STORAGE_KEY = 'creata_fotos_saved_overrides_v1';
    const FOTOS_DELETED_QUEUE_STORAGE_KEY = 'creata_fotos_deleted_queue_v1';
    const FOTOS_SYNC_BROADCAST_CHANNEL = 'creata_fotos_cotizador_sync_v1';

    function applyStoredFotosOverridesToItems(itemsArr) {
        if (!Array.isArray(itemsArr) || !itemsArr.length) return false;
        let savedBySku = null;
        let delSkus = null;
        let delFiles = null;
        const now = Date.now();
        const maxSavedAgeMs = 7 * 24 * 60 * 60 * 1000;
        const maxDelAgeMs = 24 * 60 * 60 * 1000;

        try {
            const rawDel = localStorage.getItem(FOTOS_DELETED_QUEUE_STORAGE_KEY);
            if (rawDel) {
                const parsedDel = JSON.parse(rawDel);
                if (parsedDel && typeof parsedDel === 'object') {
                    if (parsedDel.skus && typeof parsedDel.skus === 'object') {
                        delSkus = parsedDel.skus;
                    }
                    if (parsedDel.fileIds && typeof parsedDel.fileIds === 'object') {
                        delFiles = {};
                        Object.keys(parsedDel.fileIds).forEach(function (fid) {
                            const ts = Number(parsedDel.fileIds[fid] || 0);
                            if (!ts || (now - ts) <= maxDelAgeMs) {
                                delFiles[fid] = 1;
                            }
                        });
                    }
                }
            }
        } catch (eDel) {}

        try {
            const rawSaved = localStorage.getItem(FOTOS_SAVED_OVERRIDES_STORAGE_KEY);
            if (rawSaved) {
                const list = JSON.parse(rawSaved);
                if (Array.isArray(list) && list.length > 0) {
                    savedBySku = new Map();
                    for (let i = 0; i < list.length; i++) {
                        const ov = list[i];
                        if (!ov || !ov.sku || !ov.newUrl) continue;
                        const cleanUrl = sanitizeVisualOverrideUrl(cleanStr(ov.newUrl));
                        if (!cleanUrl) continue;
                        if (ov.ts && (now - Number(ov.ts)) > maxSavedAgeMs) continue;
                        const sk = cleanStr(ov.sku).toUpperCase();
                        if (!sk || savedBySku.has(sk)) continue;
                        const fid = cleanStr(ov.fileId || extractDriveFileId(cleanUrl));
                        if ((delSkus && delSkus[sk]) || (fid && delFiles && delFiles[fid])) continue;
                        savedBySku.set(sk, {
                            newUrl: cleanUrl,
                            fileId: fid,
                            previousUrl: cleanStr(ov.previousUrl)
                        });
                    }
                }
            }
        } catch (eSaved) {}

        if (!savedBySku && !delSkus && !delFiles) return false;

        let mutated = false;
        for (let i = 0; i < itemsArr.length; i++) {
            const it = itemsArr[i];
            if (!it || !it.s) continue;
            const skuKey = String(it.s).trim().toUpperCase();
            const curFid = extractDriveFileId(it.f);

            if ((delSkus && delSkus[skuKey]) || (curFid && delFiles && delFiles[curFid])) {
                if (it.f) {
                    it.f = '';
                    mutated = true;
                }
                continue;
            }

            if (savedBySku && savedBySku.has(skuKey)) {
                const ov = savedBySku.get(skuKey);
                const savedFid = ov.fileId;
                const prevFid = extractDriveFileId(ov.previousUrl);
                if (!curFid || curFid === savedFid || (prevFid && curFid === prevFid)) {
                    if (it.f !== ov.newUrl) {
                        it.f = ov.newUrl;
                        if (savedFid) failedDrivePhotoIds.delete(savedFid);
                        mutated = true;
                    }
                }
            }
        }
        return mutated;
    }

    function indexItemsAndGroups() {
        applyStoredFotosOverridesToItems(allItems);
        rebuildLiveAutoVocab(allItems);
        allItems.sort((a, b) =>
            compareAlphaEs(a && (a.n || a.s), b && (b.n || b.s)) ||
            String((a && a.s) || '').localeCompare(String((b && b.s) || ''))
        );

        bySkuMap.clear();
        bySkuNormMap.clear();
        singleBySkuMap.clear();
        groupsByKey.clear();
        activeFilteredGroupsByKey.clear();
        allSingleGroups = [];
        allGroups = [];

        sofaAndLoveseatModels = new Set();
        exteriorSofaAndLoveseatModels = new Set();
        exteriorSalaSetModels = new Set();
        exteriorModularModels = new Set();
        dynamicSofaCamaModels = new Set();
        bedUnifiedModels = new Set();

        // Pre-pasada 1: normalizar campos base, validar tela/color contra nombre y detectar modelos con Sofá Cama (ej. CITY)
        for (let i = 0; i < allItems.length; i++) {
            const it = allItems[i];
            if (!Array.isArray(it.st)) it.st = emptyStocks();
            it.pr = formatPrice(it.pr);
            const skuKey = String(it.s || '').trim().toUpperCase();
            if (!skuKey) continue;
            const curFabSig = [it.n || '', it.tp || '', it.tl || '', it.ct || '', it.cm || ''].join('\x1f');
            if (it._fabValSig !== curFabSig) {
                validateAndNormalizeFabricColorAgainstName(it, { mutate: true });
            }
            it._avail = getItemAvailabilityKind(it);
            const pairMoKey = extractPlainModelKeyForPairing(it);
            if (pairMoKey) {
                const prodTok = (plainModelToken(stripDimensionsFromProductText(it.tp)) + ' ' + plainModelToken(stripDimensionsFromProductText(it.n))).trim();
                if (/\b(SOFAS?\s*CAMAS?|SOFA-CAMA)\b/.test(prodTok)) {
                    dynamicSofaCamaModels.add(pairMoKey);
                }
            }
        }

        // Pre-pasada 2: clasificar subcategorías y detectar pares Sofá + Love Seat, colecciones de Exterior y familias de Camas/Bases/Cabeceras
        const salaPairFlags = new Map();
        const extSeatFlags = new Map();
        const bedFamilyFlags = new Map();
        for (let i = 0; i < allItems.length; i++) {
            const it = allItems[i];
            const skuKey = String(it.s || '').trim().toUpperCase();
            if (!skuKey) continue;
            it._cat = resolveItemSubcategory(it, resolveItemCategory(it));
            it._main = MAIN_OF_SUB[it._cat] || 'ESPEJOS Y ACCESORIOS';
            if (!it._avail || !isQuotableItem(it)) continue;

            const pairMoKey = extractPlainModelKeyForPairing(it);
            if (!pairMoKey) continue;
            const tpTok = plainModelToken(stripDimensionsFromProductText(it.tp));
            const nomTok = plainModelToken(stripDimensionsFromProductText(it.n));
            const prodTok = (tpTok + ' ' + nomTok).trim();

            if (it._cat === 'SOFAS & LOVESEATS') {
                let f = salaPairFlags.get(pairMoKey);
                if (!f) { f = { hasSofa: false, hasLoveSeat: false }; salaPairFlags.set(pairMoKey, f); }
                if (/^(LOVE\s*SEAT|LOVESEAT)\b/.test(tpTok) || /\b(LOVE\s*SEATS?|LOVESEATS?)\b/.test(prodTok)) {
                    f.hasLoveSeat = true;
                } else if (/^SOFA\b/.test(tpTok) || /\bSOFAS?\b/.test(prodTok)) {
                    f.hasSofa = true;
                }
            } else if ((it._cat === 'CAMAS' || it._cat === 'BASES' || it._cat === 'CABECERAS') && tpTok !== 'LITERA' && tpTok !== 'CUNA') {
                let bf = bedFamilyFlags.get(pairMoKey);
                if (!bf) { bf = { hasCama: false, hasBase: false, hasCabecera: false }; bedFamilyFlags.set(pairMoKey, bf); }
                if (it._cat === 'CAMAS') bf.hasCama = true;
                else if (it._cat === 'BASES') bf.hasBase = true;
                else if (it._cat === 'CABECERAS') bf.hasCabecera = true;
            } else if (it._cat === 'EXTERIOR') {
                const isNonSeatExt = /\b(MESA|COMEDOR|CAMASTRO|COLUMPIO|SOMBRILLA)\b/.test(prodTok) || /^SILLA\b/.test(tpTok);
                if (!isNonSeatExt && /\b(SALAS?|SOFAS?|LOVE\s*SEATS?|LOVESEATS?|ESQUINEROS?|CHAISE|OTTOMAN|OTOMAN|MODULAR|MODULO|REMATE|SILLON(?:ES)?)\b/.test(prodTok)) {
                    let f = extSeatFlags.get(pairMoKey);
                    if (!f) {
                        f = { hasModular: false, hasSofa: false, hasLoveSeat: false, hasSillon: false, hasOttoman: false };
                        extSeatFlags.set(pairMoKey, f);
                    }
                    if (/\b(MODULAR(?:ES)?|MODULOS?|ESQUINEROS?|REMATES?|SIN\s+BRAZOS?|BRAZO\s+(?:DER|IZQ)|DERECHO|DEREHO|IZQUIERDO)\b/.test(prodTok)) {
                        f.hasModular = true;
                    }
                    if (/^(LOVE\s*SEAT|LOVESEAT)\b/.test(tpTok) || /\b(LOVE\s*SEATS?|LOVESEATS?)\b/.test(prodTok)) {
                        f.hasLoveSeat = true;
                    } else if (/^SOFA\b/.test(tpTok) || /\bSOFAS?\b/.test(prodTok)) {
                        f.hasSofa = true;
                    } else if (/^SILLON\b/.test(tpTok) || /\bSILLON(?:ES)?\b/.test(prodTok)) {
                        f.hasSillon = true;
                    } else if (/\b(OTTOMAN|OTOMAN|POUF|PUFF)\b/.test(prodTok)) {
                        f.hasOttoman = true;
                    }
                }
            }
        }
        salaPairFlags.forEach((f, moKey) => {
            if (f.hasSofa && f.hasLoveSeat) sofaAndLoveseatModels.add(moKey);
        });
        bedFamilyFlags.forEach((bf, moKey) => {
            const typeCount = (bf.hasCama ? 1 : 0) + (bf.hasBase ? 1 : 0) + (bf.hasCabecera ? 1 : 0);
            if (typeCount >= 2) bedUnifiedModels.add(moKey);
        });
        extSeatFlags.forEach((f, moKey) => {
            if (f.hasModular) {
                exteriorModularModels.add(moKey);
            } else if (f.hasSofa && f.hasLoveSeat) {
                exteriorSofaAndLoveseatModels.add(moKey);
            } else {
                const kindCount = (f.hasSofa ? 1 : 0) + (f.hasLoveSeat ? 1 : 0) + (f.hasSillon ? 1 : 0) + (f.hasOttoman ? 1 : 0);
                if (kindCount >= 2) exteriorSalaSetModels.add(moKey);
            }
        });

        for (let i = 0; i < allItems.length; i++) {
            const it = allItems[i];
            const skuKey = String(it.s || '').trim().toUpperCase();
            if (!skuKey) continue;

            const grpId = computeCategoryGroupIdentity(it);
            const title = grpId.title;
            const gKey = grpId.key;
            it._groupKey = gKey;
            it._groupTitle = title;
            it._singleTitle = grpId.singleTitle || title;
            it._grpMo = grpId.mo || '';
            it._typeKey = grpId.typeKey || '';
            it._typeLabel = grpId.typeLabel || '';
            it._typeRank = typeof grpId.typeRank === 'number' ? grpId.typeRank : 999;

            it._lpptBucket = getLpptStock(it) >= 1 ? getItemLpptDaysBucket(it) : '';
            it._hasPhoto = photoUrlForItem(it) ? 1 : 0;
            it._mainRank = getMainCategoryRank(it._main);
            it._subRank = getSubCategoryRank(it._cat);

            const rawText = [
                it.s, title, it._singleTitle, it.n, it.vr, it.tp, it._typeLabel, it.mo, grpId.mo, it._cat, it._main,
                it.tl, it.ct, it.md, it.cm, it.mt, it.m, it.p, it.pr
            ].join(' ');
            it._plain = normalizePlain(rawText);
            it._search = normSearch(rawText);

            bySkuMap.set(skuKey, it);
            const skuNormKey = skuKey.replace(/[^A-Z0-9]+/g, '');
            if (skuNormKey) {
                const prevNorm = bySkuNormMap.get(skuNormKey);
                if (!prevNorm || (!isQuotableItem(prevNorm) && isQuotableItem(it))) {
                    bySkuNormMap.set(skuNormKey, it);
                }
            }

            // Cotizador: solo se muestran piezas con al menos 1 pz en Bodega/Piso
            // o piezas de LPPT con registro y precio en S Mueblería (excluyendo ARCHIVADO/ELIMINADO).
            // El resto queda oculto (sigue en bySkuMap para conservar partidas previas).
            if (!it._avail || !isQuotableItem(it)) continue;

            // Vista separada pieza por pieza para CATEGORÍAS
            const singleEntry = buildSinglePieceCoverGroup(it, skuKey, title);
            singleBySkuMap.set(skuKey, singleEntry);
            allSingleGroups.push(singleEntry);

            // Vista agrupada por Tipo de Mueble + Modelo en TODOS y en subcategorías agrupadas (Salas / Exterior)
            let grp = groupsByKey.get(gKey);
            if (!grp) {
                grp = {
                    key: gKey,
                    title: title,
                    tp: cleanStr(it.tp).toUpperCase(),
                    typeKey: grpId.typeKey || '',
                    typeLabel: grpId.typeLabel || '',
                    mo: grpId.mo || cleanStr(it.mo).toUpperCase(),
                    items: [],
                    _plainParts: [],
                    _searchParts: []
                };
                groupsByKey.set(gKey, grp);
                allGroups.push(grp);
            }
            grp.items.push(it);
            grp._plainParts.push(it._plain);
            grp._searchParts.push(it._search);
            if (!grp.cats) grp.cats = new Set();
            if (!grp.mains) grp.mains = new Set();
            if (!grp.avails) grp.avails = new Set();
            if (!grp.lpptBuckets) grp.lpptBuckets = new Set();
            if (it._cat) grp.cats.add(it._cat);
            if (it._main) grp.mains.add(it._main);
            grp.avails.add(it._avail);
            if (it._lpptBucket) grp.lpptBuckets.add(it._lpptBucket);
        }

        for (let i = 0; i < allGroups.length; i++) {
            const grp = allGroups[i];
            grp.items.sort((a, b) =>
                compareAlphaEs(a.n || a.vr || a.s, b.n || b.vr || b.s) ||
                String(a.s || '').localeCompare(String(b.s || ''))
            );
            if (grp.items.length > 1 && grp.mo) {
                let bestMo = grp.mo;
                for (let j = 0; j < grp.items.length; j++) {
                    const candMo = grp.items[j]._grpMo;
                    if (!candMo) continue;
                    const candPlain = normalizePlain(candMo);
                    const isTypo = Object.prototype.hasOwnProperty.call(MODEL_TYPO_ALIASES, candPlain) && candPlain !== 'benzio iii';
                    if (isTypo) continue;
                    if (/\s+(?:SW|II|III|IV)$/.test(plainModelToken(candMo))) {
                        bestMo = candMo;
                        break;
                    }
                    if (candMo.length < bestMo.length || Object.prototype.hasOwnProperty.call(MODEL_TYPO_ALIASES, normalizePlain(bestMo))) {
                        bestMo = candMo;
                    }
                }
                grp.mo = bestMo;

                let chosenPrefix = grp.typeLabel || stripDimensionsFromProductText(grp.items[0].tp).toUpperCase();
                if (grp.typeKey === 'MESA_COMEDOR') {
                    const anyExplicitDining = grp.items.some(x => x._typeLabel === 'MESA DE COMEDOR');
                    chosenPrefix = anyExplicitDining ? 'MESA DE COMEDOR' : 'MESA';
                } else if (grp.typeKey === 'COMODA') {
                    const allCajonera = grp.items.every(x => x._typeLabel === 'CAJONERA');
                    chosenPrefix = allCajonera ? 'CAJONERA' : 'CÓMODA';
                } else if (grp.typeKey === 'CAMA_CONJUNTO') {
                    chosenPrefix = resolveBedUnifiedTitlePrefix(grp.items);
                }
                if (chosenPrefix) {
                    const fpPad = ' ' + plainModelToken(chosenPrefix) + ' ';
                    const moPad = ' ' + plainModelToken(bestMo) + ' ';
                    grp.title = (fpPad.indexOf(moPad) !== -1 ? chosenPrefix : (chosenPrefix + ' ' + bestMo)).toUpperCase();
                    for (let j = 0; j < grp.items.length; j++) {
                        grp.items[j]._groupTitle = grp.title;
                    }
                }

                // NUNCA mezclar ni propagar Madera, Color de madera, Materiales, Medidas ni Modelo entre SKUs distintos:
                // cada SKU conserva estrictamente los datos propios de su fila en CONTROL DE PRODUCTOS PRESENTACIÓN (INVENTARIO_EN_VIVO).
            }
            grp.displayTitle = (grp.items.length > 1
                ? grp.title
                : (grp.items[0]._singleTitle || stripDimensionsFromProductText(grp.items[0].n) || grp.title || grp.items[0].s)
            ).toUpperCase();
            grp.moduleCount = countDistinctModulesForGroup(grp.typeKey, grp.items);
            grp.variationCount = countDistinctFabricsForGroup(grp.typeKey, grp.items);
            grp.bedSizeCount = countDistinctBedSizesForGroup(grp.typeKey, grp.items);
            grp.bedColorCount = countDistinctBedColorsForGroup(grp.typeKey, grp.items);
            grp.bedWoodOnly = !!(grp.typeKey && BED_GROUPABLE_TYPE_KEYS.has(grp.typeKey) && isBedGroupWoodOnly(grp.items));
            grp.totalStock = grp.items.reduce((acc, x) => acc + getBodegaPisoStock(x), 0);
            grp.lpptStock = grp.items.reduce((acc, x) => acc + getLpptStock(x), 0);
            grp._hasPhoto = (getGroupVisualCoverPhotoUrl(grp.key) || firstPhotoItem(grp.items)) ? 1 : 0;
            grp._mainRank = grp.items.reduce((m, x) => Math.min(m, typeof x._mainRank === 'number' ? x._mainRank : 99), 99);
            grp._subRank = grp.items.reduce((m, x) => Math.min(m, typeof x._subRank === 'number' ? x._subRank : 999), 999);
            grp._typeRank = grp.items.reduce((m, x) => Math.min(m, typeof x._typeRank === 'number' ? x._typeRank : 999), 999);
            grp._plain = grp._plainParts.join(' ');
            grp._search = grp._searchParts.join(' ');
            grp._titleSearch = normSearch(grp.displayTitle || grp.title);
            grp._compact = grp._search.replace(/\s+/g, '');
            const wordList = Array.from(new Set(grp._search.split(/\s+/).filter(w => w.length >= 2)));
            grp._words = wordList;
            grp._stems = new Set(wordList.map(stemEs));
            grp._roots = new Set(wordList.map(rootEs));
            grp._titleTokens = normSearch(grp.title).split(/\s+/).filter(Boolean);
            grp._modelTokens = grp.mo ? normSearch(grp.mo).split(/\s+/).filter(Boolean) : [];
            delete grp._plainParts;
            delete grp._searchParts;
        }

        allSingleGroups.sort(compareCommercialGroupOrder);
        allGroups.sort(compareCommercialGroupOrder);

        // Publicar índice compacto de modelos (Portadas) y telas/colores (VFAB) para la App de Subida de Fotos
        try {
            if (typeof localStorage !== 'undefined') {
                const coversIdx = [];
                const fabricsMap = new Map();
                for (let gIdx = 0; gIdx < allGroups.length; gIdx++) {
                    const g = allGroups[gIdx];
                    if (!g || !Array.isArray(g.items) || g.items.length < 2) continue;
                    const isModType = !!(g.typeKey && MODULE_GROUPABLE_TYPE_KEYS.has(g.typeKey));
                    const subCat = g.cats && g.cats.size ? Array.from(g.cats)[0] : '';
                    const mainCat = g.mains && g.mains.size ? Array.from(g.mains)[0] : '';
                    const samplePhotoIt = firstPhotoItem(g.items);
                    coversIdx.push({
                        groupKey: g.key,
                        overrideKey: buildVisualCoverOverrideKey(g.key),
                        title: g.displayTitle || g.title,
                        subCat: subCat,
                        mainCat: mainCat,
                        isModular: isModType ? 1 : 0,
                        itemCount: g.items.length,
                        fabricCount: g.variationCount || g.bedColorCount || 0,
                        samplePhoto: samplePhotoIt ? sanitizeVisualOverrideUrl(samplePhotoIt.f) : ''
                    });
                    if (isModType) {
                        const seenFabInModel = new Set();
                        for (let mIdx = 0; mIdx < g.items.length; mIdx++) {
                            const fab = resolveItemFabricVariation(g.items[mIdx], g);
                            if (!fab || !fab.key) continue;
                            if (!fabricsMap.has(fab.key)) {
                                fabricsMap.set(fab.key, {
                                    fabricKey: fab.key,
                                    overrideKey: buildFabricSwatchOverrideKey(fab.key),
                                    label: fab.label,
                                    colorHint: fab.colorHint || '',
                                    modelCount: 0,
                                    moduleCount: 0,
                                    sampleModels: []
                                });
                            }
                            const fEntry = fabricsMap.get(fab.key);
                            fEntry.moduleCount++;
                            if (!fEntry.colorHint && fab.colorHint) fEntry.colorHint = fab.colorHint;
                            if (!seenFabInModel.has(fab.key)) {
                                seenFabInModel.add(fab.key);
                                fEntry.modelCount++;
                                if (fEntry.sampleModels.length < 4) fEntry.sampleModels.push(g.displayTitle || g.title);
                            }
                        }
                    }
                }
                // Incluir también telas declaradas en productos no modulares (sillones, sofás, sillas, camas, etc.)
                for (let iIdx = 0; iIdx < allItems.length; iIdx++) {
                    const it = allItems[iIdx];
                    if (!it || !cleanStr(it.tl)) continue;
                    const grp = it._groupKey ? groupsByKey.get(it._groupKey) : null;
                    if (grp && grp.items && grp.items.length >= 2 && grp.typeKey && MODULE_GROUPABLE_TYPE_KEYS.has(grp.typeKey)) continue;
                    const fab = resolveItemFabricVariation(it, grp || null);
                    if (!fab || !fab.key || fab.key === 'ESTANDAR') continue;
                    if (!fabricsMap.has(fab.key)) {
                        fabricsMap.set(fab.key, {
                            fabricKey: fab.key,
                            overrideKey: buildFabricSwatchOverrideKey(fab.key),
                            label: fab.label,
                            colorHint: fab.colorHint || '',
                            modelCount: 0,
                            moduleCount: 0,
                            sampleModels: []
                        });
                    }
                    const fEntry = fabricsMap.get(fab.key);
                    fEntry.moduleCount++;
                    const mTitle = (grp && (grp.displayTitle || grp.title)) || cleanStr(it.mo) || cleanStr(it.n) || it.s;
                    if (mTitle && fEntry.sampleModels.indexOf(mTitle) === -1) {
                        fEntry.modelCount++;
                        if (fEntry.sampleModels.length < 4) fEntry.sampleModels.push(mTitle);
                    }
                }
                const fabricsIdx = Array.from(fabricsMap.values()).sort((a, b) =>
                    (b.moduleCount - a.moduleCount) || compareAlphaEs(a.label, b.label)
                );
                localStorage.setItem('creata_visual_targets_index_v1', JSON.stringify({
                    ts: Date.now(),
                    covers: coversIdx,
                    fabrics: fabricsIdx
                }));
            }
        } catch (eVisIdx) {}
    }

    function loadCart() {
        try {
            const saved = JSON.parse(localStorage.getItem(CART_KEY) || '{}');
            return (saved && typeof saved === 'object') ? saved : {};
        } catch (e) {
            return {};
        }
    }

    function saveCart() {
        try { localStorage.setItem(CART_KEY, JSON.stringify(cart)); } catch (e) {}
        if (typeof syncActiveQuoteDraftStorage === 'function') syncActiveQuoteDraftStorage();
        updateCartBadge();
    }

    function updateCartBadge() {
        const isLockedDone = (typeof isActiveQuoteCompleted === 'function' && isActiveQuoteCompleted());
        const guestMode = (typeof isGuestSession === 'function' && isGuestSession());
        const totalQty = (isLockedDone || guestMode)
            ? 0
            : Object.values(cart).reduce((acc, row) => acc + (Number(row.qty) || 0), 0);
        const el = document.getElementById('headerCartCount');
        if (el) el.textContent = String(totalQty);
        const fabBadge = document.getElementById('invFabBadge');
        if (fabBadge) {
            fabBadge.textContent = String(totalQty);
            fabBadge.classList.toggle('hidden', totalQty <= 0 || guestMode);
        }
    }

    // ------------------------------------------------------------------------
    // PORTADA PRINCIPAL (TODOS): AGRUPADO POR TIPO DE MUEBLE + MODELO EN ORDEN COMERCIAL (CON FOTO ARRIBA Y SIN FOTO AL FINAL)
    // ------------------------------------------------------------------------
    function getMainCoverGroups() {
        return allGroups;
    }

    let activeCategory = 'ALL';
    let activeSubCategory = 'ALL';

    function itemMatchesActiveFilter(it, cat, sub) {
        if (!it || !it._avail || !isQuotableItem(it)) return false;
        if (!cat || cat === 'ALL') return true;
        if (cat === 'STOCK') {
            if (getBodegaPisoStock(it) < 1) return false;
            if (sub && sub !== 'ALL') return it._main === sub;
            return true;
        }
        if (cat === 'LPPT_STOCK') return it._avail === 'LPPT_STOCK';
        if (cat === 'LPPT') {
            if (getLpptStock(it) < 1) return false;
            if (sub && sub !== 'ALL') return it._lpptBucket === sub;
            return true;
        }
        if (it._main !== cat) return false;
        if (sub && sub !== 'ALL') return it._cat === sub;
        return true;
    }

    function formatGroupBadgeLabel(grp) {
        if (!grp || !Array.isArray(grp.items)) return '';
        const modCnt = Number(grp.moduleCount) || 0;
        const varCnt = Number(grp.variationCount) || 0;
        if (modCnt >= 2 && varCnt >= 2) {
            return varCnt + ' colores · ' + grp.items.length + ' mód.';
        }
        if (modCnt >= 2) {
            return modCnt + ' módulos · ' + grp.items.length + ' var.';
        }
        if (grp.typeKey && BED_GROUPABLE_TYPE_KEYS.has(grp.typeKey)) {
            const szCnt = Number(grp.bedSizeCount) || 0;
            const colCnt = Number(grp.bedColorCount) || 0;
            if (szCnt >= 2 && colCnt >= 2) {
                return szCnt + ' tam. · ' + colCnt + (grp.bedWoodOnly ? ' acab.' : ' colores');
            }
            if (szCnt >= 2) {
                return szCnt + ' tamaños · ' + grp.items.length + ' var.';
            }
            if (colCnt >= 2) {
                return colCnt + (grp.bedWoodOnly ? ' acabados · ' : ' colores · ') + grp.items.length + ' pzas';
            }
        }
        return grp.items.length + ' variantes';
    }

    function buildFilteredGroupView(baseGrp, matchedItems) {
        if (!baseGrp || !matchedItems || matchedItems.length === 0) return null;
        if (matchedItems.length === baseGrp.items.length) return baseGrp;
        let multiTitle = baseGrp.title;
        if (matchedItems.length > 1 && baseGrp.typeKey === 'CAMA_CONJUNTO' && baseGrp.mo) {
            const narrowPrefix = resolveBedUnifiedTitlePrefix(matchedItems);
            const fpPad = ' ' + plainModelToken(narrowPrefix) + ' ';
            const moPad = ' ' + plainModelToken(baseGrp.mo) + ' ';
            multiTitle = (fpPad.indexOf(moPad) !== -1 ? narrowPrefix : (narrowPrefix + ' ' + baseGrp.mo)).toUpperCase();
        }
        const singleTitle = (matchedItems.length > 1
            ? multiTitle
            : (matchedItems[0]._singleTitle || stripDimensionsFromProductText(matchedItems[0].n) || baseGrp.title || matchedItems[0].s)
        ).toUpperCase();
        return Object.assign({}, baseGrp, {
            items: matchedItems,
            displayTitle: singleTitle,
            moduleCount: countDistinctModulesForGroup(baseGrp.typeKey, matchedItems),
            variationCount: countDistinctFabricsForGroup(baseGrp.typeKey, matchedItems),
            bedSizeCount: countDistinctBedSizesForGroup(baseGrp.typeKey, matchedItems),
            bedColorCount: countDistinctBedColorsForGroup(baseGrp.typeKey, matchedItems),
            bedWoodOnly: !!(baseGrp.typeKey && BED_GROUPABLE_TYPE_KEYS.has(baseGrp.typeKey) && isBedGroupWoodOnly(matchedItems)),
            totalStock: matchedItems.reduce((acc, x) => acc + getBodegaPisoStock(x), 0),
            lpptStock: matchedItems.reduce((acc, x) => acc + getLpptStock(x), 0),
            _hasPhoto: (getGroupVisualCoverPhotoUrl(baseGrp.key) || firstPhotoItem(matchedItems)) ? 1 : 0,
            _mainRank: matchedItems.reduce((m, x) => Math.min(m, typeof x._mainRank === 'number' ? x._mainRank : 99), 99),
            _subRank: matchedItems.reduce((m, x) => Math.min(m, typeof x._subRank === 'number' ? x._subRank : 999), 999),
            _typeRank: matchedItems.reduce((m, x) => Math.min(m, typeof x._typeRank === 'number' ? x._typeRank : 999), 999)
        });
    }

    // Vista individual por pieza para el botón STOCK: toma únicamente la cantidad física en Bodega + Piso (sin contar LPPT)
    function buildSinglePieceStockView(baseGrp, it) {
        const ownQty = getBodegaPisoStock(it);
        if (!it || ownQty < 1) return null;
        const skuKey = String(it.s || '').trim().toUpperCase();
        const pieceTitle = (
            it._singleTitle ||
            stripDimensionsFromProductText(it.n) ||
            (baseGrp && baseGrp.title) ||
            skuKey
        ).toUpperCase();
        return {
            key: 'stock_sku_' + skuKey,
            title: pieceTitle,
            displayTitle: pieceTitle,
            tp: cleanStr(it.tp).toUpperCase(),
            mo: cleanStr(it.mo).toUpperCase(),
            items: [it],
            totalStock: ownQty,
            lpptStock: 0,
            _hasPhoto: it._hasPhoto ? 1 : 0,
            _mainRank: it._mainRank,
            _subRank: it._subRank,
            _typeRank: it._typeRank
        };
    }

    function filterItemsMatchingSearchIfSubset(matchedItems, rawTrim) {
        if (!rawTrim || matchedItems.length <= 1) return matchedItems;
        const qNorm = normSearch(rawTrim);
        const rawTokens = qNorm.split(/\s+/).filter(Boolean);
        const meaningful = rawTokens.filter(t => t.length >= 2 && !SEARCH_STOPWORDS.has(t));
        const qTokens = meaningful.length > 0 ? meaningful : rawTokens;
        if (!qTokens.length) return matchedItems;
        const directHits = matchedItems.filter(it => {
            const s = it._search || '';
            const words = s.split(/\s+/).filter(Boolean);
            return qTokens.every(tok => {
                const st = stemEs(tok);
                if (st === 'siya' || st === 'siyon') {
                    return words.some(w => stemEs(w) === st);
                }
                return s.indexOf(tok) !== -1;
            });
        });
        return directHits.length > 0 ? directHits : matchedItems;
    }

    function formatActiveFilterLabel() {
        if (activeCategory === 'ALL') return 'TODOS';
        let baseLabel = activeCategory === 'LPPT_STOCK' ? 'LPPT+STOCK' : activeCategory;
        if (activeSubCategory && activeSubCategory !== 'ALL') {
            if (activeCategory === 'LPPT') {
                baseLabel += ' (' + activeSubCategory + ' días)';
            } else {
                baseLabel += ' · ' + activeSubCategory;
            }
        }
        return baseLabel;
    }

    function searchGroupCollection(sourceGroups, rawTrim, scoreByKey) {
        const qNorm = normSearch(rawTrim);
        const rawTokens = qNorm.split(/\s+/).filter(Boolean);
        const meaningfulTokens = rawTokens.filter(t => t.length >= 2 && !SEARCH_STOPWORDS.has(t));
        const qTokens = meaningfulTokens.length > 0 ? meaningfulTokens : rawTokens;
        const compactQ = qNorm.replace(/\s+/g, '');

        if (qTokens.length === 0) {
            return sourceGroups;
        }

        const reqSilla = qTokens.some(t => stemEs(t) === 'siya');
        const reqSillon = qTokens.some(t => stemEs(t) === 'siyon');

        const candidateList = [];
        for (let i = 0; i < sourceGroups.length; i++) {
            const grp = sourceGroups[i];
            if (reqSilla && !reqSillon && (!grp._stems || !grp._stems.has('siya'))) continue;
            if (reqSillon && !reqSilla && (!grp._stems || !grp._stems.has('siyon'))) continue;
            let matchedCount = 0;
            let totalScore = 0;
            for (let t = 0; t < qTokens.length; t++) {
                const sc = scoreTokenInGroup(qTokens[t], grp);
                if (sc > 0) {
                    matchedCount++;
                    totalScore += sc;
                }
            }
            if (compactQ.length >= 4 && grp._compact && grp._compact.indexOf(compactQ) !== -1) {
                totalScore += 18;
                if (matchedCount === 0) matchedCount = 1;
            }
            if (matchedCount > 0) {
                candidateList.push({ grp: grp, matched: matchedCount, score: totalScore });
            }
        }

        // Prioridad 1: productos donde coinciden todos los términos relevantes de búsqueda
        let selected = candidateList.filter(entry => entry.matched === qTokens.length);

        // Prioridad 2: si hay varias palabras y ninguna coincide al 100%, mostrar las mejores coincidencias parciales
        if (selected.length === 0 && candidateList.length > 0) {
            selected = candidateList;
        }

        // Prioridad 3: si tampoco hubo coincidencia en búsqueda de 1 palabra, intentar tolerancia extra (2 ediciones / prefijo)
        if (selected.length === 0 && qTokens.length === 1 && qTokens[0].length >= 4 && !/\d/.test(qTokens[0]) && !reqSilla && !reqSillon) {
            const tok = qTokens[0];
            const maxExtraDist = tok.length >= 5 ? 2 : 1;
            const prefix = tok.slice(0, 3);
            for (let i = 0; i < sourceGroups.length; i++) {
                const grp = sourceGroups[i];
                let extraScore = 0;
                for (let wi = 0; wi < grp._words.length; wi++) {
                    const w = grp._words[wi];
                    if (w.length < 3) continue;
                    const wSt = stemEs(w);
                    if (wSt === 'siya' || wSt === 'siyon') continue;
                    const d = editDistanceBounded(tok, w, maxExtraDist);
                    if (d <= maxExtraDist) {
                        extraScore = Math.max(extraScore, d === 1 ? 8 : 5);
                    } else if (prefix.length >= 3 && w.startsWith(prefix)) {
                        extraScore = Math.max(extraScore, 4);
                    }
                }
                if (extraScore > 0) {
                    selected.push({ grp: grp, matched: 1, score: extraScore });
                }
            }
        }

        selected.forEach(entry => {
            scoreByKey.set(entry.grp.key, entry);
        });
        return selected.map(entry => entry.grp);
    }

    // ------------------------------------------------------------------------
    // FILTRADO: EN TODOS Y EN SALAS/EXTERIOR AGRUPADO POR TIPO + MODELO (+ MÓDULOS Y VARIACIONES)
    // (BOTÓN STOCK: PIEZAS CON MAYOR CANTIDAD FÍSICA SIN CONTAR LPPT)
    // ------------------------------------------------------------------------
    let lastRenderedCardKeys = [];

    function applyFilter(query, preserveCount, explicitMinCount) {
        const rawTrim = String(query || '').trim();
        const clearBtn = document.getElementById('invClearBtn');
        if (clearBtn) {
            clearBtn.style.display = '';
            clearBtn.classList.toggle('hidden', !rawTrim);
        }

        isMainCoverActive = (!rawTrim && activeCategory === 'ALL');
        activeFilteredGroupsByKey.clear();

        const exactSkuUpper = rawTrim ? rawTrim.toUpperCase() : '';
        const exactHitItem = exactSkuUpper ? bySkuMap.get(exactSkuUpper) : null;
        const isExactSkuHit = !!(exactHitItem && isQuotableItem(exactHitItem));
        const scoreByKey = new Map();
        const isMainCatSeparated = !!SUBCATEGORIES_BY_MAIN[activeCategory];

        if (activeCategory === 'ALL') {
            if (!rawTrim) {
                filteredGroups = getMainCoverGroups().slice();
            } else if (exactHitItem && !isQuotableItem(exactHitItem)) {
                filteredGroups = [];
            } else if (isExactSkuHit && singleBySkuMap.has(exactSkuUpper)) {
                filteredGroups = [singleBySkuMap.get(exactSkuUpper)];
            } else {
                const searchedGroups = searchGroupCollection(allGroups, rawTrim, scoreByKey);
                const nextFiltered = [];
                for (let i = 0; i < searchedGroups.length; i++) {
                    const grp = searchedGroups[i];
                    const matchedItems = filterItemsMatchingSearchIfSubset(grp.items, rawTrim);
                    const viewGrp = buildFilteredGroupView(grp, matchedItems);
                    if (viewGrp) {
                        activeFilteredGroupsByKey.set(viewGrp.key, viewGrp);
                        nextFiltered.push(viewGrp);
                    }
                }
                filteredGroups = nextFiltered;
            }
        } else if (isMainCatSeparated) {
            const subList = SUBCATEGORIES_BY_MAIN[activeCategory] || [];
            const isExplicitGroupedSub = activeSubCategory !== 'ALL' && GROUPED_SUBCATEGORIES.has(activeSubCategory);
            const hasAnyGroupedSub = activeSubCategory === 'ALL' && subList.some(sub => GROUPED_SUBCATEGORIES.has(sub));

            if (exactHitItem && !isQuotableItem(exactHitItem)) {
                filteredGroups = [];
            } else if (isExactSkuHit && singleBySkuMap.has(exactSkuUpper)) {
                filteredGroups = [singleBySkuMap.get(exactSkuUpper)];
            } else if (isExplicitGroupedSub || hasAnyGroupedSub) {
                const catPool = [];
                for (let i = 0; i < allGroups.length; i++) {
                    const grp = allGroups[i];
                    const matchedItems = grp.items.filter(it =>
                        itemMatchesActiveFilter(it, activeCategory, activeSubCategory) &&
                        (isExplicitGroupedSub || GROUPED_SUBCATEGORIES.has(it._cat))
                    );
                    if (matchedItems.length > 0) {
                        const viewGrp = buildFilteredGroupView(grp, matchedItems);
                        if (viewGrp) {
                            activeFilteredGroupsByKey.set(viewGrp.key, viewGrp);
                            catPool.push(viewGrp);
                        }
                    }
                }
                if (hasAnyGroupedSub) {
                    for (let i = 0; i < allSingleGroups.length; i++) {
                        const sg = allSingleGroups[i];
                        const it0 = sg.items[0];
                        if (itemMatchesActiveFilter(it0, activeCategory, activeSubCategory) && !GROUPED_SUBCATEGORIES.has(it0._cat)) {
                            catPool.push(sg);
                        }
                    }
                }
                if (!rawTrim) {
                    filteredGroups = catPool;
                } else {
                    const searchedPool = searchGroupCollection(catPool, rawTrim, scoreByKey);
                    const nextFiltered = [];
                    for (let i = 0; i < searchedPool.length; i++) {
                        const grp = searchedPool[i];
                        if (grp.items.length > 1) {
                            const matchedItems = filterItemsMatchingSearchIfSubset(grp.items, rawTrim);
                            const viewGrp = buildFilteredGroupView(grp, matchedItems);
                            if (viewGrp) {
                                activeFilteredGroupsByKey.set(viewGrp.key, viewGrp);
                                nextFiltered.push(viewGrp);
                            }
                        } else {
                            nextFiltered.push(grp);
                        }
                    }
                    filteredGroups = nextFiltered;
                }
            } else if (!rawTrim) {
                filteredGroups = allSingleGroups.filter(grp =>
                    itemMatchesActiveFilter(grp.items[0], activeCategory, activeSubCategory)
                );
            } else {
                const catSingles = allSingleGroups.filter(grp =>
                    itemMatchesActiveFilter(grp.items[0], activeCategory, activeSubCategory)
                );
                filteredGroups = searchGroupCollection(catSingles, rawTrim, scoreByKey);
            }
        } else {
            let baseGroups = [];
            if (!rawTrim) {
                baseGroups = allGroups;
            } else if (exactHitItem && !isQuotableItem(exactHitItem)) {
                baseGroups = [];
            } else if (isExactSkuHit && singleBySkuMap.has(exactSkuUpper)) {
                baseGroups = [singleBySkuMap.get(exactSkuUpper)];
            } else if (isExactSkuHit && groupsByKey.has(exactHitItem._groupKey)) {
                baseGroups = [groupsByKey.get(exactHitItem._groupKey)];
            } else {
                baseGroups = searchGroupCollection(allGroups, rawTrim, scoreByKey);
            }

            if (!isExactSkuHit) {
                const nextFiltered = [];
                if (activeCategory === 'STOCK') {
                    // Desglose por pieza individual con existencia física en Bodega/Piso (sin contar LPPT)
                    for (let i = 0; i < baseGroups.length; i++) {
                        const grp = baseGroups[i];
                        let matchedItems = grp.items.filter(it => itemMatchesActiveFilter(it, 'STOCK', activeSubCategory));
                        if (matchedItems.length > 0) {
                            matchedItems = filterItemsMatchingSearchIfSubset(matchedItems, rawTrim);
                            const parentScore = scoreByKey.get(grp.key);
                            for (let j = 0; j < matchedItems.length; j++) {
                                const pieceView = buildSinglePieceStockView(grp, matchedItems[j]);
                                if (pieceView) {
                                    if (parentScore) scoreByKey.set(pieceView.key, parentScore);
                                    nextFiltered.push(pieceView);
                                }
                            }
                        }
                    }
                } else {
                    for (let i = 0; i < baseGroups.length; i++) {
                        const grp = baseGroups[i];
                        let matchedItems = grp.items.filter(it => itemMatchesActiveFilter(it, activeCategory, activeSubCategory));
                        if (matchedItems.length > 0) {
                            if (rawTrim) {
                                matchedItems = filterItemsMatchingSearchIfSubset(matchedItems, rawTrim);
                            }
                            const viewGrp = buildFilteredGroupView(grp, matchedItems);
                            if (viewGrp) {
                                activeFilteredGroupsByKey.set(viewGrp.key, viewGrp);
                                nextFiltered.push(viewGrp);
                            }
                        }
                    }
                }
                filteredGroups = nextFiltered;
            } else {
                filteredGroups = baseGroups.slice();
            }
        }

        // En STOCK: mayor a menor cantidad física; en búsquedas: relevancia + orden comercial; en TODOS y CATEGORÍAS: foto arriba + jerarquía comercial + A-Z
        if (activeCategory === 'STOCK' && !isExactSkuHit) {
            if (rawTrim && scoreByKey.size > 0) {
                filteredGroups.sort((a, b) => {
                    const sa = scoreByKey.get(a.key) || { matched: 0, score: 0 };
                    const sb = scoreByKey.get(b.key) || { matched: 0, score: 0 };
                    const tierA = sa.score >= 12 ? 2 : 1;
                    const tierB = sb.score >= 12 ? 2 : 1;
                    return (sb.matched - sa.matched) ||
                        (tierB - tierA) ||
                        ((Number(b.totalStock) || 0) - (Number(a.totalStock) || 0)) ||
                        compareAlphaEs(a.displayTitle || a.title, b.displayTitle || b.title) ||
                        String(a.key || '').localeCompare(String(b.key || ''));
                });
            } else {
                filteredGroups.sort((a, b) =>
                    ((Number(b.totalStock) || 0) - (Number(a.totalStock) || 0)) ||
                    compareAlphaEs(a.displayTitle || a.title, b.displayTitle || b.title) ||
                    String(a.key || '').localeCompare(String(b.key || ''))
                );
            }
        } else if (rawTrim && !isExactSkuHit && scoreByKey.size > 0) {
            filteredGroups.sort((a, b) => {
                const sa = scoreByKey.get(a.key) || { matched: 0, score: 0 };
                const sb = scoreByKey.get(b.key) || { matched: 0, score: 0 };
                const tierA = sa.score >= 12 ? 2 : 1;
                const tierB = sb.score >= 12 ? 2 : 1;
                return (sb.matched - sa.matched) ||
                    (tierB - tierA) ||
                    compareCommercialGroupOrder(a, b);
            });
        } else {
            filteredGroups.sort(compareCommercialGroupOrder);
        }

        renderCategoryBar();

        const initialCap = getAdaptivePageSize();
        const minWanted = (typeof explicitMinCount === 'number' && explicitMinCount > 0)
            ? Math.max(initialCap, explicitMinCount)
            : initialCap;
        const targetInitial = preserveCount ? Math.max(minWanted, renderedCount) : minWanted;
        const container = document.getElementById('invListContainer');

        // Actualización in-place sin recargar fotos cuando la lista filtrada conserva los mismos SKUs
        if (preserveCount && container && filteredGroups.length > 0) {
            const nextCount = Math.min(filteredGroups.length, targetInitial);
            if (nextCount === lastRenderedCardKeys.length && nextCount > 0) {
                let sameKeys = true;
                for (let i = 0; i < nextCount; i++) {
                    if (String(filteredGroups[i].key || '') !== lastRenderedCardKeys[i]) {
                        sameKeys = false;
                        break;
                    }
                }
                if (sameKeys) {
                    const cards = container.children;
                    if (cards && cards.length === nextCount) {
                        for (let i = 0; i < nextCount; i++) {
                            const grp = filteredGroups[i];
                            const cardEl = cards[i];
                            const titleEl = cardEl.querySelector('[data-card-title]');
                            const subEl = cardEl.querySelector('[data-card-sub]');
                            const stockEl = cardEl.querySelector('[data-card-stock]');
                            if (grp.items.length > 1) {
                                const nextTitle = grp.displayTitle || grp.title || '';
                                if (titleEl && titleEl.textContent !== nextTitle) titleEl.textContent = nextTitle;
                                const nextSub = formatGroupBadgeLabel(grp);
                                if (subEl && subEl.textContent !== nextSub) subEl.textContent = nextSub;
                                if (stockEl) stockEl.remove();
                            } else {
                                const it = grp.items[0];
                                const nextTitle = grp.displayTitle || stripDimensionsFromProductText(it.n) || grp.title || it.s || '';
                                if (titleEl && titleEl.textContent !== nextTitle) titleEl.textContent = nextTitle;
                                const nextSub = it.s || '';
                                if (subEl && subEl.textContent !== nextSub) subEl.textContent = nextSub;
                                const ownPhysQty = getBodegaPisoStock(it);
                                if (activeCategory === 'STOCK' && ownPhysQty > 0) {
                                    const badgeTxt = ownPhysQty + ' pz';
                                    if (stockEl) {
                                        if (stockEl.textContent !== badgeTxt) stockEl.textContent = badgeTxt;
                                    } else {
                                        const metaEl = cardEl.querySelector('.inv-card-meta');
                                        if (metaEl) {
                                            const sp = document.createElement('span');
                                            sp.className = 'inv-card-stock';
                                            sp.setAttribute('data-card-stock', '1');
                                            sp.textContent = badgeTxt;
                                            metaEl.appendChild(sp);
                                        }
                                    }
                                } else if (stockEl) {
                                    stockEl.remove();
                                }
                            }
                        }
                        const moreWrap = document.getElementById('invLoadMoreWrap');
                        if (moreWrap) moreWrap.classList.toggle('hidden', renderedCount >= filteredGroups.length);
                        return;
                    }
                }
            }
        }

        renderedCount = 0;
        lastRenderedCardKeys = [];
        if (container) container.innerHTML = '';
        renderMoreItems(targetInitial);
    }

    let lastRenderedMainCat = null;
    let lastRenderedSubCat = null;
    let catStripListenersBound = false;

    function updateHorizontalStripFade(stripEl) {
        if (!stripEl || stripEl.style.display === 'none') return;
        const maxScroll = stripEl.scrollWidth - stripEl.clientWidth;
        if (maxScroll <= 2) {
            stripEl.classList.remove('can-scroll-left', 'can-scroll-right');
            return;
        }
        stripEl.classList.toggle('can-scroll-left', stripEl.scrollLeft > 3);
        stripEl.classList.toggle('can-scroll-right', stripEl.scrollLeft < maxScroll - 3);
    }

    function syncActivePillInStrip(stripEl, prevScrollLeft, shouldCenterActive, animate) {
        if (!stripEl || stripEl.style.display === 'none') return;
        stripEl.scrollLeft = prevScrollLeft || 0;
        if (shouldCenterActive && stripEl.scrollWidth > stripEl.clientWidth + 2) {
            const activeBtn = stripEl.querySelector('.active');
            if (activeBtn) {
                const targetLeft = Math.max(
                    0,
                    Math.min(
                        stripEl.scrollWidth - stripEl.clientWidth,
                        activeBtn.offsetLeft - Math.round((stripEl.clientWidth - activeBtn.offsetWidth) / 2)
                    )
                );
                if (animate && typeof stripEl.scrollTo === 'function') {
                    stripEl.scrollTo({ left: targetLeft, behavior: 'smooth' });
                } else {
                    stripEl.scrollLeft = targetLeft;
                }
            }
        }
        updateHorizontalStripFade(stripEl);
        if (animate) {
            setTimeout(() => updateHorizontalStripFade(stripEl), 280);
        }
    }

    function attachDesktopStripScroll(stripEl) {
        if (!stripEl) return;
        stripEl.addEventListener('scroll', () => updateHorizontalStripFade(stripEl), { passive: true });
        stripEl.addEventListener('wheel', (ev) => {
            const maxScroll = stripEl.scrollWidth - stripEl.clientWidth;
            if (maxScroll <= 2) return;
            if (Math.abs(ev.deltaY) > Math.abs(ev.deltaX) && ev.deltaY !== 0) {
                const prev = stripEl.scrollLeft;
                const next = Math.max(0, Math.min(maxScroll, prev + ev.deltaY));
                if (Math.abs(next - prev) >= 1) {
                    ev.preventDefault();
                    stripEl.scrollLeft = next;
                    updateHorizontalStripFade(stripEl);
                }
            }
        }, { passive: false });

        let isDown = false;
        let startX = 0;
        let startScroll = 0;
        let dragged = false;
        stripEl.addEventListener('mousedown', (ev) => {
            if (ev.button !== 0 || stripEl.scrollWidth <= stripEl.clientWidth + 2) return;
            isDown = true;
            dragged = false;
            startX = ev.clientX;
            startScroll = stripEl.scrollLeft;
        });
        window.addEventListener('mousemove', (ev) => {
            if (!isDown) return;
            const dx = ev.clientX - startX;
            if (Math.abs(dx) > 5) {
                dragged = true;
                stripEl.classList.add('is-dragging');
            }
            if (dragged) {
                stripEl.scrollLeft = startScroll - dx;
                updateHorizontalStripFade(stripEl);
            }
        });
        window.addEventListener('mouseup', () => {
            if (!isDown) return;
            isDown = false;
            stripEl.classList.remove('is-dragging');
            if (dragged) {
                setTimeout(() => { dragged = false; }, 0);
            }
        });
        stripEl.addEventListener('click', (ev) => {
            if (dragged) {
                ev.preventDefault();
                ev.stopPropagation();
                dragged = false;
            }
        }, true);
    }

    function bindCategoryStripScrollListeners(bar, subBar) {
        if (catStripListenersBound) return;
        catStripListenersBound = true;
        attachDesktopStripScroll(bar);
        attachDesktopStripScroll(subBar);
        window.addEventListener('resize', () => {
            updateHorizontalStripFade(document.getElementById('invCategoryBar'));
            updateHorizontalStripFade(document.getElementById('invSubCategoryBar'));
        }, { passive: true });
    }

    function renderCategoryBar() {
        const bar = document.getElementById('invCategoryBar');
        if (!bar) return;
        const subBar = document.getElementById('invSubCategoryBar');
        bindCategoryStripScrollListeners(bar, subBar);

        const prevMainScroll = bar.scrollLeft || 0;
        const prevSubScroll = subBar ? (subBar.scrollLeft || 0) : 0;
        const mainCatChanged = activeCategory !== lastRenderedMainCat;
        const animateMain = mainCatChanged && lastRenderedMainCat !== null;
        const subCatKey = activeCategory + '::' + activeSubCategory;
        const subCatChanged = subCatKey !== lastRenderedSubCat;
        const animateSub = subCatChanged && !mainCatChanged && lastRenderedSubCat !== null;
        lastRenderedMainCat = activeCategory;
        lastRenderedSubCat = subCatKey;

        const mainCounts = new Map();
        const subCounts = new Map();
        const availCounts = new Map();
        const lpptRangeCounts = new Map();
        const stockMainCounts = new Map();
        let stockPieceCount = 0;
        let lpptGroupCount = 0;

        for (let i = 0; i < allGroups.length; i++) {
            const g = allGroups[i];
            if (g.avails) {
                g.avails.forEach(a => {
                    if (a && a !== 'STOCK' && a !== 'LPPT') availCounts.set(a, (availCounts.get(a) || 0) + 1);
                });
            }
            if ((Number(g.lpptStock) || 0) >= 1) {
                lpptGroupCount++;
            }
            if (Array.isArray(g.items)) {
                const groupedCatsInGroup = new Set();
                for (let j = 0; j < g.items.length; j++) {
                    const it = g.items[j];
                    const isGroupedSub = !!(it._cat && GROUPED_SUBCATEGORIES.has(it._cat));
                    if (isGroupedSub) {
                        groupedCatsInGroup.add(it._cat);
                    } else {
                        if (it._main) {
                            mainCounts.set(it._main, (mainCounts.get(it._main) || 0) + 1);
                        }
                        if (SUBCATEGORIES_BY_MAIN[activeCategory] && it._cat && MAIN_OF_SUB[it._cat] === activeCategory) {
                            subCounts.set(it._cat, (subCounts.get(it._cat) || 0) + 1);
                        }
                    }
                    if (getBodegaPisoStock(it) >= 1) {
                        stockPieceCount++;
                        if (it._main) {
                            stockMainCounts.set(it._main, (stockMainCounts.get(it._main) || 0) + 1);
                        }
                    }
                }
                if (groupedCatsInGroup.size > 0) {
                    const countedMains = new Set();
                    groupedCatsInGroup.forEach(catName => {
                        const mCat = MAIN_OF_SUB[catName];
                        if (mCat && !countedMains.has(mCat)) {
                            countedMains.add(mCat);
                            mainCounts.set(mCat, (mainCounts.get(mCat) || 0) + 1);
                        }
                        if (SUBCATEGORIES_BY_MAIN[activeCategory] && mCat === activeCategory) {
                            subCounts.set(catName, (subCounts.get(catName) || 0) + 1);
                        }
                    });
                }
            }
            if (activeCategory === 'LPPT' && g.lpptBuckets) {
                g.lpptBuckets.forEach(b => {
                    if (b) lpptRangeCounts.set(b, (lpptRangeCounts.get(b) || 0) + 1);
                });
            }
        }
        availCounts.set('STOCK', stockPieceCount);
        availCounts.set('LPPT', lpptGroupCount);

        const pill = (cls, attr, val, label, isActive) =>
            '<button type="button" class="' + cls + (isActive ? ' active' : '') + '" ' + attr + '="' + escapeHtml(val) + '">' + escapeHtml(label) + '</button>';

        const pills = [
            pill('inv-cat-pill', 'data-cat', 'ALL', 'TODOS (' + allGroups.length + ')', activeCategory === 'ALL')
        ];
        MAIN_CATEGORY_ORDER.forEach(c => {
            const cnt = mainCounts.get(c) || 0;
            pills.push(pill('inv-cat-pill', 'data-cat', c, c + ' (' + cnt + ')', activeCategory === c));
        });
        AVAILABILITY_FILTERS.forEach(af => {
            const cnt = availCounts.get(af.key) || 0;
            pills.push(pill('inv-cat-pill stock-pill', 'data-cat', af.key, af.label + ' (' + cnt + ')', activeCategory === af.key));
        });
        bar.innerHTML = pills.join('');
        bar.querySelectorAll('.inv-cat-pill[data-cat]').forEach(btn => {
            btn.onclick = function () { setInvCategory(btn.getAttribute('data-cat')); };
        });
        syncActivePillInStrip(bar, prevMainScroll, mainCatChanged, animateMain);

        if (!subBar) return;

        if (SUBCATEGORIES_BY_MAIN[activeCategory]) {
            const subs = SUBCATEGORIES_BY_MAIN[activeCategory].slice();
            if (activeCategory === 'ESPEJOS Y ACCESORIOS' && (subCounts.get('OTROS') || 0) > 0 && subs.indexOf('OTROS') === -1) {
                subs.push('OTROS');
            }
            const subPills = [
                pill('inv-cat-pill inv-sub-pill', 'data-sub', 'ALL', 'TODO ' + activeCategory + ' (' + (mainCounts.get(activeCategory) || 0) + ')', activeSubCategory === 'ALL')
            ];
            subs.forEach(c => {
                subPills.push(pill('inv-cat-pill inv-sub-pill', 'data-sub', c, c + ' (' + (subCounts.get(c) || 0) + ')', activeSubCategory === c));
            });
            subBar.innerHTML = subPills.join('');
            subBar.style.display = '';
            subBar.querySelectorAll('.inv-sub-pill[data-sub]').forEach(btn => {
                btn.onclick = function () { setInvSubCategory(btn.getAttribute('data-sub')); };
            });
            syncActivePillInStrip(subBar, mainCatChanged ? 0 : prevSubScroll, subCatChanged, animateSub);
            return;
        }

        if (activeCategory === 'STOCK') {
            const subPills = [
                pill('inv-cat-pill inv-sub-pill', 'data-sub', 'ALL', 'TODO STOCK (' + stockPieceCount + ')', activeSubCategory === 'ALL')
            ];
            MAIN_CATEGORY_ORDER.forEach(c => {
                const cnt = stockMainCounts.get(c) || 0;
                subPills.push(pill('inv-cat-pill inv-sub-pill', 'data-sub', c, c + ' (' + cnt + ')', activeSubCategory === c));
            });
            subBar.innerHTML = subPills.join('');
            subBar.style.display = '';
            subBar.querySelectorAll('.inv-sub-pill[data-sub]').forEach(btn => {
                btn.onclick = function () { setInvSubCategory(btn.getAttribute('data-sub')); };
            });
            syncActivePillInStrip(subBar, mainCatChanged ? 0 : prevSubScroll, subCatChanged, animateSub);
            return;
        }

        if (activeCategory === 'LPPT') {
            const lpptTotal = availCounts.get('LPPT') || 0;
            const subPills = [
                pill('inv-cat-pill inv-sub-pill', 'data-sub', 'ALL', 'TODO LPPT (' + lpptTotal + ')', activeSubCategory === 'ALL')
            ];
            LPPT_DAY_RANGES.forEach(r => {
                const cnt = lpptRangeCounts.get(r.key) || 0;
                subPills.push(pill('inv-cat-pill inv-sub-pill', 'data-sub', r.key, r.label + ' (' + cnt + ')', activeSubCategory === r.key));
            });
            subBar.innerHTML = subPills.join('');
            subBar.style.display = '';
            subBar.querySelectorAll('.inv-sub-pill[data-sub]').forEach(btn => {
                btn.onclick = function () { setInvSubCategory(btn.getAttribute('data-sub')); };
            });
            syncActivePillInStrip(subBar, mainCatChanged ? 0 : prevSubScroll, subCatChanged, animateSub);
            return;
        }

        subBar.innerHTML = '';
        subBar.style.display = 'none';
        subBar.classList.remove('can-scroll-left', 'can-scroll-right');
    }

    window.setInvCategory = function (cat) {
        const next = cat || 'ALL';
        activeSubCategory = 'ALL';
        activeCategory = next;
        const inp = document.getElementById('invSearchInput');
        applyFilter(inp ? inp.value : '');
        if (activeCategory !== 'ALL') notifyInvBackStatePush('inv_category');
    };

    window.setInvSubCategory = function (sub) {
        activeSubCategory = sub || 'ALL';
        const inp = document.getElementById('invSearchInput');
        applyFilter(inp ? inp.value : '');
        if (activeSubCategory !== 'ALL') notifyInvBackStatePush('inv_subcategory');
    };

    function buildCardCartControlHtml(skuKey) {
        if (typeof isGuestSession === 'function' && isGuestSession()) {
            return '';
        }
        const key = String(skuKey || '').trim().toUpperCase();
        const inCartQty = cart[key] ? (Number(cart[key].qty) || 0) : 0;
        if (inCartQty > 0) {
            return '<div class="cart-ctrl-wrap" data-sku-ctrl="' + escapeHtml(key) + '">' +
                '<div class="cart-qty-pill">' +
                    '<button type="button" class="cart-qty-step minus" data-cart-act="sub" title="Quitar 1 de Cotización">−</button>' +
                    '<span class="cart-qty-num">' + inCartQty + '</span>' +
                    '<button type="button" class="cart-qty-step plus" data-cart-act="add" title="Agregar 1 más a Cotización">+</button>' +
                '</div>' +
            '</div>';
        }
        return '<div class="cart-ctrl-wrap" data-sku-ctrl="' + escapeHtml(key) + '">' +
            '<button type="button" title="Agregar a Cotización" data-cart-act="add" class="cart-plus-btn">+</button>' +
        '</div>';
    }

    function bindCardCartControlEvents(ctrlWrapEl, skuRaw) {
        if (!ctrlWrapEl) return;
        ctrlWrapEl.onclick = function (ev) {
            ev.stopPropagation();
            if (typeof isGuestSession === 'function' && isGuestSession()) return;
            const actBtn = ev.target && ev.target.closest ? ev.target.closest('[data-cart-act]') : null;
            if (!actBtn) return;
            const act = actBtn.getAttribute('data-cart-act');
            addToCart(skuRaw, act === 'sub' ? -1 : 1);
        };
    }

    window.renderMoreItems = function (batchSize) {
        const container = document.getElementById('invListContainer');
        const moreWrap = document.getElementById('invLoadMoreWrap');
        if (!container) return;

        const maxAllowed = filteredGroups.length;

        if (maxAllowed === 0) {
            lastRenderedCardKeys = [];
            if (isMainCoverActive) {
                container.innerHTML =
                    '<div class="rounded-xl border px-4 py-6 text-center text-[11px] font-semibold" ' +
                    'style="grid-column: 1 / -1; border-color:#E6E1D8; color:#1A1816; background:#FFFFFF;">' +
                    'Sin productos disponibles.' +
                    '</div>';
            } else {
                const inp = document.getElementById('invSearchInput');
                const curQ = cleanStr(inp && inp.value);
                const filterLbl = formatActiveFilterLabel();
                container.innerHTML =
                    '<div class="rounded-xl border px-4 py-6 text-center text-[11px] font-semibold space-y-1.5" ' +
                    'style="grid-column: 1 / -1; border-color:#E6E1D8; color:#1A1816; background:#FFFFFF;">' +
                    '<div>Sin resultados' +
                        (curQ ? (' para <strong>“' + escapeHtml(curQ) + '”</strong>') : '') +
                        (activeCategory !== 'ALL' ? (' en <strong>' + escapeHtml(filterLbl) + '</strong>') : '') +
                    '.</div>' +
                    '</div>';
            }
            if (moreWrap) moreWrap.classList.add('hidden');
            return;
        }

        const step = (typeof batchSize === 'number' && batchSize > 0) ? batchSize : getAdaptivePageSize();
        const nextEnd = Math.min(renderedCount + step, maxAllowed);
        const eagerCount = (typeof window !== 'undefined' && window.innerWidth >= 768) ? 6 : 4;
        const frag = document.createDocumentFragment();

        for (let i = renderedCount; i < nextEnd; i++) {
            const grp = filteredGroups[i];
            const row = document.createElement('div');
            row.className = 'inv-row';
            row.setAttribute('data-card-key', String(grp.key || ''));
            lastRenderedCardKeys.push(String(grp.key || ''));

            if (grp.items.length > 1) {
                const visualCoverUrl = getGroupVisualCoverPhotoUrl(grp.key);
                row.onclick = function () {
                    openGroupModal(grp.key);
                };
                row.innerHTML =
                    '<div class="inv-card-top-right">' +
                        '<span class="inv-card-variant-badge" data-card-sub="1">' + escapeHtml(formatGroupBadgeLabel(grp)) + '</span>' +
                    '</div>' +
                    buildThumbHtml(visualCoverUrl ? { f: visualCoverUrl } : firstPhotoItem(grp.items), { card: true, eager: i < eagerCount, boxRatio: 1 }) +
                    '<div class="inv-card-body">' +
                        '<div class="inv-card-title" data-card-title="1">' + escapeHtml(grp.displayTitle || grp.title) + '</div>' +
                    '</div>';
            } else {
                const it = grp.items[0];
                const skuKey = String(it.s || '').toUpperCase();
                row.setAttribute('data-card-sku', skuKey);
                row.setAttribute('data-sku', String(it.s || ''));
                const ownPhysQty = getBodegaPisoStock(it);
                const stockBadgeHtml = (activeCategory === 'STOCK' && ownPhysQty > 0)
                    ? '<span class="inv-card-stock" data-card-stock="1">' + ownPhysQty + ' pz</span>'
                    : '';
                row.onclick = function () {
                    openProductDetail(it.s, false);
                };
                row.innerHTML =
                    '<div class="inv-card-top-right">' + buildCardCartControlHtml(skuKey) + '</div>' +
                    buildThumbHtml(it, { card: true, eager: i < eagerCount, boxRatio: 1 }) +
                    '<div class="inv-card-body">' +
                        '<div class="inv-card-title" data-card-title="1">' + escapeHtml(grp.displayTitle || stripDimensionsFromProductText(it.n) || grp.title || it.s) + '</div>' +
                        '<div class="inv-card-meta"><span data-card-sub="1">' + escapeHtml(it.s) + '</span>' + stockBadgeHtml + '</div>' +
                    '</div>';

                const ctrlWrap = row.querySelector('[data-sku-ctrl]');
                bindCardCartControlEvents(ctrlWrap, it.s);
            }

            frag.appendChild(row);
        }

        container.appendChild(frag);
        renderedCount = nextEnd;

        if (window.CreataGuard && typeof window.CreataGuard.protectImages === 'function') {
            window.CreataGuard.protectImages(container);
        }

        if (moreWrap) {
            if (renderedCount < maxAllowed) moreWrap.classList.remove('hidden');
            else moreWrap.classList.add('hidden');
        }
    };

    let searchDebounceTimer = null;
    window.clearInvSearch = function () {
        if (searchDebounceTimer) {
            clearTimeout(searchDebounceTimer);
            searchDebounceTimer = null;
        }
        const inp = document.getElementById('invSearchInput');
        if (inp) {
            inp.value = '';
        }
        _invPrevSearchNonEmpty = false;
        applyFilter('');
        scheduleSaveInvWorkspaceCheckpoint();
    };

    // ------------------------------------------------------------------------
    // ESCÁNER DE CÁMARA Y LECTURA SILENCIOSA BLUETOOTH HID (P2300L · ANDROID / APPLE iOS / PC)
    // ------------------------------------------------------------------------
    const SCAN_LIB_URLS = [
        'https://cdn.jsdelivr.net/npm/html5-qrcode@2.3.8/html5-qrcode.min.js',
        'https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js'
    ];
    let scanLibPromise = null;
    let scanInstance = null;
    let scanHandled = false;
    let btLastProcessedCode = '';
    let btLastProcessedTs = 0;
    let btLastResultObj = null;

    function loadScanLib() {
        if (window.Html5Qrcode) return Promise.resolve();
        if (scanLibPromise) return scanLibPromise;
        scanLibPromise = new Promise((resolve, reject) => {
            let idx = 0;
            const tryNext = () => {
                if (idx >= SCAN_LIB_URLS.length) {
                    scanLibPromise = null;
                    reject(new Error('No se pudo cargar el lector de códigos.'));
                    return;
                }
                const s = document.createElement('script');
                s.src = SCAN_LIB_URLS[idx++];
                s.async = true;
                s.onload = () => (window.Html5Qrcode ? resolve() : tryNext());
                s.onerror = tryNext;
                document.head.appendChild(s);
            };
            tryNext();
        });
        return scanLibPromise;
    }

    function setScanStatus(msg, isError) {
        const el = document.getElementById('scanStatus');
        if (!el) return;
        el.textContent = msg;
        el.style.color = isError ? '#991B1B' : '#252C32';
    }

    function normalizeScannedBarcodeText(rawText) {
        let s = String(rawText == null ? '' : rawText);
        // Eliminar caracteres de control (NUL, GS, RS, EOT, etc.) conservando espacios
        s = s.replace(/[\r\n\t]+/g, ' ').replace(/[\x00-\x1f\x7f]+/g, '').trim();
        // Eliminar prefijos AIM estándar que algunos lectores 2D envían (]C1, ]Q1, ]E0, ]d2...)
        s = s.replace(/^\][A-Za-z][0-9]/, '').trim();
        s = s.replace(/\s+/g, ' ');
        return s;
    }

    function repairUsToEsScannerLayout(text) {
        const out = [];
        const base = String(text || '').trim();
        if (!base) return out;
        out.push(base);
        // Cuando un P2300L en layout US envía hacia Android/iPhone en Español (MX/ES):
        // '-' llega como "'", '_' como '?', ':' como 'Ñ', '/' como '-', '=' como '¡', '&' como '/'
        const urlRepaired = base
            .replace(/^https?[Ññ]--/i, m => m.replace(/[Ññ]/g, ':').replace(/--/g, '//'))
            .replace(/['’]/g, '-')
            .replace(/[¡]/g, '=')
            .replace(/\?/g, '_');
        if (urlRepaired !== base) out.push(urlRepaired);
        const hyphenOnly = base.replace(/['’]/g, '-');
        if (hyphenOnly !== base && out.indexOf(hyphenOnly) === -1) out.push(hyphenOnly);
        const ampRepaired = base.replace(/\//g, '&');
        if (ampRepaired !== base && out.indexOf(ampRepaired) === -1) out.push(ampRepaired);
        const hyphenAndAmp = hyphenOnly.replace(/\//g, '&');
        if (hyphenAndAmp !== base && out.indexOf(hyphenAndAmp) === -1) out.push(hyphenAndAmp);
        return out;
    }

    function extractBarcodeCandidates(rawText) {
        const cleaned = normalizeScannedBarcodeText(rawText);
        if (!cleaned) return [];
        const seen = new Set();
        const list = [];
        function addCand(v) {
            const c = String(v || '').trim().toUpperCase();
            if (!c || seen.has(c)) return;
            seen.add(c);
            list.push(c);
        }

        const variants = repairUsToEsScannerLayout(cleaned);
        for (let i = 0; i < variants.length; i++) {
            const v = variants[i];
            addCand(v);

            // Prefijos comunes de etiquetas (SKU: XXX, COD: XXX, MODELO: XXX)
            const prefMatch = v.match(/^(?:SKU|COD|C[OÓ]DIGO|CODE|REF|ITEM|ID|MODELO)\s*[:=#\-]\s*(.+)$/i);
            if (prefMatch && prefMatch[1]) {
                addCand(prefMatch[1]);
            }

            // QR con URL (ej. https://.../?sku=API1P o /producto/API1P)
            if (/^https?:\/\//i.test(v)) {
                try {
                    const u = new URL(v);
                    ['sku', 's', 'codigo', 'code', 'id', 'item', 'p', 'q'].forEach(param => {
                        const pv = u.searchParams.get(param);
                        if (pv) addCand(pv);
                    });
                    const segs = u.pathname.split('/').map(seg => decodeURIComponent(seg || '').trim()).filter(Boolean);
                    for (let k = segs.length - 1; k >= 0; k--) {
                        if (segs[k].length >= 4 && !/\.html?$/i.test(segs[k])) addCand(segs[k]);
                    }
                } catch (e) {}
            }

            // Etiquetas con varios campos separados por espacio, |, ; o ,
            const parts = v.split(/[\s|;,]+/).map(p => p.trim()).filter(Boolean);
            for (let j = 0; j < parts.length; j++) {
                const tok = parts[j].replace(/^[^A-Za-z0-9]+|[^A-Za-z0-9&]+$/g, '');
                if (tok.length >= 4) addCand(tok);
            }
        }
        return list;
    }

    function resolveScannedBarcode(rawText) {
        const rawCode = normalizeScannedBarcodeText(rawText);
        if (!rawCode) return null;
        const candidates = extractBarcodeCandidates(rawCode);

        // 1. Coincidencia exacta en bySkuMap
        for (let i = 0; i < candidates.length; i++) {
            const hit = bySkuMap.get(candidates[i]);
            if (hit) {
                return {
                    status: isQuotableItem(hit) ? 'quotable' : 'out_of_stock',
                    item: hit,
                    rawCode: rawCode,
                    matchedCode: hit.s
                };
            }
        }

        // 2. Coincidencia normalizada alfanumérica en bySkuNormMap
        for (let i = 0; i < candidates.length; i++) {
            const norm = candidates[i].replace(/[^A-Z0-9]+/g, '');
            if (norm.length >= 4) {
                const hit = bySkuNormMap.get(norm);
                if (hit) {
                    return {
                        status: isQuotableItem(hit) ? 'quotable' : 'out_of_stock',
                        item: hit,
                        rawCode: rawCode,
                        matchedCode: hit.s
                    };
                }
            }
        }

        // 3. Búsqueda inteligente en el catálogo disponible (sin mutar la vista principal)
        try {
            if (typeof searchGroupCollection === 'function' && Array.isArray(allGroups) && allGroups.length > 0) {
                const scoreMap = new Map();
                const hits = searchGroupCollection(allGroups, rawCode, scoreMap);
                if (hits.length === 1) {
                    const g = hits[0];
                    if (g.items && g.items.length === 1 && isQuotableItem(g.items[0])) {
                        return {
                            status: 'quotable',
                            item: g.items[0],
                            rawCode: rawCode,
                            matchedCode: g.items[0].s
                        };
                    }
                    return {
                        status: 'search_group',
                        group: g,
                        rawCode: rawCode,
                        matchedCode: rawCode
                    };
                }
                if (hits.length > 1) {
                    return {
                        status: 'search_multi',
                        count: hits.length,
                        rawCode: rawCode,
                        matchedCode: rawCode
                    };
                }
            }
        } catch (e) {}

        return {
            status: 'raw_only',
            rawCode: rawCode,
            matchedCode: rawCode
        };
    }

    function playBtScanFeedback() {
        try {
            if (navigator && typeof navigator.vibrate === 'function') {
                navigator.vibrate(65);
            }
        } catch (e) {}
    }

    function processScannedBarcode(rawText, opts) {
        const o = opts || {};
        const cleaned = normalizeScannedBarcodeText(rawText);
        if (!cleaned) return null;

        // Evitar doble disparo si el lector envía keydown + input casi simultáneos
        const nowTs = Date.now();
        if (!o.force && cleaned.toUpperCase() === btLastProcessedCode && (nowTs - btLastProcessedTs) < 420) {
            return btLastResultObj;
        }
        btLastProcessedCode = cleaned.toUpperCase();
        btLastProcessedTs = nowTs;

        const res = resolveScannedBarcode(cleaned);
        if (!res) return null;

        res.source = o.source || 'Bluetooth HID (P2300L)';
        btLastResultObj = res;
        playBtScanFeedback();

        if (isModalOpenById('scanModal')) {
            closeBarcodeScanner();
        }
        if (isModalOpenById('priceCalculatorModal') && typeof handleScannedBarcodeForPriceCalculator === 'function') {
            return handleScannedBarcodeForPriceCalculator(res, cleaned);
        }
        if (isModalOpenById('cartModal') && (res.status === 'quotable' || res.status === 'search_group' || res.status === 'search_multi')) {
            closeCartModal();
        }

        const inp = document.getElementById('invSearchInput');
        if (res.status === 'quotable' && res.item) {
            if (inp) inp.value = res.item.s;
            applyFilter(res.item.s);
            openProductDetail(res.item.s, false);
            showToast('✓ Escaneado: ' + res.item.s);
        } else if (res.status === 'search_group' && res.group) {
            if (inp) inp.value = res.rawCode;
            applyFilter(res.rawCode);
            openGroupModal(res.group.key);
            showToast('✓ Escaneado: ' + res.rawCode);
        } else if (res.status === 'search_multi') {
            if (inp) inp.value = res.rawCode;
            applyFilter(res.rawCode);
            showToast('Código leído: ' + res.rawCode + ' · ' + res.count + ' coincidencias');
        } else if (res.status === 'out_of_stock') {
            // Respetar filtro de disponibilidad: no exponer en catálogo cotizable ni abrir ficha
            showToast('⚠ Código leído (' + res.matchedCode + '): sin stock en Bodega/Piso ni LPPT');
        } else {
            if (inp) inp.value = res.rawCode;
            applyFilter(res.rawCode);
            showToast('Código leído: ' + res.rawCode);
        }
        return res;
    }

    function handleScannedCode(rawText) {
        if (scanHandled) return;
        const code = normalizeScannedBarcodeText(rawText);
        if (!code) return;
        scanHandled = true;
        processScannedBarcode(code, { source: 'Cámara' });
    }

    function isScanModalOpen() {
        const modal = document.getElementById('scanModal');
        return Boolean(modal && modal.classList.contains('open'));
    }

    async function startLiveBarcodeCamera() {
        if (!isScanModalOpen()) return;
        if (!window.isSecureContext || !navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
            setScanStatus('Este navegador no permite video en vivo. Usa el botón "Tomar foto del código".', true);
            loadScanLib().catch(() => {});
            return;
        }
        setScanStatus('Iniciando cámara...', false);
        try {
            await loadScanLib();
            if (!isScanModalOpen()) return;
            if (scanInstance) {
                const prevInst = scanInstance;
                scanInstance = null;
                try {
                    if (prevInst.isScanning) await prevInst.stop();
                    prevInst.clear();
                } catch (ePrev) {}
            }
            if (!isScanModalOpen()) return;
            const reader = document.getElementById('scanReader');
            if (reader) reader.innerHTML = '';
            const inst = new window.Html5Qrcode('scanReader', {
                verbose: false,
                experimentalFeatures: { useBarCodeDetectorIfSupported: true }
            });
            scanInstance = inst;
            if (!isScanModalOpen()) {
                scanInstance = null;
                try { inst.clear(); } catch (eClr) {}
                return;
            }
            const scanConfig = {
                fps: 12,
                qrbox: function (w, h) {
                    const bw = Math.floor(Math.min(w * 0.85, 360));
                    const bh = Math.floor(Math.min(h * 0.5, 180));
                    return { width: Math.max(bw, 120), height: Math.max(bh, 80) };
                }
            };
            const onDecodeSuccess = function (decodedText) { handleScannedCode(decodedText); };
            const onDecodeFailure = function () {};
            let startedCamera = false;
            try {
                await inst.start({ facingMode: 'environment' }, scanConfig, onDecodeSuccess, onDecodeFailure);
                startedCamera = true;
            } catch (envErr) {
                // Fallback automático para computadora (PC / Mac / Laptop / Webcam USB) sin cámara trasera
                if (!isScanModalOpen() || scanInstance !== inst) return;
                let cameras = [];
                try {
                    if (typeof window.Html5Qrcode.getCameras === 'function') {
                        cameras = await window.Html5Qrcode.getCameras();
                    }
                } catch (eCamList) {}
                if (!isScanModalOpen() || scanInstance !== inst) return;
                if (Array.isArray(cameras) && cameras.length > 0) {
                    const preferred = cameras.find(c => /back|rear|trasera|environment/i.test(String((c && c.label) || ''))) || cameras[0];
                    await inst.start(preferred.id, scanConfig, onDecodeSuccess, onDecodeFailure);
                    startedCamera = true;
                } else {
                    await inst.start({ facingMode: 'user' }, scanConfig, onDecodeSuccess, onDecodeFailure);
                    startedCamera = true;
                }
            }
            if (!startedCamera) {
                throw new Error('No se encontró cámara disponible.');
            }
            // Si el usuario cerró el modal mientras la cámara arrancaba, apagarla
            if (scanInstance !== inst || !isScanModalOpen()) {
                try { await inst.stop(); inst.clear(); } catch (e) {}
                return;
            }
            setScanStatus('Apunta la cámara al código de barras o QR del producto.', false);
        } catch (err) {
            console.error('[Escáner]', err);
            setScanStatus('No fue posible abrir la cámara en vivo. Da permiso de cámara, usa "Tomar foto del código" o escanea con lector USB/Bluetooth.', true);
        }
    }

    window.openBarcodeScanner = async function () {
        const modal = document.getElementById('scanModal');
        if (!modal) return;
        scanHandled = false;
        modal.classList.add('open');
        notifyInvBackStatePush('scan_modal');
        await startLiveBarcodeCamera();
    };

    // Respaldo: tomar una foto del código con la cámara del teléfono y leerla
    window.scanBarcodeFromPhoto = async function (inputEl) {
        const file = inputEl && inputEl.files && inputEl.files[0];
        if (!file) return;
        let hadLiveCamera = false;
        setScanStatus('Leyendo código de la foto...', false);
        try {
            await loadScanLib();
            if (scanInstance && scanInstance.isScanning) {
                hadLiveCamera = true;
                try { await scanInstance.stop(); } catch (e) {}
            }
            const tmpId = 'scanFileTmp';
            let tmp = document.getElementById(tmpId);
            if (!tmp) {
                tmp = document.createElement('div');
                tmp.id = tmpId;
                tmp.style.display = 'none';
                document.body.appendChild(tmp);
            }
            const fileReader = new window.Html5Qrcode(tmpId, { verbose: false });
            const text = await fileReader.scanFile(file, false);
            try { fileReader.clear(); } catch (e) {}
            handleScannedCode(text);
        } catch (err) {
            console.error('[Escáner foto]', err);
            if (isScanModalOpen() && hadLiveCamera) {
                await startLiveBarcodeCamera();
            }
            setScanStatus('No se encontró un código en la foto. Acércate más y que el código se vea nítido.', true);
        } finally {
            inputEl.value = '';
        }
    };

    window.closeBarcodeScanner = function () {
        const modal = document.getElementById('scanModal');
        if (modal) modal.classList.remove('open');
        const inst = scanInstance;
        scanInstance = null;
        if (inst) {
            try {
                const p = inst.isScanning ? inst.stop() : Promise.resolve();
                Promise.resolve(p).then(() => { try { inst.clear(); } catch (e) {} }).catch(() => {});
            } catch (e) {}
        }
    };

    window.__creataBtScanner = {
        normalizeScannedBarcodeText: normalizeScannedBarcodeText,
        repairUsToEsScannerLayout: repairUsToEsScannerLayout,
        extractBarcodeCandidates: extractBarcodeCandidates,
        resolveScannedBarcode: resolveScannedBarcode,
        processScannedBarcode: processScannedBarcode,
        getLastResult: function () { return btLastResultObj; }
    };

    // ------------------------------------------------------------------------
    // PASO 1: MODAL DE VARIANTES DISPONIBLES DEL MODELO (ej. SILLON APIENZO)
    // ------------------------------------------------------------------------
    function renderGroupVariantsStep(grp, forcedFabricKey, forcedSizeKey) {
        currentGroup = grp;
        currentDetailItem = null;
        if (forcedFabricKey !== undefined) {
            currentGroupFabricKey = String(forcedFabricKey || '').trim();
        }
        if (forcedSizeKey !== undefined) {
            currentGroupBedSizeKey = String(forcedSizeKey || '').trim();
        }

        const crumbEl = document.getElementById('detGroupCrumb');
        const skuEl = document.getElementById('detSku');
        const nameEl = document.getElementById('detName');
        const priceWrapEl = document.getElementById('detPriceWrap');
        const priceEl = document.getElementById('detPrice');
        const actionsRow = document.getElementById('detHeaderActionsRow');
        const addPillWrap = document.getElementById('detAddPillWrap');
        const addBtn = document.getElementById('detAddCartBtn');
        const subBtn = document.getElementById('detSubCartBtn');
        const remAllBtn = document.getElementById('detRemoveAllCartBtn');
        const oosBtn = document.getElementById('detOutOfStockRequestBtn');
        const varStep = document.getElementById('detVariantsStep');
        const singleStep = document.getElementById('detSingleStep');
        const varList = document.getElementById('detVariantsList');
        const guestModeGrp = typeof isGuestSession === 'function' && isGuestSession();

        if (crumbEl) {
            crumbEl.textContent = '';
            crumbEl.classList.add('hidden');
        }
        if (skuEl) {
            skuEl.textContent = '';
            skuEl.classList.add('hidden');
        }
        if (nameEl) {
            nameEl.textContent = grp.displayTitle || grp.title;
        }
        if (priceEl) priceEl.textContent = '';
        if (priceWrapEl) priceWrapEl.classList.add('hidden');
        if (actionsRow) actionsRow.classList.add('hidden');
        if (addPillWrap) addPillWrap.classList.add('hidden');
        if (addBtn) addBtn.classList.add('hidden');
        if (subBtn) subBtn.classList.add('hidden');
        if (remAllBtn) remAllBtn.classList.add('hidden');
        if (oosBtn) oosBtn.classList.add('hidden');

        function normWordForVariant(w) {
            return String(w || '')
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .toUpperCase()
                .replace(/[^A-Z0-9]/g, '');
        }

        function buildVariantLabel(it, groupObj, extraSkipTokens) {
            const rawName = stripDimensionsFromProductText(it.n).toUpperCase();
            const vr = cleanStr(it.vr).toUpperCase();
            const titleWords = new Set(
                String(groupObj && groupObj.title ? groupObj.title : '')
                    .toUpperCase()
                    .split(/\s+/)
                    .map(normWordForVariant)
                    .filter(Boolean)
            );
            if (Array.isArray(extraSkipTokens)) {
                for (let s = 0; s < extraSkipTokens.length; s++) {
                    const st = normWordForVariant(extraSkipTokens[s]);
                    if (st) titleWords.add(st);
                }
            }

            const tokens = rawName.split(/\s+/).filter(Boolean);
            const rem = [];
            for (let i = 0; i < tokens.length; i++) {
                const nw = normWordForVariant(tokens[i]);
                if (!nw) continue;
                if ((nw === 'DE' || nw === 'DEL' || nw === 'CON' || nw === 'SIN' || nw === 'PARA') && i + 1 < tokens.length && titleWords.has(normWordForVariant(tokens[i + 1]))) {
                    continue;
                }
                if (titleWords.has(nw)) continue;
                rem.push(tokens[i]);
            }
            while (rem.length > 0 && /^(DE|DEL|LA|EL|LOS|LAS|CON|SIN|PARA|EN|Y|-|\/|·)$/.test(normWordForVariant(rem[0]))) rem.shift();
            while (rem.length > 0 && /^(DE|DEL|LA|EL|LOS|LAS|CON|SIN|PARA|EN|Y|-|\/|·)$/.test(normWordForVariant(rem[rem.length - 1]))) rem.pop();

            let label = rem.join(' ').replace(/\s+/g, ' ').trim();
            if (!label || normWordForVariant(label) === normWordForVariant(it.s)) {
                const fallbackPieces = [
                    cleanStr(it.tl).toUpperCase(),
                    cleanStr(it.ct).toUpperCase()
                ].filter(Boolean);
                const fabricFallback = fallbackPieces.join(' ').trim();
                label = vr || fabricFallback || cleanStr(it.md).toUpperCase() || cleanStr(it.m).toUpperCase() || rawName || it.s;
            }
            return label;
        }

        function renderVariantCardHtml(entry) {
            const it = entry.it;
            const skuKey = String(it.s || '').toUpperCase();
            const varLabel = entry.varLabel;
            const matchedFab = (!currentGroupFabricKey) ? findMatchingFabricSwatchForItem(it, grp) : null;
            const matchedWood = (!matchedFab) ? findMatchingWoodSwatchForItem(it, grp) : null;
            let fabricPillHtml = '';
            if (matchedFab && matchedFab.url) {
                const fabThumb = resolveVisualImgSrc(matchedFab.url, 120);
                const fabFid = extractDriveFileId(matchedFab.url);
                fabricPillHtml =
                    '<div class="inv-var-fabric-pill" data-fabric-zoom-url="' + escapeHtml(matchedFab.url) + '" data-fabric-zoom-label="' + escapeHtml('Tela · ' + matchedFab.label) + '" title="Ver tela">' +
                        '<img class="inv-var-fabric-thumb" src="' + escapeHtml(fabThumb) + '" alt="' + escapeHtml(matchedFab.label) + '" loading="lazy" decoding="async" referrerpolicy="no-referrer"' +
                        (fabFid ? (' data-fid="' + escapeHtml(fabFid) + '"') : '') +
                        ' onerror="window.__invHandleSwatchImgError&&window.__invHandleSwatchImgError(this)">' +
                        '<span class="inv-var-fabric-lbl">' + escapeHtml(matchedFab.label) + '</span>' +
                    '</div>';
            } else if (matchedWood && matchedWood.url) {
                const woodThumb = resolveVisualImgSrc(matchedWood.url, 120);
                const woodFid = extractDriveFileId(matchedWood.url);
                fabricPillHtml =
                    '<div class="inv-var-fabric-pill is-wood" data-fabric-zoom-url="' + escapeHtml(matchedWood.url) + '" data-fabric-zoom-label="' + escapeHtml('Madera · ' + matchedWood.label) + '" title="Ver madera">' +
                        '<img class="inv-var-fabric-thumb" src="' + escapeHtml(woodThumb) + '" alt="' + escapeHtml(matchedWood.label) + '" loading="lazy" decoding="async" referrerpolicy="no-referrer"' +
                        (woodFid ? (' data-fid="' + escapeHtml(woodFid) + '"') : '') +
                        ' onerror="window.__invHandleSwatchImgError&&window.__invHandleSwatchImgError(this)">' +
                        '<span class="inv-var-fabric-lbl">🪵 ' + escapeHtml(matchedWood.label) + '</span>' +
                    '</div>';
            }
            return '<div class="inv-row inv-variant-card" data-var-sku="' + escapeHtml(skuKey) + '">' +
                '<div class="inv-card-top-right">' +
                    buildCardCartControlHtml(skuKey) +
                '</div>' +
                buildThumbHtml(it, { card: true, eager: true, boxRatio: 4 / 3 }) +
                '<div class="inv-variant-card-body">' +
                    '<div class="inv-det-uniform-text font-bold uppercase leading-snug" style="color:#1A1816;">' +
                        formatTitleWithPriceHtml(varLabel, it.pr) +
                    '</div>' +
                    '<div class="inv-det-uniform-text font-semibold tracking-wider mt-0.5" style="color:#9E7B4F;">' + escapeHtml(it.s) + '</div>' +
                    fabricPillHtml +
                '</div>' +
            '</div>';
        }

        // Cotizador es vista comercial limpia: la edición de portadas visuales y fotos de tela vive en la App de Subida de Fotos
        const coverBarEl = document.getElementById('detGroupCoverBar');
        if (coverBarEl) {
            coverBarEl.innerHTML = '';
            coverBarEl.classList.add('hidden');
        }

        if (varList) {
            const canGroupByFabricModules = !!(grp && grp.typeKey && MODULE_GROUPABLE_TYPE_KEYS.has(grp.typeKey) && grp.items.length >= 2);
            const fabricBucketsByKey = new Map();
            const distinctModKeys = new Set();

            if (canGroupByFabricModules) {
                for (let i = 0; i < grp.items.length; i++) {
                    const it = grp.items[i];
                    const fab = resolveItemFabricVariation(it, grp);
                    const modB = resolveItemModuleBucket(it) || { key: 'OTRO_MODULO', label: 'PIEZA', rank: 99, stripTokens: [] };
                    distinctModKeys.add(modB.key);
                    if (!fabricBucketsByKey.has(fab.key)) {
                        fabricBucketsByKey.set(fab.key, {
                            key: fab.key,
                            label: fab.label,
                            colorHint: fab.colorHint || '',
                            items: []
                        });
                    }
                    const fb = fabricBucketsByKey.get(fab.key);
                    if (!fb.colorHint && fab.colorHint) fb.colorHint = fab.colorHint;
                    fb.items.push({ it: it, mod: modB });
                }
            }

            const useFabricModuleSections = canGroupByFabricModules && (distinctModKeys.size >= 2 || fabricBucketsByKey.size >= 2);

            const canGroupByBedSizeColor = !useFabricModuleSections && !!(grp && grp.typeKey && BED_GROUPABLE_TYPE_KEYS.has(grp.typeKey) && grp.items.length >= 2);

            if (useFabricModuleSections) {
                currentGroupBedSizeKey = '';
                if (currentGroupFabricKey && !fabricBucketsByKey.has(currentGroupFabricKey)) {
                    currentGroupFabricKey = '';
                }
                const orderedFabrics = Array.from(fabricBucketsByKey.values()).sort((a, b) =>
                    (b.items.length - a.items.length) || compareAlphaEs(a.label, b.label)
                );

                if (!currentGroupFabricKey) {
                    // CLICK 2: Selector de Color / Tela con foto de la tela
                    if (crumbEl) {
                        const colTxt = orderedFabrics.length === 1 ? '1 color / tela' : (orderedFabrics.length + ' colores / telas');
                        const modTxt = grp.items.length === 1 ? '1 módulo' : (grp.items.length + ' módulos');
                        crumbEl.textContent = colTxt + ' · ' + modTxt;
                        crumbEl.style.pointerEvents = 'none';
                        crumbEl.style.cursor = 'default';
                        crumbEl.classList.remove('hidden');
                    }
                    currentGroupFabricSingleSkuMap = new Map();
                    const choiceHtml = [];
                    for (let fIdx = 0; fIdx < orderedFabrics.length; fIdx++) {
                        const fb = orderedFabrics[fIdx];
                        const sampleIt = (fb.items && fb.items[0] && fb.items[0].it) || null;
                        if (fb.items && fb.items.length === 1 && sampleIt && sampleIt.s) {
                            currentGroupFabricSingleSkuMap.set(fb.key, sampleIt.s);
                        }
                        const swatchUrl = getFabricSwatchPhotoUrl(fb.key, sampleIt);
                        const swatchSrc = swatchUrl ? resolveVisualImgSrc(swatchUrl, 600) : '';
                        const swatchFid = swatchUrl ? extractDriveFileId(swatchUrl) : '';
                        const modCountTxt = fb.items.length === 1 ? '1 módulo disponible' : (fb.items.length + ' módulos disponibles');
                        const subMeta = fb.colorHint ? (fb.colorHint + ' · ' + modCountTxt) : modCountTxt;

                        const stageInner = swatchSrc
                            ? ('<img class="inv-fabric-choice-img" loading="eager" decoding="async" referrerpolicy="no-referrer" draggable="false" src="' + escapeHtml(swatchSrc) + '" alt="' + escapeHtml(fb.label) + '"' +
                               (swatchFid ? (' data-fid="' + escapeHtml(swatchFid) + '"') : '') +
                               ' onerror="window.__invHandleSwatchImgError&&window.__invHandleSwatchImgError(this)">' +
                               '<button type="button" class="inv-fabric-choice-zoom" data-fabric-zoom-url="' + escapeHtml(swatchUrl) + '" data-fabric-zoom-label="' + escapeHtml('Tela · ' + fb.label) + '" title="Ampliar foto de tela" aria-label="Ampliar foto de tela">🔍</button>')
                            : ('<div class="inv-fabric-choice-empty"><span class="inv-fabric-choice-empty-ico" aria-hidden="true">🧵</span><span>Tela / Color</span></div>');

                        choiceHtml.push(
                            '<div class="inv-row inv-variant-card inv-fabric-choice-card" data-fabric-select-key="' + escapeHtml(fb.key) + '">' +
                                '<div class="inv-fabric-choice-stage">' + stageInner + '</div>' +
                                '<div class="inv-fabric-choice-body">' +
                                    '<div class="inv-fabric-choice-meta">' +
                                        '<div class="inv-fabric-choice-title">' + escapeHtml(fb.label) + '</div>' +
                                        '<div class="inv-fabric-choice-sub">' + escapeHtml(subMeta) + '</div>' +
                                    '</div>' +
                                    '<span class="inv-fabric-choice-arrow">Módulos →</span>' +
                                '</div>' +
                            '</div>'
                        );
                    }
                    varList.innerHTML = choiceHtml.join('');
                } else {
                    // CLICK 3: Módulos disponibles del Color / Tela seleccionado
                    const selectedFb = fabricBucketsByKey.get(currentGroupFabricKey);
                    if (nameEl) {
                        nameEl.textContent = grp.title + ' · ' + selectedFb.label;
                    }
                    if (crumbEl) {
                        crumbEl.textContent = '← Colores / Telas (' + orderedFabrics.length + ')';
                        crumbEl.style.pointerEvents = 'auto';
                        crumbEl.style.cursor = 'pointer';
                        crumbEl.classList.remove('hidden');
                    }

                    const sampleSelIt = (selectedFb.items && selectedFb.items[0] && selectedFb.items[0].it) || null;
                    const swatchUrl = getFabricSwatchPhotoUrl(selectedFb.key, sampleSelIt);
                    const swatchThumb = swatchUrl ? resolveVisualImgSrc(swatchUrl, 160) : '';
                    const swatchSelFid = swatchUrl ? extractDriveFileId(swatchUrl) : '';
                    const modCountTxt = selectedFb.items.length === 1 ? '1 módulo disponible' : (selectedFb.items.length + ' módulos disponibles');
                    const subMeta = selectedFb.colorHint ? (selectedFb.colorHint + ' · ' + modCountTxt) : modCountTxt;
                    const swatchInner = swatchThumb
                        ? '<img src="' + escapeHtml(swatchThumb) + '" alt="' + escapeHtml(selectedFb.label) + '" referrerpolicy="no-referrer"' +
                          (swatchSelFid ? (' data-fid="' + escapeHtml(swatchSelFid) + '"') : '') +
                          ' onerror="window.__invHandleSwatchImgError&&window.__invHandleSwatchImgError(this)">'
                        : '<span aria-hidden="true">🧵</span>';
                    const swatchClasses = 'inv-fabric-swatch' + (swatchThumb ? '' : ' is-empty is-readonly');
                    const swatchAttrs = swatchUrl
                        ? (' data-fabric-zoom-url="' + escapeHtml(swatchUrl) + '" data-fabric-zoom-label="' + escapeHtml('Tela · ' + selectedFb.label) + '" title="Ver foto de la tela"')
                        : ' disabled';

                    const htmlChunks = [
                        '<div class="inv-fabric-selected-bar" data-fabric-key="' + escapeHtml(selectedFb.key) + '">' +
                            '<div class="inv-fabric-head-left">' +
                                '<button type="button" class="' + swatchClasses + '"' + swatchAttrs + '>' + swatchInner + '</button>' +
                                '<div class="inv-fabric-meta">' +
                                    '<span class="inv-fabric-title">' + escapeHtml(selectedFb.label) + '</span>' +
                                    '<span class="inv-fabric-sub">' + escapeHtml(subMeta) + '</span>' +
                                '</div>' +
                            '</div>' +
                            '<button type="button" class="inv-fabric-back-btn" data-fabric-back="1">← Colores</button>' +
                        '</div>'
                    ];

                    const sortedMods = selectedFb.items.slice().sort((a, b) =>
                        (a.mod.rank - b.mod.rank) ||
                        compareAlphaEs(a.mod.label, b.mod.label) ||
                        compareAlphaEs(a.it.n || a.it.s, b.it.n || b.it.s) ||
                        String(a.it.s || '').localeCompare(String(b.it.s || ''))
                    );
                    const modLabelCounts = new Map();
                    for (let mIdx = 0; mIdx < sortedMods.length; mIdx++) {
                        const lbl = sortedMods[mIdx].mod.label;
                        modLabelCounts.set(lbl, (modLabelCounts.get(lbl) || 0) + 1);
                    }
                    for (let mIdx = 0; mIdx < sortedMods.length; mIdx++) {
                        const pair = sortedMods[mIdx];
                        let cardLabel = pair.mod.label;
                        if (modLabelCounts.get(cardLabel) > 1) {
                            const extraDetail = cleanStr(pair.it.m).toUpperCase() || cleanStr(pair.it.md).toUpperCase() || buildVariantLabel(pair.it, grp, pair.mod.stripTokens);
                            if (extraDetail && plainModelToken(extraDetail) !== plainModelToken(selectedFb.label) && cardLabel.indexOf(extraDetail) === -1) {
                                cardLabel = cardLabel + ' · ' + extraDetail;
                            }
                        }
                        htmlChunks.push(renderVariantCardHtml({ it: pair.it, varLabel: cardLabel }));
                    }
                    varList.innerHTML = htmlChunks.join('');
                }
            } else if (canGroupByBedSizeColor) {
                const grpHeadTitle = grp.displayTitle || grp.title;
                const sizeBucketsByKey = new Map();
                const allColorsSet = new Set();
                let allWoodOnly = true;

                for (let i = 0; i < grp.items.length; i++) {
                    const it = grp.items[i];
                    const sz = resolveItemBedSize(it);
                    const col = resolveItemBedColorOrFinish(it, grp);
                    const piece = resolveItemBedPieceInfo(it);
                    allColorsSet.add(col.key);
                    if (!col.isWood) allWoodOnly = false;

                    if (!sizeBucketsByKey.has(sz.key)) {
                        sizeBucketsByKey.set(sz.key, {
                            key: sz.key,
                            label: sz.label,
                            rank: sz.rank,
                            items: [],
                            pieceShortLabels: new Set(),
                            colorsByKey: new Map()
                        });
                    }
                    const sb = sizeBucketsByKey.get(sz.key);
                    sb.items.push(it);
                    if (piece && piece.shortLabel) sb.pieceShortLabels.add(piece.shortLabel);
                    if (!sb.colorsByKey.has(col.key)) {
                        sb.colorsByKey.set(col.key, {
                            key: col.key,
                            label: col.label,
                            colorHint: col.colorHint || '',
                            isWood: !!col.isWood,
                            items: []
                        });
                    }
                    const cb = sb.colorsByKey.get(col.key);
                    if (!cb.colorHint && col.colorHint) cb.colorHint = col.colorHint;
                    if (!col.isWood) cb.isWood = false;
                    cb.items.push({ it: it, piece: piece });
                }

                const orderedSizes = Array.from(sizeBucketsByKey.values()).sort((a, b) =>
                    (a.rank - b.rank) || compareAlphaEs(a.label, b.label)
                );
                for (let sIdx = 0; sIdx < orderedSizes.length; sIdx++) {
                    const sb = orderedSizes[sIdx];
                    sb.orderedColors = Array.from(sb.colorsByKey.values()).sort((a, b) =>
                        (b.items.length - a.items.length) || compareAlphaEs(a.label, b.label)
                    );
                }

                if (currentGroupBedSizeKey && !sizeBucketsByKey.has(currentGroupBedSizeKey)) {
                    currentGroupBedSizeKey = '';
                    currentGroupFabricKey = '';
                }

                const hasMultiSizes = orderedSizes.length >= 2;
                const effectiveSizeKey = hasMultiSizes ? currentGroupBedSizeKey : (orderedSizes[0] ? orderedSizes[0].key : '');

                if (hasMultiSizes && !effectiveSizeKey) {
                    // PASO 1 CAMAS: Selector de Tamaño (Individual, Matrimonial, Queen Size, King Size, etc.)
                    currentGroupFabricKey = '';
                    currentGroupFabricSingleSkuMap = new Map();
                    if (nameEl) nameEl.textContent = grpHeadTitle;
                    if (crumbEl) {
                        const szTxt = orderedSizes.length + ' tamaños';
                        const colCountAll = allColorsSet.size;
                        const colTxt = colCountAll === 1
                            ? (allWoodOnly ? '1 acabado' : '1 color / tela')
                            : (colCountAll + (allWoodOnly ? ' acabados' : ' colores / telas'));
                        const pzTxt = grp.items.length === 1 ? '1 pieza' : (grp.items.length + ' piezas');
                        crumbEl.textContent = szTxt + ' · ' + colTxt + ' · ' + pzTxt;
                        crumbEl.style.pointerEvents = 'none';
                        crumbEl.style.cursor = 'default';
                        crumbEl.classList.remove('hidden');
                    }

                    const sizeHtml = [];
                    for (let sIdx = 0; sIdx < orderedSizes.length; sIdx++) {
                        const sb = orderedSizes[sIdx];
                        const samplePhotoIt = firstPhotoItem(sb.items);
                        const photoUrl = samplePhotoIt ? photoUrlForItem(samplePhotoIt) : '';
                        const photoSrc = photoUrl ? resolveVisualImgSrc(photoUrl, 520) : '';
                        const photoFid = photoUrl ? extractDriveFileId(photoUrl) : '';
                        const sbAllWood = sb.orderedColors.length > 0 && sb.orderedColors.every(c => c.isWood);
                        const colCountTxt = sb.orderedColors.length === 1
                            ? (sbAllWood ? '1 acabado' : '1 color')
                            : (sb.orderedColors.length + (sbAllWood ? ' acabados' : ' colores'));
                        const pieceTxt = Array.from(sb.pieceShortLabels).join(' + ');
                        const pzTxt = sb.items.length === 1 ? '1 pza' : (sb.items.length + ' pzas');
                        const subMeta = [colCountTxt, pieceTxt, pzTxt].filter(Boolean).join(' · ');
                        const arrowTxt = sb.orderedColors.length >= 2
                            ? (sbAllWood ? 'Acabados →' : 'Colores →')
                            : 'Piezas →';

                        const stageInner = photoSrc
                            ? ('<img class="inv-bed-size-img" loading="eager" decoding="async" referrerpolicy="no-referrer" draggable="false" src="' + escapeHtml(photoSrc) + '" alt="' + escapeHtml(grpHeadTitle + ' ' + sb.label) + '"' +
                               (photoFid ? (' data-fid="' + escapeHtml(photoFid) + '"') : '') +
                               ' onerror="window.__invHandleCardImgError&&window.__invHandleCardImgError(this)">')
                            : ('<div class="inv-fabric-choice-empty"><span class="inv-fabric-choice-empty-ico" aria-hidden="true">🛏️</span><span>' + escapeHtml(sb.label) + '</span></div>');

                        sizeHtml.push(
                            '<div class="inv-row inv-variant-card inv-bed-size-card" data-bed-size-select-key="' + escapeHtml(sb.key) + '">' +
                                '<div class="inv-bed-size-stage">' +
                                    '<span class="inv-bed-size-pill">' + escapeHtml(sb.label) + '</span>' +
                                    stageInner +
                                '</div>' +
                                '<div class="inv-fabric-choice-body">' +
                                    '<div class="inv-fabric-choice-meta">' +
                                        '<div class="inv-bed-size-title">' + escapeHtml(sb.label) + '</div>' +
                                        '<div class="inv-fabric-choice-sub">' + escapeHtml(subMeta) + '</div>' +
                                    '</div>' +
                                    '<span class="inv-fabric-choice-arrow">' + escapeHtml(arrowTxt) + '</span>' +
                                '</div>' +
                            '</div>'
                        );
                    }
                    varList.innerHTML = sizeHtml.join('');
                } else {
                    const selectedSb = sizeBucketsByKey.get(effectiveSizeKey) || orderedSizes[0];
                    if (currentGroupFabricKey && !selectedSb.colorsByKey.has(currentGroupFabricKey)) {
                        currentGroupFabricKey = '';
                    }
                    const sbAllWood = selectedSb.orderedColors.length > 0 && selectedSb.orderedColors.every(c => c.isWood);
                    const hasMultiColorsInSize = selectedSb.orderedColors.length >= 2;

                    if (hasMultiColorsInSize && !currentGroupFabricKey) {
                        // PASO 2 CAMAS: Selector de Color de Tela / Acabado Madera dentro del Tamaño
                        if (nameEl) {
                            nameEl.textContent = selectedSb.key === 'UNSPECIFIED'
                                ? grpHeadTitle
                                : (grpHeadTitle + ' · ' + selectedSb.label);
                        }
                        if (crumbEl) {
                            if (hasMultiSizes) {
                                crumbEl.textContent = '← Tamaños (' + orderedSizes.length + ')';
                                crumbEl.style.pointerEvents = 'auto';
                                crumbEl.style.cursor = 'pointer';
                            } else {
                                const colTxt = selectedSb.orderedColors.length + (sbAllWood ? ' acabados' : ' colores / telas');
                                const pzTxt = selectedSb.items.length === 1 ? '1 pieza' : (selectedSb.items.length + ' piezas');
                                crumbEl.textContent = selectedSb.label + ' · ' + colTxt + ' · ' + pzTxt;
                                crumbEl.style.pointerEvents = 'none';
                                crumbEl.style.cursor = 'default';
                            }
                            crumbEl.classList.remove('hidden');
                        }

                        const choiceHtml = [];
                        if (hasMultiSizes) {
                            const barSub = selectedSb.orderedColors.length + (sbAllWood ? ' acabados disponibles' : ' colores / telas disponibles');
                            choiceHtml.push(
                                '<div class="inv-fabric-selected-bar inv-bed-selected-bar" data-bed-size-key="' + escapeHtml(selectedSb.key) + '">' +
                                    '<div class="inv-fabric-head-left">' +
                                        '<span class="inv-bed-size-chip">' + escapeHtml(selectedSb.label) + '</span>' +
                                        '<div class="inv-fabric-meta">' +
                                            '<span class="inv-fabric-sub">' + escapeHtml(barSub) + '</span>' +
                                        '</div>' +
                                    '</div>' +
                                    '<button type="button" class="inv-fabric-back-btn" data-bed-size-back="1">← Tamaños</button>' +
                                '</div>'
                            );
                        }

                        currentGroupFabricSingleSkuMap = new Map();
                        for (let cIdx = 0; cIdx < selectedSb.orderedColors.length; cIdx++) {
                            const fb = selectedSb.orderedColors[cIdx];
                            const sampleIt = (fb.items && fb.items[0] && fb.items[0].it) || null;
                            if (fb.items && fb.items.length === 1 && sampleIt && sampleIt.s) {
                                currentGroupFabricSingleSkuMap.set(fb.key, sampleIt.s);
                            }
                            const swatchUrl = fb.isWood ? getWoodSwatchPhotoUrl(fb.key, sampleIt) : getFabricSwatchPhotoUrl(fb.key, sampleIt);
                            const swatchSrc = swatchUrl ? resolveVisualImgSrc(swatchUrl, 600) : '';
                            const swatchFid = swatchUrl ? extractDriveFileId(swatchUrl) : '';
                            const pzCountTxt = fb.items.length === 1 ? '1 pieza disponible' : (fb.items.length + ' piezas disponibles');
                            const subMeta = fb.colorHint ? (fb.colorHint + ' · ' + pzCountTxt) : (fb.isWood ? ('🪵 Acabado Madera · ' + pzCountTxt) : pzCountTxt);
                            const zoomTitle = fb.isWood ? 'Ampliar foto de madera' : 'Ampliar foto de tela';
                            const zoomPrefix = fb.isWood ? 'Madera · ' : 'Tela · ';

                            const stageInner = swatchSrc
                                ? ('<img class="inv-fabric-choice-img" loading="eager" decoding="async" referrerpolicy="no-referrer" draggable="false" src="' + escapeHtml(swatchSrc) + '" alt="' + escapeHtml(fb.label) + '"' +
                                   (swatchFid ? (' data-fid="' + escapeHtml(swatchFid) + '"') : '') +
                                   ' onerror="window.__invHandleSwatchImgError&&window.__invHandleSwatchImgError(this)">' +
                                   '<button type="button" class="inv-fabric-choice-zoom" data-fabric-zoom-url="' + escapeHtml(swatchUrl) + '" data-fabric-zoom-label="' + escapeHtml(zoomPrefix + fb.label) + '" title="' + zoomTitle + '" aria-label="' + zoomTitle + '">🔍</button>')
                                : (fb.isWood
                                    ? '<div class="inv-fabric-choice-empty"><span class="inv-fabric-choice-empty-ico" aria-hidden="true">🪵</span><span>Acabado Madera</span></div>'
                                    : '<div class="inv-fabric-choice-empty"><span class="inv-fabric-choice-empty-ico" aria-hidden="true">🧵</span><span>Tela / Color</span></div>');

                            choiceHtml.push(
                                '<div class="inv-row inv-variant-card inv-fabric-choice-card" data-fabric-select-key="' + escapeHtml(fb.key) + '">' +
                                    '<div class="inv-fabric-choice-stage">' + stageInner + '</div>' +
                                    '<div class="inv-fabric-choice-body">' +
                                        '<div class="inv-fabric-choice-meta">' +
                                            '<div class="inv-fabric-choice-title">' + escapeHtml(fb.label) + '</div>' +
                                            '<div class="inv-fabric-choice-sub">' + escapeHtml(subMeta) + '</div>' +
                                        '</div>' +
                                        '<span class="inv-fabric-choice-arrow">Piezas →</span>' +
                                    '</div>' +
                                '</div>'
                            );
                        }
                        varList.innerHTML = choiceHtml.join('');
                    } else {
                        // PASO 3 CAMAS: Piezas disponibles (Cama / Base de Cama / Cabecera) para (Tamaño, Color/Madera)
                        const selectedFb = (hasMultiColorsInSize && currentGroupFabricKey)
                            ? selectedSb.colorsByKey.get(currentGroupFabricKey)
                            : selectedSb.orderedColors[0];
                        if (nameEl) {
                            nameEl.textContent = grpHeadTitle + ' · ' + selectedSb.label + ' · ' + selectedFb.label;
                        }
                        if (crumbEl) {
                            if (hasMultiColorsInSize) {
                                crumbEl.textContent = '← ' + (selectedFb.isWood ? 'Acabados' : 'Colores / Telas') + ' (' + selectedSb.orderedColors.length + ') · ' + selectedSb.label;
                                crumbEl.style.pointerEvents = 'auto';
                                crumbEl.style.cursor = 'pointer';
                            } else if (hasMultiSizes) {
                                crumbEl.textContent = '← Tamaños (' + orderedSizes.length + ')';
                                crumbEl.style.pointerEvents = 'auto';
                                crumbEl.style.cursor = 'pointer';
                            } else {
                                crumbEl.textContent = selectedSb.label + ' · ' + selectedFb.label + ' · ' + selectedFb.items.length + ' piezas';
                                crumbEl.style.pointerEvents = 'none';
                                crumbEl.style.cursor = 'default';
                            }
                            crumbEl.classList.remove('hidden');
                        }

                        const sampleSelIt = (selectedFb.items && selectedFb.items[0] && selectedFb.items[0].it) || null;
                        const swatchUrl = selectedFb.isWood ? getWoodSwatchPhotoUrl(selectedFb.key, sampleSelIt) : getFabricSwatchPhotoUrl(selectedFb.key, sampleSelIt);
                        const swatchThumb = swatchUrl ? resolveVisualImgSrc(swatchUrl, 160) : '';
                        const swatchSelFid = swatchUrl ? extractDriveFileId(swatchUrl) : '';
                        const pzCountTxt = selectedFb.items.length === 1 ? '1 pieza disponible' : (selectedFb.items.length + ' piezas disponibles');
                        const subMeta = selectedFb.colorHint ? (selectedFb.colorHint + ' · ' + pzCountTxt) : (selectedFb.isWood ? ('🪵 Acabado Madera · ' + pzCountTxt) : pzCountTxt);
                        const swatchInner = swatchThumb
                            ? '<img src="' + escapeHtml(swatchThumb) + '" alt="' + escapeHtml(selectedFb.label) + '" referrerpolicy="no-referrer"' +
                              (swatchSelFid ? (' data-fid="' + escapeHtml(swatchSelFid) + '"') : '') +
                              ' onerror="window.__invHandleSwatchImgError&&window.__invHandleSwatchImgError(this)">'
                            : '<span aria-hidden="true">' + (selectedFb.isWood ? '🪵' : '🧵') + '</span>';
                        const swatchClasses = 'inv-fabric-swatch' + (swatchThumb ? '' : ' is-empty is-readonly');
                        const selZoomPrefix = selectedFb.isWood ? 'Madera · ' : 'Tela · ';
                        const selZoomTitle = selectedFb.isWood ? 'Ver foto de la madera' : 'Ver foto de la tela';
                        const swatchAttrs = swatchUrl
                            ? (' data-fabric-zoom-url="' + escapeHtml(swatchUrl) + '" data-fabric-zoom-label="' + escapeHtml(selZoomPrefix + selectedFb.label) + '" title="' + selZoomTitle + '"')
                            : ' disabled';
                        let backBtnHtml = '';
                        if (hasMultiColorsInSize) {
                            backBtnHtml = '<button type="button" class="inv-fabric-back-btn" data-fabric-back="1">← ' + (selectedFb.isWood ? 'Acabados' : 'Colores') + '</button>';
                        } else if (hasMultiSizes) {
                            backBtnHtml = '<button type="button" class="inv-fabric-back-btn" data-bed-size-back="1">← Tamaños</button>';
                        }

                        const htmlChunks = [
                            '<div class="inv-fabric-selected-bar inv-bed-selected-bar" data-fabric-key="' + escapeHtml(selectedFb.key) + '" data-bed-size-key="' + escapeHtml(selectedSb.key) + '">' +
                                '<div class="inv-fabric-head-left">' +
                                    '<button type="button" class="' + swatchClasses + '"' + swatchAttrs + '>' + swatchInner + '</button>' +
                                    '<div class="inv-fabric-meta">' +
                                        '<span class="inv-fabric-title">' + escapeHtml(selectedFb.label) + ' <span class="inv-bed-size-chip">' + escapeHtml(selectedSb.label) + '</span></span>' +
                                        '<span class="inv-fabric-sub">' + escapeHtml(subMeta) + '</span>' +
                                    '</div>' +
                                '</div>' +
                                backBtnHtml +
                            '</div>'
                        ];

                        const sortedPieces = selectedFb.items.slice().sort((a, b) =>
                            (a.piece.rank - b.piece.rank) ||
                            compareAlphaEs(a.piece.label, b.piece.label) ||
                            compareAlphaEs(a.it.n || a.it.s, b.it.n || b.it.s) ||
                            String(a.it.s || '').localeCompare(String(b.it.s || ''))
                        );
                        const pieceBuckets = new Map();
                        for (let pIdx = 0; pIdx < sortedPieces.length; pIdx++) {
                            const lbl = sortedPieces[pIdx].piece.label;
                            if (!pieceBuckets.has(lbl)) pieceBuckets.set(lbl, []);
                            pieceBuckets.get(lbl).push(sortedPieces[pIdx]);
                        }
                        for (let pIdx = 0; pIdx < sortedPieces.length; pIdx++) {
                            const pair = sortedPieces[pIdx];
                            let cardLabel = pair.piece.label;
                            const siblings = pieceBuckets.get(cardLabel) || [];
                            if (siblings.length > 1) {
                                // Desambiguación general cuando varias piezas comparten Tamaño + Color + Tipo (ej. madera Parota vs Rosa Morada, Tabaco vs Tacuba, Sin Cinchos)
                                const distinctMds = new Set(siblings.map(s => plainModelToken(cleanStr(s.it.md))).filter(Boolean));
                                const distinctCms = new Set(siblings.map(s => plainModelToken(cleanStr(s.it.cm)).replace(/^LACA\s+/, '')).filter(Boolean));
                                let diffDetail = '';
                                if (distinctMds.size > 1 && cleanStr(pair.it.md)) {
                                    diffDetail = cleanStr(pair.it.md).toUpperCase();
                                } else if (distinctCms.size > 1 && cleanStr(pair.it.cm)) {
                                    diffDetail = cleanStr(pair.it.cm).toUpperCase();
                                } else {
                                    // Buscar tokens diferenciadores únicos en el nombre entre hermanos (ej. "SIN CINCHOS")
                                    const tokenSets = siblings.map(s => new Set(plainModelToken(stripDimensionsFromProductText(s.it.n)).split(/\s+/).filter(Boolean)));
                                    const myTokens = plainModelToken(stripDimensionsFromProductText(pair.it.n)).split(/\s+/).filter(Boolean);
                                    const uniqueToks = myTokens.filter(tok => tokenSets.some(ts => !ts.has(tok)));
                                    if (uniqueToks.length > 0) {
                                        diffDetail = uniqueToks.join(' ');
                                    } else {
                                        const cmVal = cleanStr(pair.it.cm).toUpperCase();
                                        const mdVal = cleanStr(pair.it.md).toUpperCase();
                                        const medVal = cleanStr(pair.it.m).toUpperCase();
                                        diffDetail = cmVal || mdVal || medVal || pair.it.s;
                                    }
                                }
                                if (diffDetail && plainModelToken(diffDetail) !== plainModelToken(selectedFb.label) && cardLabel.indexOf(diffDetail) === -1) {
                                    cardLabel = cardLabel + ' · ' + diffDetail;
                                }
                            }
                            htmlChunks.push(renderVariantCardHtml({ it: pair.it, varLabel: cardLabel }));
                        }
                        varList.innerHTML = htmlChunks.join('');
                    }
                }
            } else {
                currentGroupFabricKey = '';
                currentGroupBedSizeKey = '';
                currentGroupFabricSingleSkuMap = new Map();
                const baseLabels = grp.items.map(it => buildVariantLabel(it, grp, null));
                const labelCounts = new Map();
                for (let i = 0; i < baseLabels.length; i++) {
                    labelCounts.set(baseLabels[i], (labelCounts.get(baseLabels[i]) || 0) + 1);
                }

                const variantEntries = grp.items.map((it, idx) => {
                    let varLabel = baseLabels[idx];
                    const medUpper = cleanStr(it.m).toUpperCase();
                    if (medUpper && labelCounts.get(varLabel) > 1 && varLabel.indexOf(medUpper) === -1) {
                        varLabel = varLabel + ' · ' + medUpper;
                    }
                    return { it: it, varLabel: varLabel };
                });

                variantEntries.sort((a, b) =>
                    compareAlphaEs(a.varLabel, b.varLabel) ||
                    compareAlphaEs(a.it.n || a.it.s, b.it.n || b.it.s) ||
                    String(a.it.s || '').localeCompare(String(b.it.s || ''))
                );

                varList.innerHTML = variantEntries.map(renderVariantCardHtml).join('');
            }

            if (varList.classList) {
                const rawVarHtml = String(varList.innerHTML || '');
                const isCompactChoiceGrid = rawVarHtml.indexOf('inv-fabric-choice-card') !== -1 || rawVarHtml.indexOf('inv-bed-size-card') !== -1;
                varList.classList.toggle('inv-variants-compact-choices', isCompactChoiceGrid);
            }

            varList.querySelectorAll('[data-bed-size-select-key]').forEach(cardEl => {
                cardEl.onclick = function () {
                    const sKey = cardEl.getAttribute('data-bed-size-select-key') || '';
                    if (sKey) window.selectGroupBedSizeStep(sKey);
                };
            });
            varList.querySelectorAll('[data-bed-size-back]').forEach(btnEl => {
                btnEl.onclick = function (ev) {
                    if (ev && ev.stopPropagation) ev.stopPropagation();
                    window.backToCurrentGroupVariants();
                };
            });
            varList.querySelectorAll('[data-fabric-select-key]').forEach(cardEl => {
                cardEl.onclick = function () {
                    const fKey = cardEl.getAttribute('data-fabric-select-key') || '';
                    if (fKey) window.selectGroupFabricStep(fKey);
                };
            });
            varList.querySelectorAll('[data-fabric-back]').forEach(btnEl => {
                btnEl.onclick = function (ev) {
                    if (ev && ev.stopPropagation) ev.stopPropagation();
                    window.backToCurrentGroupVariants();
                };
            });
            varList.querySelectorAll('[data-fabric-zoom-url]').forEach(btnEl => {
                btnEl.onclick = function (ev) {
                    if (ev && ev.stopPropagation) ev.stopPropagation();
                    const zUrl = btnEl.getAttribute('data-fabric-zoom-url');
                    const zLbl = btnEl.getAttribute('data-fabric-zoom-label') || 'Foto de tela';
                    openVisualPhotoLightbox(zUrl, zLbl);
                };
            });
            varList.querySelectorAll('.inv-row[data-var-sku]').forEach(rowEl => {
                const sku = rowEl.getAttribute('data-var-sku');
                rowEl.onclick = function () {
                    openProductDetail(sku, true);
                };
                const ctrlWrap = rowEl.querySelector('[data-sku-ctrl]');
                bindCardCartControlEvents(ctrlWrap, sku);
            });
            if (window.CreataGuard && typeof window.CreataGuard.protectImages === 'function') {
                window.CreataGuard.protectImages(varList);
            }
        }

        if (varStep) varStep.classList.remove('hidden');
        if (singleStep) singleStep.classList.add('hidden');
        prepareRelatedInStockSection(grp && grp.items && grp.items.length ? grp.items[0] : null, false);
    }

    window.selectGroupBedSizeStep = function (sizeKey) {
        if (!currentGroup || !sizeKey) return false;
        currentGroupBedSizeKey = String(sizeKey).trim();
        currentGroupFabricKey = '';
        renderGroupVariantsStep(currentGroup, '', currentGroupBedSizeKey);
        if (!invWorkspaceRestoring) notifyInvBackStatePush('product_bed_size_step');
        return true;
    };

    window.selectGroupFabricStep = function (fabricKey) {
        if (!currentGroup || !fabricKey) return false;
        const cleanKey = String(fabricKey).trim();
        const singleSku = currentGroupFabricSingleSkuMap.get(cleanKey) || '';
        if (singleSku) {
            currentGroupFabricKey = '';
            return openProductDetail(singleSku, true);
        }
        currentGroupFabricKey = cleanKey;
        renderGroupVariantsStep(currentGroup, currentGroupFabricKey, currentGroupBedSizeKey);
        if (!invWorkspaceRestoring) notifyInvBackStatePush('product_fabric_modules');
        return true;
    };

    function resolveActiveGroup(groupKey) {
        if (!groupKey) return null;
        if (activeFilteredGroupsByKey.has(groupKey)) {
            return activeFilteredGroupsByKey.get(groupKey);
        }
        return groupsByKey.get(groupKey) || null;
    }

    window.openGroupModal = function (groupKey, preserveFabricKey) {
        const grp = resolveActiveGroup(groupKey);
        if (!grp) return false;
        if (grp.items.length === 1) {
            currentGroupFabricKey = '';
            currentGroupBedSizeKey = '';
            return openProductDetail(grp.items[0].s, false);
        }

        if (!preserveFabricKey) {
            currentGroupFabricKey = '';
            currentGroupBedSizeKey = '';
        }
        renderGroupVariantsStep(grp);

        const modal = document.getElementById('productDetailModal');
        if (modal) modal.classList.add('open');
        if (!invWorkspaceRestoring && !preserveFabricKey) notifyInvBackStatePush('product_group_modal');
        if (typeof scheduleSaveInvWorkspaceCheckpoint === 'function') {
            scheduleSaveInvWorkspaceCheckpoint();
        }
        refreshLiveSheetNow(false);
        return true;
    };

    window.backToCurrentGroupVariants = function () {
        if (!currentGroup || currentGroup.items.length <= 1) return;
        const singleStep = document.getElementById('detSingleStep');
        const inSingleDetail = !!(currentDetailItem || (singleStep && !singleStep.classList.contains('hidden')));
        if (inSingleDetail) {
            // Desde Detalle de SKU regresar a los Módulos / Piezas del tamaño y color seleccionado
            openGroupModal(currentGroup.key, true);
            return;
        }
        if (currentGroupFabricKey) {
            // Desde Paso 3 regresar a Colores / Telas (conservando tamaño si aplica)
            currentGroupFabricKey = '';
            renderGroupVariantsStep(currentGroup, '', currentGroupBedSizeKey);
            return;
        }
        if (currentGroupBedSizeKey) {
            // Desde Paso 2 (o Paso 3 con 1 solo color) de Camas regresar a Tamaños
            currentGroupBedSizeKey = '';
            renderGroupVariantsStep(currentGroup, '', '');
        }
    };

    // ------------------------------------------------------------------------
    // PASO 2: DETALLE DE VARIANTE SELECCIONADA O ESCANEADA DIRECTO POR SKU
    // ------------------------------------------------------------------------
    window.openProductDetail = function (skuRaw, fromGroupList, allowHidden) {
        const key = String(skuRaw || '').trim().toUpperCase();
        const it = bySkuMap.get(key);
        if (!it) return false;
        // Piezas sin existencia en Bodega/Piso ni LPPT (con precio ERP) no se muestran en el cotizador
        // (solo se permite abrirlas desde una partida que ya estaba en la cotización).
        if (!allowHidden && !isQuotableItem(it)) return false;

        currentDetailItem = it;
        if (!fromGroupList) {
            const grp = resolveActiveGroup(it._groupKey);
            currentGroup = (grp && grp.items.length > 1) ? grp : null;
            currentGroupFabricKey = '';
            currentGroupBedSizeKey = '';
        }

        renderDetailModal(it, !!fromGroupList);

        const varStep = document.getElementById('detVariantsStep');
        const singleStep = document.getElementById('detSingleStep');
        if (varStep) varStep.classList.add('hidden');
        if (singleStep) singleStep.classList.remove('hidden');

        const modal = document.getElementById('productDetailModal');
        if (modal) modal.classList.add('open');
        try {
            const activeEl = document.activeElement;
            if (activeEl && activeEl.id === 'invSearchInput') {
                if (typeof activeEl.select === 'function') activeEl.select();
                if (typeof activeEl.setSelectionRange === 'function') {
                    activeEl.setSelectionRange(0, String(activeEl.value || '').length);
                }
                if (typeof activeEl.blur === 'function') activeEl.blur();
            }
        } catch (eBlur) {}
        if (!invWorkspaceRestoring) notifyInvBackStatePush('product_detail_modal');
        if (typeof scheduleSaveInvWorkspaceCheckpoint === 'function') {
            scheduleSaveInvWorkspaceCheckpoint();
        }
        refreshLiveSheetNow(false);
        return true;
    };

    let visualDiscActiveSku = '';

    window.updateDetailVisualDiscount = function () {
        const discBox = document.getElementById('detVisualDiscBox');
        const discInp = document.getElementById('detVisualDiscInput');
        const finalBox = document.getElementById('detVisualFinalBox');
        const finalLbl = document.getElementById('detVisualFinalLabel');
        const finalPriceEl = document.getElementById('detVisualFinalPrice');
        const guestMode = typeof isGuestSession === 'function' && isGuestSession();
        if (guestMode) {
            if (discInp) discInp.value = '';
            if (discBox) discBox.classList.add('hidden');
            if (finalBox) finalBox.classList.add('hidden');
            if (finalPriceEl) finalPriceEl.textContent = '';
            return;
        }
        if (discBox) discBox.classList.remove('hidden');
        if (finalBox) finalBox.classList.remove('hidden');
        if (!finalPriceEl) return;

        const baseNum = currentDetailItem ? parsePriceNum(currentDetailItem.pr) : 0;
        if (baseNum <= 0) {
            finalPriceEl.textContent = '';
            return;
        }

        const rawStr = discInp ? String(discInp.value || '').replace(',', '.').trim() : '';
        let pct = rawStr === '' ? 0 : parseFloat(rawStr);
        if (isNaN(pct) || !isFinite(pct) || pct < 0) {
            pct = 0;
        } else if (pct > 100) {
            pct = 100;
            if (discInp) discInp.value = '100';
        }

        const discountedNum = Math.max(0, Math.round((baseNum * (1 - pct / 100)) * 100) / 100);
        finalPriceEl.textContent = '$' + discountedNum.toLocaleString('en-US', {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2
        });

        const hasActiveDisc = pct > 0;
        if (finalBox) {
            finalBox.style.borderColor = hasActiveDisc ? '#A7F3D0' : '#E1DBC5';
            finalBox.style.background = hasActiveDisc ? '#ECFDF5' : '#FAF9F6';
        }
        if (finalLbl) {
            finalLbl.style.color = hasActiveDisc ? '#065F46' : '#252C32';
        }
        finalPriceEl.style.color = hasActiveDisc ? '#065F46' : '#252C32';
    };

    window.closeProductDetail = function () {
        const modal = document.getElementById('productDetailModal');
        if (modal) modal.classList.remove('open');
        currentDetailItem = null;
        currentGroup = null;
        currentGroupFabricKey = '';
        currentGroupBedSizeKey = '';
        currentGroupFabricSingleSkuMap = new Map();
        relatedStockExpanded = false;
        const relPanel = document.getElementById('detRelatedStockPanel');
        if (relPanel) relPanel.classList.add('hidden');
        visualDiscActiveSku = '';
        if (!invWorkspaceRestoring) {
            pendingWorkspaceDetailRestore = null;
        }
        const discInp = document.getElementById('detVisualDiscInput');
        if (discInp) discInp.value = '';
        if (typeof scheduleSaveInvWorkspaceCheckpoint === 'function') {
            scheduleSaveInvWorkspaceCheckpoint();
        }
    };

    function renderDetailModal(it, showGroupBack) {
        const crumbEl = document.getElementById('detGroupCrumb');
        const skuEl = document.getElementById('detSku');
        const nameEl = document.getElementById('detName');
        const priceWrapEl = document.getElementById('detPriceWrap');
        const priceEl = document.getElementById('detPrice');
        const discInp = document.getElementById('detVisualDiscInput');
        const actionsRow = document.getElementById('detHeaderActionsRow');
        const addPillWrap = document.getElementById('detAddPillWrap');
        const addBtn = document.getElementById('detAddCartBtn');
        const subBtn = document.getElementById('detSubCartBtn');
        const remAllBtn = document.getElementById('detRemoveAllCartBtn');
        const oosBtn = document.getElementById('detOutOfStockRequestBtn');
        const guestMode = typeof isGuestSession === 'function' && isGuestSession();

        if (crumbEl) {
            if (showGroupBack && currentGroup && currentGroup.items.length > 1) {
                const grpLbl = currentGroup.displayTitle || currentGroup.title;
                const crumbParts = [];
                if (currentGroupBedSizeKey) {
                    const szObj = resolveItemBedSize(it);
                    crumbParts.push(szObj && szObj.key === currentGroupBedSizeKey ? szObj.label : currentGroupBedSizeKey);
                }
                if (currentGroupFabricKey) crumbParts.push(currentGroupFabricKey);
                crumbParts.push(grpLbl);
                crumbEl.textContent = '← ' + crumbParts.join(' · ');
                crumbEl.style.pointerEvents = 'auto';
                crumbEl.style.cursor = 'pointer';
                crumbEl.classList.remove('hidden');
            } else {
                crumbEl.textContent = '';
                crumbEl.style.pointerEvents = 'none';
                crumbEl.style.cursor = 'default';
                crumbEl.classList.add('hidden');
            }
        }

        if (skuEl) {
            skuEl.textContent = it.s || '';
            skuEl.classList.toggle('hidden', !it.s);
        }

        const keyUpperForDisc = String(it.s || '').toUpperCase();
        if (visualDiscActiveSku !== keyUpperForDisc || guestMode) {
            visualDiscActiveSku = keyUpperForDisc;
            if (discInp) discInp.value = '';
        }

        const baseTitle = cleanStr(it.n) || cleanStr(it._groupTitle) || it.s || '';
        const formattedPrice = formatPrice(it.pr);
        if (nameEl) {
            nameEl.textContent = baseTitle;
        }
        // Precio adentro del recuadro de inventario + calculadora visual de descuento al costado (oculta para Invitados Solo Ver)
        if (priceEl && priceWrapEl) {
            if (formattedPrice) {
                priceEl.textContent = formattedPrice;
                priceWrapEl.classList.remove('hidden');
                updateDetailVisualDiscount();
            } else {
                priceEl.textContent = '';
                priceWrapEl.classList.add('hidden');
            }
        }

        const key = String(it.s || '').toUpperCase();
        const q = (!guestMode && cart[key]) ? (Number(cart[key].qty) || 0) : 0;
        if (guestMode) {
            if (actionsRow) actionsRow.classList.add('hidden');
            if (addPillWrap) addPillWrap.classList.add('hidden');
            if (addBtn) addBtn.classList.add('hidden');
            if (subBtn) subBtn.classList.add('hidden');
            if (remAllBtn) remAllBtn.classList.add('hidden');
            if (oosBtn) oosBtn.classList.add('hidden');
        } else {
            if (actionsRow) actionsRow.classList.remove('hidden');
            if (addPillWrap) addPillWrap.classList.remove('hidden');
            if (addBtn) {
                addBtn.classList.remove('hidden');
                addBtn.textContent = q > 0 ? ('Agregar (' + q + ')') : 'Agregar';
            }
            if (subBtn) {
                subBtn.classList.toggle('hidden', q <= 0);
            }
            if (remAllBtn) {
                remAllBtn.classList.add('hidden');
            }
            if (oosBtn) {
                oosBtn.classList.remove('hidden');
            }
        }

        // Cuadro de foto renderizado en canvas protegido con auto-encuadre parejo (78%)
        const driveId = extractDriveFileId(it.f);
        const photoUrl = driveId ? ('https://lh3.googleusercontent.com/d/' + driveId + '=w1000') : resolveDriveOrImgUrl(it.f);
        const stageEl = document.getElementById('detPhotoCanvasStage');
        const imgEl = document.getElementById('detPhotoImg');
        const emptyEl = document.getElementById('detPhotoEmpty');
        if (imgEl) {
            imgEl.onerror = null;
            imgEl.onload = null;
            imgEl.src = '';
            imgEl.style.removeProperty('--opt-scale');
            imgEl.style.removeProperty('--opt-tx');
            imgEl.style.removeProperty('--opt-ty');
            imgEl.classList.add('hidden');
        }
        if (photoUrl && !(driveId && failedDrivePhotoIds.has(driveId))) {
            if (emptyEl) emptyEl.classList.add('hidden');
            if (stageEl && window.CreataGuard && typeof window.CreataGuard.renderCanvasImage === 'function') {
                stageEl.innerHTML = '';
                stageEl.classList.remove('hidden');
                window.CreataGuard.renderCanvasImage(stageEl, photoUrl, baseTitle, function (reason) {
                    const reasonMsg = typeof reason === 'string' ? reason : (reason && reason.message ? String(reason.message) : '');
                    if (reasonMsg === 'image_load_error') {
                        if (driveId) failedDrivePhotoIds.add(driveId);
                        stageEl.innerHTML = '';
                        stageEl.classList.add('hidden');
                        if (emptyEl) emptyEl.classList.remove('hidden');
                    }
                }, { autoFrame: true, targetFill: OPTFIT_TARGET_FILL });
            } else if (imgEl) {
                if (stageEl) {
                    stageEl.innerHTML = '';
                    stageEl.classList.add('hidden');
                }
                imgEl.setAttribute('referrerpolicy', 'no-referrer');
                imgEl.setAttribute('crossorigin', 'anonymous');
                imgEl.setAttribute('draggable', 'false');
                imgEl.setAttribute('data-card-img', '1');
                imgEl.setAttribute('data-box-ratio', (4 / 3).toFixed(4));
                if (driveId) imgEl.setAttribute('data-fid', driveId);
                else imgEl.removeAttribute('data-fid');
                imgEl.onload = function () {
                    if (typeof window.__invOnCardImgLoad === 'function') window.__invOnCardImgLoad(imgEl);
                };
                imgEl.src = photoUrl;
                imgEl.classList.remove('hidden');
                imgEl.onerror = function () {
                    const step = parseInt(imgEl.getAttribute('data-fb-step') || '0', 10);
                    if (driveId && step === 0) {
                        imgEl.setAttribute('data-fb-step', '1');
                        try { imgEl.removeAttribute('crossorigin'); } catch (e) {}
                        imgEl.crossOrigin = null;
                        imgEl.src = 'https://lh3.googleusercontent.com/d/' + encodeURIComponent(driveId) + '=w1000';
                        return;
                    }
                    if (driveId && step === 1) {
                        imgEl.setAttribute('data-fb-step', '2');
                        imgEl.src = 'https://drive.google.com/thumbnail?id=' + encodeURIComponent(driveId) + '&sz=w1000';
                        return;
                    }
                    if (driveId && step === 2) {
                        imgEl.setAttribute('data-fb-step', '3');
                        imgEl.src = 'https://drive.google.com/uc?export=view&id=' + encodeURIComponent(driveId);
                        return;
                    }
                    imgEl.onerror = null;
                    if (driveId) failedDrivePhotoIds.add(driveId);
                    imgEl.classList.add('hidden');
                    if (emptyEl) emptyEl.classList.remove('hidden');
                };
                if (window.CreataGuard && typeof window.CreataGuard.protectImages === 'function') {
                    window.CreataGuard.protectImages(document.getElementById('detPhotoWrap'));
                }
            }
        } else {
            if (stageEl) {
                stageEl.innerHTML = '';
                stageEl.classList.add('hidden');
            }
            if (emptyEl) emptyEl.classList.remove('hidden');
        }

        const sameSkuRefresh = !!(relatedStockRefSku && relatedStockRefSku === key);
        refreshDetailManagerPhotoControls(it, sameSkuRefresh);

        // Stock Total (solo las 10 ubicaciones físicas Bodega/Piso) y Semáforo + LPPT
        const stocks = Array.isArray(it.st) ? it.st : emptyStocks();
        let totalBodegaPiso = 0;
        const whHtml = [];

        for (let i = 0; i < WAREHOUSES.length; i++) {
            const whName = WAREHOUSES[i];
            const isLppt = isLpptWarehouse(whName);
            const qty = Math.max(0, Number(stocks[i]) || 0);
            if (!isLppt) {
                totalBodegaPiso += qty;
            }

            let semClass = 'sem-green';
            let dotColor = '#10B981';
            if (qty <= 0) {
                semClass = 'sem-red';
                dotColor = '#EF4444';
            } else if (qty <= DEFAULT_MIN_STOCK) {
                semClass = 'sem-yellow';
                dotColor = '#F59E0B';
            }

            const spanClass = isLppt ? ' inv-det-info-btn-span' : '';

            if (isLppt && qty > 0) {
                const lpptMsg = formatLpptArrivalText(it, qty);
                whHtml.push(
                    '<div class="inv-det-info-btn ' + semClass + spanClass + '">' +
                        '<span class="inv-det-info-lbl"><span class="inv-det-dot" style="background:' + dotColor + ';"></span><span>' + escapeHtml(lpptMsg) + '</span></span>' +
                        '<span class="inv-det-info-val">' + qty + '</span>' +
                    '</div>'
                );
            } else {
                whHtml.push(
                    '<div class="inv-det-info-btn ' + semClass + spanClass + '">' +
                        '<span class="inv-det-info-lbl"><span class="inv-det-dot" style="background:' + dotColor + ';"></span><span>' + escapeHtml(whName) + '</span></span>' +
                        '<span class="inv-det-info-val">' + qty + '</span>' +
                    '</div>'
                );
            }
        }

        document.getElementById('detTotalStock').textContent = String(totalBodegaPiso);
        document.getElementById('detWarehousesGrid').innerHTML = whHtml.join('');

        // Ficha de información limpia + muestras automáticas de Tela (VFAB:) y Madera (VWOD:)
        const specsWrap = document.getElementById('detSpecsWrap');
        const specsGrid = document.getElementById('detSpecsGrid');
        const specRows = buildCleanProductSpecRows(it);
        const matchedDetailFabric = findMatchingFabricSwatchForItem(it, currentGroup);
        const matchedDetailWood = findMatchingWoodSwatchForItem(it, currentGroup);
        if (specsGrid) {
            let swatchCardsHtml = '';
            if (matchedDetailFabric && matchedDetailFabric.url) {
                const fabThumb = resolveVisualImgSrc(matchedDetailFabric.url, 180);
                const fabFid = extractDriveFileId(matchedDetailFabric.url);
                swatchCardsHtml +=
                    '<button type="button" class="inv-det-fabric-swatch-card inv-det-info-btn-span" data-det-fabric-zoom-url="' + escapeHtml(matchedDetailFabric.url) + '" data-det-fabric-zoom-label="' + escapeHtml('Tela · ' + matchedDetailFabric.label) + '" title="Toca para ampliar la tela">' +
                        '<span class="inv-det-fabric-swatch-img-wrap">' +
                            '<img src="' + escapeHtml(fabThumb) + '" alt="' + escapeHtml(matchedDetailFabric.label) + '" loading="eager" decoding="async" referrerpolicy="no-referrer"' +
                            (fabFid ? (' data-fid="' + escapeHtml(fabFid) + '"') : '') +
                            ' onerror="window.__invHandleSwatchImgError&&window.__invHandleSwatchImgError(this)">' +
                        '</span>' +
                        '<span class="inv-det-fabric-swatch-meta">' +
                            '<span class="inv-det-fabric-swatch-tag">🧵 Tela</span>' +
                            '<span class="inv-det-fabric-swatch-name">' + escapeHtml(matchedDetailFabric.label) + '</span>' +
                        '</span>' +
                        '<span class="inv-det-fabric-swatch-zoom">🔍 Ver</span>' +
                    '</button>';
            }
            if (matchedDetailWood && matchedDetailWood.url) {
                const woodThumb = resolveVisualImgSrc(matchedDetailWood.url, 180);
                const woodFid = extractDriveFileId(matchedDetailWood.url);
                swatchCardsHtml +=
                    '<button type="button" class="inv-det-fabric-swatch-card is-wood inv-det-info-btn-span" data-det-fabric-zoom-url="' + escapeHtml(matchedDetailWood.url) + '" data-det-fabric-zoom-label="' + escapeHtml('Madera · ' + matchedDetailWood.label) + '" title="Toca para ampliar la madera">' +
                        '<span class="inv-det-fabric-swatch-img-wrap">' +
                            '<img src="' + escapeHtml(woodThumb) + '" alt="' + escapeHtml(matchedDetailWood.label) + '" loading="eager" decoding="async" referrerpolicy="no-referrer"' +
                            (woodFid ? (' data-fid="' + escapeHtml(woodFid) + '"') : '') +
                            ' onerror="window.__invHandleSwatchImgError&&window.__invHandleSwatchImgError(this)">' +
                        '</span>' +
                        '<span class="inv-det-fabric-swatch-meta">' +
                            '<span class="inv-det-fabric-swatch-tag">🪵 Madera</span>' +
                            '<span class="inv-det-fabric-swatch-name">' + escapeHtml(matchedDetailWood.label) + '</span>' +
                        '</span>' +
                        '<span class="inv-det-fabric-swatch-zoom">🔍 Ver</span>' +
                    '</button>';
            }
            specsGrid.innerHTML = swatchCardsHtml + specRows.map(r =>
                '<div class="inv-det-info-btn" style="border-color:#E8E4DE; background:#FAF9F6; color:#252C32;">' +
                    '<span class="inv-det-info-lbl" style="opacity:0.75;">' + escapeHtml(r[0]) + ':</span>' +
                    '<span class="inv-det-info-val">' + escapeHtml(r[1]) + '</span>' +
                '</div>'
            ).join('');
            const zoomBtns = specsGrid.querySelectorAll('[data-det-fabric-zoom-url]');
            if (zoomBtns && zoomBtns.length) {
                zoomBtns.forEach(function (swatchBtn) {
                    swatchBtn.onclick = function (ev) {
                        if (ev && ev.stopPropagation) ev.stopPropagation();
                        openVisualPhotoLightbox(
                            swatchBtn.getAttribute('data-det-fabric-zoom-url') || '',
                            swatchBtn.getAttribute('data-det-fabric-zoom-label') || 'Muestra'
                        );
                    };
                });
            }
        }
        if (specsWrap) specsWrap.classList.toggle('hidden', specRows.length === 0 && !matchedDetailFabric && !matchedDetailWood);

        prepareRelatedInStockSection(it, sameSkuRefresh ? relatedStockExpanded : false);
        if (typeof notifyInvSplitFotosOfSku === 'function' && it && it.s) {
            notifyInvSplitFotosOfSku(it.s);
        }
    }

    function buildCleanProductSpecRows(it) {
        if (!it) return [];
        const normSpec = s => String(s || '')
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toUpperCase()
            .replace(/[^A-Z0-9\s]/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();

        const singularizeEs = s => normSpec(s)
            .split(' ')
            .filter(Boolean)
            .map(w => {
                if (w.length > 4 && w.endsWith('ES') && !/[AEIOU]ES$/.test(w)) return w.slice(0, -2);
                if (w.length > 3 && w.endsWith('S')) return w.slice(0, -1);
                return w;
            })
            .join(' ');

        const sku = cleanStr(it.s);
        const cat = it._cat && it._cat !== 'OTROS' ? cleanStr(it._cat) : cleanStr(it.c);
        let tp = cleanStr(it.tp);
        const mo = cleanStr(it.mo);
        const med = cleanStr(it.m);
        const tl = cleanStr(it.tl);
        let ct = cleanStr(it.ct);
        const md = cleanStr(it.md);
        let cm = cleanStr(it.cm);
        let vr = cleanStr(it.vr);
        const mtRaw = cleanStr(it.mt);

        const normSku = normSpec(sku);
        const normNom = normSpec(stripDimensionsFromProductText(it.n));
        const normCat = normSpec(cat);
        const normTp = normSpec(tp);
        const normMo = normSpec(mo);
        const normTl = normSpec(tl);
        const normCt = normSpec(ct);
        const normMd = normSpec(md);
        const normCm = normSpec(cm);

        // 1) Evitar repetir Tipo de producto si equivale a Categoría (ej. SILLONES vs SILLON)
        if (normCat && normTp && (normCat === normTp || singularizeEs(normCat) === singularizeEs(normTp))) {
            tp = '';
        }

        // 2) Evitar repetir Color de tela cuando ya está contenido en Tela (ej. LUXOR IVORY -> IVORY)
        if (normTl && normCt) {
            const tlPad = ' ' + normTl + ' ';
            const ctWords = normCt.split(' ').filter(Boolean);
            if (normTl === normCt || (ctWords.length > 0 && ctWords.every(w => tlPad.indexOf(' ' + w + ' ') !== -1))) {
                ct = '';
            }
        }

        // 3) Evitar repetir Color de madera cuando ya está contenido en Madera (ej. CHAPA DE NOGAL -> NOGAL)
        if (normMd && normCm) {
            const mdPad = ' ' + normMd + ' ';
            const cmWords = normCm.split(' ').filter(Boolean);
            if (normMd === normCm || (cmWords.length > 0 && cmWords.every(w => mdPad.indexOf(' ' + w + ' ') !== -1))) {
                cm = '';
            }
        }

        // 4) Limpiar Materiales quitando prefijos "TELA:", "MADERA:" y valores ya mostrados en Tela / Madera / Color
        let mtClean = '';
        if (mtRaw) {
            const coveredTokens = new Set(
                [normTl, normCt, normMd, normCm]
                    .filter(Boolean)
                    .join(' ')
                    .split(' ')
                    .filter(Boolean)
            );
            const seenMat = new Set();
            const keptParts = [];
            const segments = mtRaw.split(/[,;|\/]+|\s+·\s+/);
            for (let i = 0; i < segments.length; i++) {
                let seg = cleanStr(segments[i])
                    .replace(/^(?:MATERIAL(?:ES)?|ACABADO(?:S)?|TAPIZ(?:ADO)?|TELA|MADERA)\s*:\s*/i, '')
                    .trim();
                if (!seg) continue;
                const nSeg = normSpec(seg);
                if (!nSeg) continue;
                if ((nSeg === 'TELA' || nSeg === 'TAPIZ') && normTl) continue;
                if (nSeg === 'MADERA' && normMd) continue;
                if (nSeg === normTl || nSeg === normCt || nSeg === normMd || nSeg === normCm) continue;
                const segWords = nSeg.split(' ').filter(w => !/^(DE|DEL|LA|EL|EN|CON|Y|TELA|MADERA)$/.test(w));
                if (segWords.length > 0 && segWords.every(w => coveredTokens.has(w))) continue;
                if (seenMat.has(nSeg)) continue;
                seenMat.add(nSeg);
                keptParts.push(seg);
            }
            mtClean = keptParts.join(', ');
        }

        // 5) Conservar Variante siempre que aporte información de la variante (acabado, pieza, tamaño, tela, madera o tono),
        //    omitiendo únicamente "ESTÁNDAR" o repeticiones literales del nombre completo, modelo, tipo o SKU.
        if (vr) {
            const vrSegments = vr.split(/\s*·\s*/).map(cleanStr).filter(Boolean).filter(seg => {
                const nSeg = normSpec(seg);
                if (!nSeg || nSeg === 'ESTANDAR' || nSeg === normNom || nSeg === normMo || nSeg === normTp || nSeg === normSku) {
                    return false;
                }
                return true;
            });
            vr = vrSegments.join(' · ');
        }
        if (!vr) {
            const fallbackVrParts = [];
            if (tl) fallbackVrParts.push(tl);
            if (md) fallbackVrParts.push(md + (cm && normMd.indexOf(normCm) === -1 ? ' ' + cm : ''));
            else if (cm) fallbackVrParts.push(cm);
            if (fallbackVrParts.length > 0) vr = fallbackVrParts.join(' · ');
        }

        const candidateRows = [
            ['SKU / Clave', sku],
            ['Categoría', cat],
            ['Tipo de producto', tp],
            ['Modelo', mo],
            ['Variante', vr],
            ['Medidas', med],
            ['Tela', tl],
            ['Color de tela', ct],
            ['Madera', md],
            ['Color de madera', cm],
            ['Materiales', mtClean]
        ];

        const ALWAYS_KEEP_LABELS = new Set(['SKU / Clave', 'Categoría', 'Modelo', 'Variante', 'Medidas', 'Tela', 'Color de tela', 'Madera', 'Color de madera']);
        const seenBoxValues = new Set();
        const finalRows = [];
        for (let i = 0; i < candidateRows.length; i++) {
            const label = candidateRows[i][0];
            const val = cleanStr(candidateRows[i][1]);
            if (!val) continue;
            const nVal = normSpec(val);
            if (!nVal) continue;
            if (!ALWAYS_KEEP_LABELS.has(label) && seenBoxValues.has(nVal)) continue;
            seenBoxValues.add(nVal);
            finalRows.push([label, val]);
        }
        return finalRows;
    }

    // ------------------------------------------------------------------------
    // SUBIDA DE FOTOS (1:1 STUDIO FRAMING · MULTI-FOTO · TODOS EXCEPTO INVITADOS)
    // ------------------------------------------------------------------------
    let managerPhotoUploadInFlight = false;
    let uploadPhotoPendingFiles = [];
    let uploadPhotoObjectUrls = [];

    const OWNER_FOTOS_EMAIL = 'kevin.reyna@grupoanipa.com';
    const KEVIN_ROLE_PREVIEW_KEY = 'creata_inv_kevin_role_preview_v1';
    const KEVIN_PREVIEW_STORE_KEY = 'creata_inv_kevin_preview_store_v1';
    const CANONICAL_SQUARE_UPLOAD_PX = 2048;

    const ADMIN_PERM_COLUMNS_CLIENT = [
        { colIndex: 9,  header: 'VER_COTIZADOR',          key: 'cotizador',        label: 'Cotizador' },
        { colIndex: 10, header: 'VER_SEGUIMIENTO',        key: 'seguimiento',      label: 'Seguimiento' },
        { colIndex: 11, header: 'VER_HISTORIAL',          key: 'historial',        label: 'Historial' },
        { colIndex: 12, header: 'VER_FOTOS_APP',          key: 'fotosApp',         label: 'App Fotos / Portadas' },
        { colIndex: 13, header: 'VER_PROMPTS_IA',         key: 'promptsIa',        label: 'Prompts IA' },
        { colIndex: 14, header: 'VER_PANEL_SUITE',        key: 'panelSuite',       label: 'Panel Suite' },
        { colIndex: 15, header: 'VER_EQUIPO_Y_INVITADOS', key: 'equipoInvitados',  label: 'Equipo e Invitados' },
        { colIndex: 16, header: 'VER_CAMBIAR_ROL',        key: 'cambiarRol',       label: 'Modo Admin/Asesor' },
        { colIndex: 17, header: 'VER_GESTION_PRODUCTOS',  key: 'gestionProductos', label: 'Gestionar SKUs' },
        { colIndex: 18, header: 'VER_SUBIR_FOTO',         key: 'subirFoto',        label: 'Subir foto' },
        { colIndex: 19, header: 'VER_CAMBIAR_TIENDA',     key: 'cambiarTienda',    label: 'Cambiar tienda' }
    ];

    function defaultAdminPermissionsForEmailClient(emailRaw) {
        const em = String(emailRaw || '').trim().toLowerCase().replace(/,/g, '.');
        const isOwnerKevin = (em === OWNER_FOTOS_EMAIL);
        return {
            cotizador: true,
            seguimiento: true,
            historial: true,
            fotosApp: isOwnerKevin,
            promptsIa: isOwnerKevin,
            panelSuite: isOwnerKevin,
            equipoInvitados: true,
            cambiarRol: true,
            gestionProductos: isOwnerKevin,
            subirFoto: true,
            cambiarTienda: true
        };
    }

    function parseAdminPermCellClient(rawVal, fallbackBool) {
        if (rawVal === true) return true;
        if (rawVal === false) return false;
        const s = String(rawVal === null || rawVal === undefined ? '' : rawVal)
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .trim()
            .toUpperCase();
        if (!s) return !!fallbackBool;
        if (/^(SI|YES|TRUE|1|X|OK|VER|ACTIVO|HABILITADO)$/.test(s)) return true;
        if (/^(NO|FALSE|0|OCULTO|INACTIVO|DESHABILITADO|-)$/.test(s)) return false;
        return !!fallbackBool;
    }

    function extractAdminPermissionsFromRowClient(headerRow, rowArr, emailRaw) {
        const perms = defaultAdminPermissionsForEmailClient(emailRaw);
        const hdr = Array.isArray(headerRow) ? headerRow : [];
        const r = Array.isArray(rowArr) ? rowArr : [];
        const colByKey = {};
        for (let c = 0; c < hdr.length; c++) {
            const norm = String(hdr[c] || '')
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .toUpperCase()
                .replace(/[^A-Z0-9]+/g, '_')
                .replace(/^_+|_+$/g, '');
            if (!norm) continue;
            for (let k = 0; k < ADMIN_PERM_COLUMNS_CLIENT.length; k++) {
                const def = ADMIN_PERM_COLUMNS_CLIENT[k];
                if (norm === def.header || norm.indexOf(def.header) !== -1) {
                    colByKey[def.key] = c;
                }
            }
        }
        for (let k = 0; k < ADMIN_PERM_COLUMNS_CLIENT.length; k++) {
            const def = ADMIN_PERM_COLUMNS_CLIENT[k];
            const idx = (colByKey[def.key] !== undefined) ? colByKey[def.key] : def.colIndex;
            if (idx < r.length) {
                perms[def.key] = parseAdminPermCellClient(r[idx], perms[def.key]);
            }
        }
        return perms;
    }

    const UNIFIED_STORE_COLUMNS_CLIENT = [
        { colIndex: 21, headers: ['COLOCIO', 'COLOSIO', 'TIENDA_COLOCIO', 'TIENDA_COLOSIO'], tab: 'COLOCIO' },
        { colIndex: 22, headers: ['PLAYA', 'TIENDA_PLAYA'], tab: 'PLAYA' },
        { colIndex: 23, headers: ['PTC', 'PUERTO_CANCUN', 'TIENDA_PTC'], tab: 'PTC' },
        { colIndex: 24, headers: ['CASA_CREATA', 'TIENDA_CASA_CREATA'], tab: 'CASA CREATA' },
        { colIndex: 25, headers: ['PROYECTOS', 'TIENDA_PROYECTOS'], tab: 'PROYECTOS' }
    ];

    function inferStoreTabFromAreaClient(areaRaw) {
        const up = String(areaRaw || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toUpperCase();
        if (!up) return '';
        if (up.indexOf('COLOCIO') !== -1 || up.indexOf('COLOSIO') !== -1) return 'COLOCIO';
        if (up.indexOf('PLAYA') !== -1) return 'PLAYA';
        if (up.indexOf('PTC') !== -1 || up.indexOf('PUERTO') !== -1) return 'PTC';
        if (up.indexOf('CASA') !== -1) return 'CASA CREATA';
        if (up.indexOf('PROYECTO') !== -1) return 'PROYECTOS';
        return '';
    }

    function isAdministrativeUnifiedRowClient(correoRaw, areaColB, puestoColD, hasStoreCols) {
        const em = String(correoRaw || '').trim().toLowerCase().replace(/,/g, '.');
        if (typeof ADMIN_MASTER_EMAILS !== 'undefined' && ADMIN_MASTER_EMAILS && ADMIN_MASTER_EMAILS[em]) return true;
        if (em === OWNER_FOTOS_EMAIL || em === 'santiago.torres@grupoanipa.com') return true;
        const areaUp = String(areaColB || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toUpperCase();
        const puestoUp = String(puestoColD || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toUpperCase();
        if (/ADMINISTRACI[OÓ]N|ADMINISTRADOR|ADMIN\s+GENERAL/.test(areaUp)) return true;
        if (/ADMINISTRADOR|ADMINISTRACI[OÓ]N|DIRECCI[OÓ]N|GERENCIA\s+GENERAL/.test(puestoUp)) return true;
        if (!hasStoreCols) {
            if (/(ASESOR|GERENTE\s+DE\s+TIENDA|GERENTE\s+COMERCIAL|COORDINADOR|ARQUITECT|INTERIORISTA)/.test(puestoUp)) return false;
            return true;
        }
        return false;
    }

    function extractAssignedStoresFromRowClient(headerRow, rowArr, areaColB) {
        const hdr = Array.isArray(headerRow) ? headerRow : [];
        const r = Array.isArray(rowArr) ? rowArr : [];
        const colByTab = {};
        let detectedStoreHeader = false;
        for (let c = 0; c < hdr.length; c++) {
            const norm = String(hdr[c] || '')
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .toUpperCase()
                .replace(/[^A-Z0-9]+/g, '_')
                .replace(/^_+|_+$/g, '');
            if (!norm) continue;
            for (let k = 0; k < UNIFIED_STORE_COLUMNS_CLIENT.length; k++) {
                const def = UNIFIED_STORE_COLUMNS_CLIENT[k];
                if (def.headers.indexOf(norm) !== -1) {
                    colByTab[def.tab] = c;
                    detectedStoreHeader = true;
                }
            }
        }
        const hasStoreCols = detectedStoreHeader || r.length >= 22;
        const stores = [];
        if (hasStoreCols) {
            for (let k = 0; k < UNIFIED_STORE_COLUMNS_CLIENT.length; k++) {
                const def = UNIFIED_STORE_COLUMNS_CLIENT[k];
                const idx = (colByTab[def.tab] !== undefined) ? colByTab[def.tab] : def.colIndex;
                if (idx < r.length && parseAdminPermCellClient(r[idx], false) === true) {
                    stores.push(def.tab);
                }
            }
        }
        if (!stores.length) {
            const inferred = inferStoreTabFromAreaClient(areaColB);
            if (inferred) stores.push(inferred);
        }
        return { hasStoreCols: hasStoreCols, stores: stores };
    }

    function isRealAdminAccount() {
        if (!activeAdvisorSession || activeAdvisorSession.mustChangeKey) return false;
        if (typeof isGuestSession === 'function' && isGuestSession()) return false;
        const emailNorm = String(activeAdvisorSession.correo || '').trim().toLowerCase().replace(/,/g, '.');
        return Boolean(activeAdvisorSession.isAdmin || emailNorm === OWNER_FOTOS_EMAIL || emailNorm === 'santiago.torres@grupoanipa.com');
    }

    function getActiveAdminPermissions() {
        if (!isRealAdminAccount()) return null;
        if (activeAdvisorSession && activeAdvisorSession.adminPermissions && typeof activeAdvisorSession.adminPermissions === 'object') {
            return Object.assign(defaultAdminPermissionsForEmailClient(activeAdvisorSession.correo), activeAdvisorSession.adminPermissions);
        }
        return defaultAdminPermissionsForEmailClient(activeAdvisorSession && activeAdvisorSession.correo);
    }

    function hasAdminPerm(permKey) {
        if (!isRealAdminAccount()) return false;
        const perms = getActiveAdminPermissions();
        return !!(perms && perms[permKey] === true);
    }

    function isRealKevinOwner() {
        if (!activeAdvisorSession || activeAdvisorSession.mustChangeKey) return false;
        if (typeof isGuestSession === 'function' && isGuestSession()) return false;
        const emailNorm = String(activeAdvisorSession.correo || '').trim().toLowerCase().replace(/,/g, '.');
        return emailNorm === OWNER_FOTOS_EMAIL;
    }

    function isKevinAdvisorPreviewActive() {
        if (!isRealAdminAccount()) return false;
        if (!isRealKevinOwner() && !hasAdminPerm('cambiarRol')) return false;
        try {
            return typeof sessionStorage !== 'undefined' && sessionStorage.getItem(KEVIN_ROLE_PREVIEW_KEY) === 'ASESOR';
        } catch (e) {
            return false;
        }
    }

    function getKevinAdvisorPreviewStore() {
        try {
            const s = typeof sessionStorage !== 'undefined' ? String(sessionStorage.getItem(KEVIN_PREVIEW_STORE_KEY) || '').trim() : '';
            if (s) return s;
        } catch (e) {}
        return 'CREATA PUERTO CANCUN';
    }

    function isEffectiveAdminSession() {
        if (!activeAdvisorSession || activeAdvisorSession.mustChangeKey) return false;
        if (typeof isGuestSession === 'function' && isGuestSession()) return false;
        if (isKevinAdvisorPreviewActive()) return false;
        return !!activeAdvisorSession.isAdmin;
    }

    function isFotosAppOwner() {
        if (!isEffectiveAdminSession()) return false;
        return hasAdminPerm('fotosApp');
    }

    function canManageProductPhotos() {
        if (!activeAdvisorSession || activeAdvisorSession.mustChangeKey) return false;
        if (typeof isGuestSession === 'function' && isGuestSession()) return false;
        if (isEffectiveAdminSession() && !hasAdminPerm('subirFoto')) return false;
        if (!isEffectiveAdminSession() && activeAdvisorSession.userPermissions && activeAdvisorSession.userPermissions.subirFoto === false) return false;
        return true;
    }

